    // ── Caption style drawer helpers


    /** Common look for the drawer's tappable chips. */
    private void styleDrawerChip(@NonNull TextView chip, float d) {
        chip.setTextColor(0xFFEEEEEE);
        chip.setTextSize(13);
        chip.setShadowLayer(3f * d, 0f, 1f, 0xCC000000);
        int cp = (int)(10*d);
        chip.setPadding(cp, cp/2, cp, cp/2);
        chip.setBackgroundResource(R.drawable.floating_button_item_bg);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT);
        lp.leftMargin = (int)(8*d);
        chip.setLayoutParams(lp);
    }

    @NonNull
    private String fontDisplayName(@NonNull String key) {
        for (String[] c : com.fadcam.ui.faditor.transcript.CaptionStyle.fontChoices()) {
            if (c[0].equals(key)) return c[1];
        }
        return "Standard"; // TODO(strings)
    }

    /**
     * Single position button: three stacked lines, the active one green.
     * Tap cycles Top → Middle → Bottom (replaces the old three-button row).
     */
    @NonNull
    private View makeCaptionPositionToggle(float d) {
        final float[] ys = {0.15f, 0.5f, 0.85f};
        View v = new View(this) {
            @Override
            protected void onDraw(android.graphics.Canvas canvas) {
                super.onDraw(canvas);
                android.graphics.Paint p = new android.graphics.Paint(
                        android.graphics.Paint.ANTI_ALIAS_FLAG);
                p.setStrokeWidth(3 * d);
                p.setStrokeCap(android.graphics.Paint.Cap.ROUND);
                float w = getWidth(), h = getHeight();
                float inset = 10 * d;
                int active = nearestCaptionPositionIndex(ys);
                float[] lineYs = {h * 0.28f, h * 0.5f, h * 0.72f};
                for (int i = 0; i < 3; i++) {
                    p.setColor(i == active ? 0xFF4CAF50 : 0xFF666666);
                    canvas.drawLine(inset, lineYs[i], w - inset, lineYs[i], p);
                }
            }
        };
        int wPx = (int)(52*d), hPx = (int)(40*d);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(wPx, hPx);
        v.setLayoutParams(lp);
        v.setBackgroundResource(R.drawable.floating_button_item_bg);
        v.setContentDescription("Caption position"); // TODO(strings)
        v.setOnClickListener(view -> {
            int next = (nearestCaptionPositionIndex(ys) + 1) % 3;
            applyCaptionPosition(0.5f, ys[next]);
            view.invalidate();
        });
        return v;
    }

    private int nearestCaptionPositionIndex(float[] ys) {
        float cy = 0.85f;
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        if (preferAudio) {
            AudioClip ac = project.getTimeline().getAudioClips().get(editorTimeline.getSelectedAudioIndex());
            cy = ac.getCaptionCenterY();
        } else if (getSelectedClip() != null) {
            cy = getSelectedClip().getCaptionCenterY();
        }
        int best = 2;
        float bestD = Float.MAX_VALUE;
        for (int i = 0; i < ys.length; i++) {
            float dd = Math.abs(ys[i] - cy);
            if (dd < bestD) { bestD = dd; best = i; }
        }
        return best;
    }

    /** The drawer chip's text for a clip's current motion preset. TODO(strings) */
    @NonNull
    private String captionAnimPresetLabel(@NonNull Clip clip) {
        com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset p =
                com.fadcam.ui.faditor.transcript.CaptionAnimator
                        .parsePreset(clip.getCaptionAnimPreset());
        String gran;
        switch (com.fadcam.ui.faditor.transcript.CaptionAnimator
                .parseGranularity(clip.getCaptionAnimGranularity())) {
            case LETTER:   gran = "letter"; break;
            case SENTENCE: gran = "sentence"; break;
            case BLOCK:    gran = "block"; break;
            default:       gran = "word"; break;
        }
        // The per-preset names come from CaptionAnimator.presetLabel, the ONE authority. This
        // switch used to spell them out with a `default: p.name()` fallback, and MATRIX shipped a
        // session reading a bare "MATRIX" because a case was missed. NONE is special-cased because
        // it is a state, not a style — "None · word" would read as an animation with a granularity.
        if (p == com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset.NONE) return "None";
        return com.fadcam.ui.faditor.transcript.CaptionAnimator.presetLabel(p) + " · " + gran;
    }

    /**
     * The reporter's icon for this feature: "an 'A' in motion with motion lines". Drawn rather
     * than picked from the icon font — no ligature in the set is an A with motion lines, and a
     * near-miss glyph on the one entry point to a feature is how the feature stays undiscovered.
     * Same bespoke-View precedent as {@link #makeCaptionPositionToggle}.
     */
    @NonNull
    /** One-line summary of a text box's motion, for the row beside the icon. TODO(strings) */
    private void updateTextMotionState(@NonNull TextView label,
            @NonNull com.fadcam.ui.faditor.model.TextOverlayItem o) {
        com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset p =
                com.fadcam.ui.faditor.transcript.CaptionAnimator
                        .parsePreset(o.getTextAnimPreset());
        if (p == com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset.NONE
                || !o.hasTextAnim()) {
            label.setText("None");
            return;
        }
        int in = Math.round(o.getTextAnimInPct() * 100f);
        int out = Math.round(o.getTextAnimOutPct() * 100f);
        // From the ONE authority. This used to title-case the enum constant, which would have
        // rendered MASK_WIPE as "Mask_wipe" — the same class of defect as the bare "MATRIX" the
        // caption row shipped, and the reason presetLabel exists.
        String name = com.fadcam.ui.faditor.transcript.CaptionAnimator.presetLabel(p);
        // "of this box" rather than a bare percentage, for the same reason the caption readout
        // says "of each line": a bare 50% invites reading it as half the project.
        label.setText(name + " · " + in + "% in / " + out + "% out of this box");
    }

    /**
     * Apply a preset + granularity to a TEXT BOX, in ONE undo step.
     *
     * <p>Seeds an entrance when there is none, exactly as the caption path does: zero zones ARE
     * the off state, so without this every tile in the picker would apply cleanly and change
     * nothing on screen, and the feature would read as broken on first use. Choosing a preset is
     * an explicit request to animate.</p>
     */
    private void applyTextOverlayAnim(
            @NonNull com.fadcam.ui.faditor.model.TextOverlayItem o,
            @NonNull com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset preset,
            @NonNull com.fadcam.ui.faditor.transcript.CaptionAnimator.Granularity gran) {
        final String beforePreset = o.getTextAnimPreset();
        final String beforeGran = o.getTextAnimGranularity();
        final float beforeIn = o.getTextAnimInPct();
        final float beforeOut = o.getTextAnimOutPct();

        final String afterPreset = preset.name();
        final String afterGran = gran.name();
        float seedIn = beforeIn;
        float seedOut = beforeOut;
        // NONE KEEPS THE TIMING. It used to zero both zones, and that was wrong for the reason
        // JoyRaptor gave on 2026-08-21: "people might want to experiment seeing how something looks
        // with an animation, and they might have carefully plotted out the timing, and then they
        // wanna try different times, then try it with none and go back... It seems like a silent
        // way to lose information." Trying None is part of comparing options, not a decision to
        // discard work.
        //
        // Keeping them is SAFE, which is the part that makes this possible: TextBoxRenderer
        // computes `animating = preset != NONE && ...`, so the preset name alone stops the
        // animation and stored zones with NONE selected are simply inert. Nothing renders from
        // them and nothing gets stuck.
        //
        // The bug that originally made None look like a one-way ticket was NOT these zones: it
        // was a leaked editing id pinning `live` true, fixed 2026-08-19. Clearing the zones was
        // my wrong answer to a real symptom, and it traded a rendering bug for silent data loss.
        if (preset != com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset.NONE
                && beforeIn <= 0f && beforeOut <= 0f) {
            seedIn = com.fadcam.ui.faditor.transcript.CaptionAnimator.MAX_ZONE_PCT / 2f;
        }
        final float afterIn = seedIn;
        final float afterOut = seedOut;
        // Compares BOTH zones so a change to either is applied rather than short-circuited.
        if (beforePreset.equals(afterPreset) && beforeGran.equals(afterGran)
                && beforeIn == afterIn && beforeOut == afterOut) {
            return;
        }

        o.setTextAnimPreset(afterPreset);
        o.setTextAnimGranularity(afterGran);
        o.setTextAnimZonePct(afterIn, afterOut);
        final float clampedIn = o.getTextAnimInPct();
        final float clampedOut = o.getTextAnimOutPct();

        undoManager.recordAction(new EditActions.LambdaAction("Text animation", // TODO(strings)
                () -> {
                    o.setTextAnimPreset(afterPreset);
                    o.setTextAnimGranularity(afterGran);
                    o.setTextAnimZonePct(clampedIn, clampedOut);
                    refreshAfterTimerEdit(o);
                },
                () -> {
                    o.setTextAnimPreset(beforePreset);
                    o.setTextAnimGranularity(beforeGran);
                    o.setTextAnimZonePct(beforeIn, beforeOut);
                    refreshAfterTimerEdit(o);
                }));
        refreshAfterTimerEdit(o);
    }

    /** The text overlay behind a timeline item id, or null if it is gone (an undo mid-gesture). */
    @Nullable
    private com.fadcam.ui.faditor.model.TextOverlayItem textOverlayById(@NonNull String itemId) {
        if (project == null) return null;
        for (com.fadcam.ui.faditor.model.TextOverlayItem o
                : project.getTimeline().getTextOverlays()) {
            if (itemId.equals(o.getId())) return o;
        }
        return null;
    }

    /**
     * Live, un-recorded zone update while a timing caret is being dragged (LEDGER §3h).
     *
     * <p>No undo step and no autosave — a drag fires this on every frame, and one entry per frame
     * would bury the user's real history under the gesture's own. The commit is
     * {@link #applyTextAnimZones}, once, on release. Exactly the split the caption sliders use.</p>
     *
     * <p>Re-seats the playhead rather than rebuilding the overlay views: the zones are read when a
     * view is POSITIONED, not when it is created, so this is the cheap call that actually shows
     * the change. {@code rebuild()} would tear down and recreate every overlay view on every
     * frame of the drag.</p>
     */
    private void previewTextAnimZones(@NonNull String itemId, float inPct, float outPct) {
        com.fadcam.ui.faditor.model.TextOverlayItem o = textOverlayById(itemId);
        if (o == null) return;
        o.setTextAnimZonePct(inPct, outPct);
        setTextOverlayPlayhead(lastPlayheadAbsoluteMs);
    }

    /**
     * Commit a caret gesture: ONE undo step spanning the whole drag.
     *
     * <p>The before-values arrive from the view, captured on the DOWN that grabbed the caret. They
     * cannot be read here instead: by the time this runs the model holds the gesture's own live
     * preview, so "the current value" would undo to the last pixel of the drag rather than to
     * where the drag began.</p>
     */
    private void applyTextAnimZones(@NonNull String itemId, float beforeIn, float beforeOut,
                                    float inPct, float outPct) {
        final com.fadcam.ui.faditor.model.TextOverlayItem o = textOverlayById(itemId);
        if (o == null) return;
        o.setTextAnimZonePct(inPct, outPct);
        final float afterIn = o.getTextAnimInPct();
        final float afterOut = o.getTextAnimOutPct();
        // Put the BEFORE values through the same clamp before comparing, so a gesture that only
        // moved within the clamp's dead zone is recognised as the no-op it is. Float == is safe
        // only because both sides have been through clampZonePct, which maps NaN and -0.0f to
        // positive zero; if that clamp is ever loosened this comparison has to change with it.
        final float clampedBeforeIn =
                com.fadcam.ui.faditor.transcript.CaptionAnimator.clampZonePct(beforeIn);
        final float clampedBeforeOut =
                com.fadcam.ui.faditor.transcript.CaptionAnimator.clampZonePct(beforeOut);
        if (clampedBeforeIn == afterIn && clampedBeforeOut == afterOut) {
            // Nothing changed, but the live preview may have moved and come back — put the model
            // where the caller believes it is and refresh, without writing history.
            setTextOverlayPlayhead(lastPlayheadAbsoluteMs);
            return;
        }
        undoManager.recordAction(new EditActions.LambdaAction("Text animation timing", // TODO(strings)
                () -> {
                    o.setTextAnimZonePct(afterIn, afterOut);
                    refreshAfterTimerEdit(o);
                },
                () -> {
                    o.setTextAnimZonePct(clampedBeforeIn, clampedBeforeOut);
                    refreshAfterTimerEdit(o);
                }));
        refreshAfterTimerEdit(o);
        editorTimeline.invalidate();
    }

    // ── Motion-range window (SPEC_TEXT_DRAWER follow-up, 2026-08-08) ────────────────────────
    // The timeline carrots and the drawer's Start/End-here buttons both write this window; the
    // drawer's buttons are plain writes, the carrots are preview-on-move / commit-on-release with
    // ONE undo step, mirroring the text-anim zone carets exactly.

    /** Live carrot drag — write the window, reseat the playhead (zones are read at position time). */
    private void previewMotionRange(@NonNull String itemId, long startMs, long endMs) {
        com.fadcam.ui.faditor.model.TextOverlayItem o = textOverlayById(itemId);
        if (o == null) return;
        o.setMotionRange(startMs, endMs);
        setTextOverlayPlayhead(lastPlayheadAbsoluteMs);
    }

    /**
     * Commit a carrot drag — ONE undo step. The before-window arrives from the view (captured on
     * DOWN); by release the model already holds the gesture's live preview, so reading the model
     * here would undo to the last pixel of the drag instead of where it began.
     */
    private void applyMotionRange(@NonNull String itemId, long beforeStartMs, long beforeEndMs,
                                  long afterStartMs, long afterEndMs) {
        final com.fadcam.ui.faditor.model.TextOverlayItem o = textOverlayById(itemId);
        if (o == null) return;
        o.setMotionRange(afterStartMs, afterEndMs);
        final long afterS = o.getMotionStartMs();
        final long afterE = o.getMotionEndMs();
        if (beforeStartMs == afterS && beforeEndMs == afterE) {
            setTextOverlayPlayhead(lastPlayheadAbsoluteMs);
            return;
        }
        undoManager.recordAction(new EditActions.LambdaAction(
                getString(R.string.faditor_text_motion_range),
                () -> {
                    o.setMotionRange(afterS, afterE);
                    refreshAfterTimerEdit(o);
                },
                () -> {
                    o.setMotionRange(beforeStartMs, beforeEndMs);
                    refreshAfterTimerEdit(o);
                }));
        refreshAfterTimerEdit(o);
        editorTimeline.invalidate();
    }

    private View makeTextMotionIcon(float d) {
        View v = new View(this) {
            @Override
            protected void onDraw(android.graphics.Canvas canvas) {
                super.onDraw(canvas);
                android.graphics.Paint p = new android.graphics.Paint(
                        android.graphics.Paint.ANTI_ALIAS_FLAG);
                float w = getWidth(), h = getHeight();
                // The "A", pushed right so the motion lines have room to trail it.
                p.setColor(0xFFEEEEEE);
                p.setTextAlign(android.graphics.Paint.Align.CENTER);
                p.setTextSize(h * 0.52f);
                p.setFakeBoldText(true);
                canvas.drawText("A", w * 0.62f, h * 0.68f, p);
                // Three trailing motion lines, shortening and fading with distance.
                p.setStyle(android.graphics.Paint.Style.STROKE);
                p.setStrokeWidth(2f * d);
                p.setStrokeCap(android.graphics.Paint.Cap.ROUND);
                float[] ys = {h * 0.36f, h * 0.52f, h * 0.68f};
                float[] lens = {0.20f, 0.26f, 0.16f};
                int[] alphas = {0x66, 0xAA, 0x44};
                for (int i = 0; i < 3; i++) {
                    p.setColor((alphas[i] << 24) | 0x00EEEEEE);
                    float rx = w * 0.34f;
                    canvas.drawLine(rx - w * lens[i], ys[i], rx, ys[i], p);
                }
            }
        };
        int wPx = (int)(44*d), hPx = (int)(34*d);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(wPx, hPx);
        lp.leftMargin = (int)(8*d);
        v.setLayoutParams(lp);
        v.setBackgroundResource(R.drawable.floating_button_item_bg);
        v.setContentDescription("Text motion"); // TODO(strings)
        return v;
    }

    /** Label + color swatch that opens the palette picker. */
    private void addColorControl(@NonNull LinearLayout row, float d, @NonNull String label,
                                 @NonNull java.util.function.Supplier<Integer> get,
                                 @NonNull java.util.function.IntConsumer set) {
        TextView tl = new TextView(this);
        tl.setText(label);
        tl.setTextColor(0xFFAAAAAA);
        tl.setTextSize(12);
        tl.setShadowLayer(3f * d, 0f, 1f, 0xCC000000);
        tl.setPadding((int)(4*d), 0, 0, 0);
        row.addView(tl);
        View swatch = new View(this);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams((int)(26*d), (int)(26*d));
        lp.leftMargin = (int)(6*d);
        lp.rightMargin = (int)(14*d);
        swatch.setLayoutParams(lp);
        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setCornerRadius(6*d);
        bg.setColor(get.get());
        bg.setStroke((int)(1*d), 0xFF555555);
        swatch.setBackground(bg);
        // LIVE, both ways: dragging any control in the picker re-styles the caption on the
        // preview immediately (tweakCaptionStyle records no undo, so calling it on every tick
        // costs nothing extra), and Cancel replays the original colour back through the same
        // path so the caption returns to exactly what it looked like before the dialog opened.
        swatch.setOnClickListener(v -> com.fadcam.ui.faditor.tools.ColorPickerDialog.show(
                this, label, get.get(), false,
                c -> { if (c != null) { set.accept(c); bg.setColor(c); } },
                c -> { if (c != null) { set.accept(c); bg.setColor(c); } }));
        row.addView(swatch);
    }

