    private float getCurrentCaptionSize() {
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        if (preferAudio) {
            int idx = editorTimeline.getSelectedAudioIndex();
            if (idx >= 0 && idx < project.getTimeline().getAudioClips().size()) {
                return project.getTimeline().getAudioClips().get(idx).getCaptionSizeFraction();
            }
        }
        Clip cc = getSelectedClip();
        return cc != null ? cc.getCaptionSizeFraction() : 0.06f;
    }

    private void applyCaptionStyle(String styleId) {
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        if (preferAudio) {
            int idx = editorTimeline.getSelectedAudioIndex();
            if (idx >= 0 && idx < project.getTimeline().getAudioClips().size()) {
                final AudioClip ac = project.getTimeline().getAudioClips().get(idx);
                final String beforeStyle = ac.getCaptionStyleId();
                final boolean beforeEnabled = ac.isCaptionsEnabled();
                ac.setCaptionStyleId(styleId);
                ac.setCaptionsEnabled(true);
                activeCaptionIsAudio = true;
                audioCaptionClipId = ac.getId();
                bindAudioCaptionData(ac);
                audioCaptionOverlay.setStyle(com.fadcam.ui.faditor.transcript.CaptionStyle.byId(styleId));
                audioCaptionOverlay.setVisibility(View.VISIBLE);
                if (captionStyleBar != null) { captionStyleBarRequested = true; captionStyleBar.setVisibility(View.VISIBLE); }
                if (!styleId.equals(beforeStyle) || !beforeEnabled) {
                    undoManager.recordAction(new EditActions.LambdaAction("Caption style",
                            () -> { ac.setCaptionStyleId(styleId); ac.setCaptionsEnabled(true);
                                    editorTimeline.invalidate(); },
                            () -> { ac.setCaptionStyleId(beforeStyle); ac.setCaptionsEnabled(beforeEnabled);
                                    editorTimeline.invalidate(); }));
                }
                // The CC tape tints by style — repaint NOW, not on the next scrub (JoyRaptor 2026-07-14).
                editorTimeline.invalidate();
                scheduleAutoSave();
            }
        } else {
            final Clip cc = getSelectedClip();
            if (cc != null && cc.hasTranscript()) {
                final String beforeStyle = cc.getCaptionStyleId();
                final boolean beforeEnabled = cc.isCaptionsEnabled();
                cc.setCaptionStyleId(styleId);
                cc.setCaptionsEnabled(true);
                bindCaptionData(cc);
                captionOverlay.setVisibility(View.VISIBLE);
                if (captionStyleBar != null) { captionStyleBarRequested = true; captionStyleBar.setVisibility(View.VISIBLE); }
                if (!styleId.equals(beforeStyle) || !beforeEnabled) {
                    undoManager.recordAction(new EditActions.LambdaAction("Caption style",
                            () -> { cc.setCaptionStyleId(styleId); cc.setCaptionsEnabled(true);
                                    editorTimeline.invalidate(); },
                            () -> { cc.setCaptionStyleId(beforeStyle); cc.setCaptionsEnabled(beforeEnabled);
                                    editorTimeline.invalidate(); }));
                }
                // The CC tape tints by style — repaint NOW, not on the next scrub (JoyRaptor 2026-07-14).
                editorTimeline.invalidate();
                scheduleAutoSave();
            }
        }
    }

    private void applyCaptionPosition(float x, float y) {
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        if (preferAudio) {
            int idx = editorTimeline.getSelectedAudioIndex();
            if (idx >= 0 && idx < project.getTimeline().getAudioClips().size()) {
                final AudioClip ac = project.getTimeline().getAudioClips().get(idx);
                final float beforeX = ac.getCaptionCenterX();
                final float beforeY = ac.getCaptionCenterY();
                ac.setCaptionCenter(x, y);
                bindAudioCaptionData(ac);
                if (beforeX != x || beforeY != y) {
                    undoManager.recordAction(new EditActions.LambdaAction("Caption position",
                            () -> ac.setCaptionCenter(x, y),
                            () -> ac.setCaptionCenter(beforeX, beforeY)));
                }
                scheduleAutoSave();
            }
        } else {
            final Clip cc = getSelectedClip();
            if (cc != null && cc.hasTranscript()) {
                final float beforeX = cc.getCaptionCenterX();
                final float beforeY = cc.getCaptionCenterY();
                cc.setCaptionCenter(x, y);
                bindCaptionData(cc);
                if (beforeX != x || beforeY != y) {
                    undoManager.recordAction(new EditActions.LambdaAction("Caption position",
                            () -> cc.setCaptionCenter(x, y),
                            () -> cc.setCaptionCenter(beforeX, beforeY)));
                }
                scheduleAutoSave();
            }
        }
    }

    private boolean captionSizeSuppressUndo = false;
    private float captionSizeDragBefore = Float.NaN;

    /** Caption size fraction of the currently-selected caption target (audio clip or clip), or NaN. */
    private float currentCaptionSizeOfSelection() {
        int idx = editorTimeline.getSelectedAudioIndex();
        if (idx >= 0 && idx < project.getTimeline().getAudioClips().size())
            return project.getTimeline().getAudioClips().get(idx).getCaptionSizeFraction();
        Clip cc = getSelectedClip();
        return (cc != null && cc.hasTranscript()) ? cc.getCaptionSizeFraction() : Float.NaN;
    }

    /** Record ONE undo for a completed caption-size drag (before -> current), if it changed. */
    private void recordCaptionSizeUndo(float before) {
        if (Float.isNaN(before)) return;
        int idx = editorTimeline.getSelectedAudioIndex();
        if (idx >= 0 && idx < project.getTimeline().getAudioClips().size()) {
            final AudioClip ac = project.getTimeline().getAudioClips().get(idx);
            final float after = ac.getCaptionSizeFraction();
            if (before != after) undoManager.recordAction(new EditActions.LambdaAction("Caption size",
                    () -> ac.setCaptionSizeFraction(after), () -> ac.setCaptionSizeFraction(before)));
            return;
        }
        final Clip cc = getSelectedClip();
        if (cc != null && cc.hasTranscript()) {
            final float after = cc.getCaptionSizeFraction();
            if (before != after) undoManager.recordAction(new EditActions.LambdaAction("Caption size",
                    () -> cc.setCaptionSizeFraction(after), () -> cc.setCaptionSizeFraction(before)));
        }
    }

    private void applyCaptionSize(float size) {
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        if (preferAudio) {
            int idx = editorTimeline.getSelectedAudioIndex();
            if (idx >= 0 && idx < project.getTimeline().getAudioClips().size()) {
                final AudioClip ac = project.getTimeline().getAudioClips().get(idx);
                final float beforeSize = ac.getCaptionSizeFraction();
                ac.setCaptionSizeFraction(size);
                bindAudioCaptionData(ac);
                if (!captionSizeSuppressUndo && beforeSize != size) {
                    undoManager.recordAction(new EditActions.LambdaAction("Caption size",
                            () -> ac.setCaptionSizeFraction(size),
                            () -> ac.setCaptionSizeFraction(beforeSize)));
                }
                scheduleAutoSave();
            }
        } else {
            final Clip cc = getSelectedClip();
            if (cc != null && cc.hasTranscript()) {
                final float beforeSize = cc.getCaptionSizeFraction();
                cc.setCaptionSizeFraction(size);
                bindCaptionData(cc);
                if (!captionSizeSuppressUndo && beforeSize != size) {
                    undoManager.recordAction(new EditActions.LambdaAction("Caption size",
                            () -> cc.setCaptionSizeFraction(size),
                            () -> cc.setCaptionSizeFraction(beforeSize)));
                }
                scheduleAutoSave();
            }
        }
    }

    // ── Text animation (SPEC_TEXT_ANIMATION step 2) ────────────────────
    //
    // The four captionAnim* fields live on Clip only. Audio-clip captions have no animation
    // fields, so the drawer's motion control is hidden rather than shown-and-inert when an audio
    // caption is the selection — a control that silently does nothing is the failure mode this
    // whole area is being cleaned up from.

    /**
     * The clip these controls act on: the selected clip, if it is captioned.
     *
     * <p>Returns null when an AUDIO clip's captions are the current target — the same
     * {@code getSelectedAudioIndex()} test {@code tweakCaptionStyle} uses. Without it the drawer
     * would show a motion control while an audio caption is selected and then apply it to
     * whatever video clip happened to be selected underneath, which is a silent edit to the wrong
     * object.</p>
     */
    @Nullable
    private Clip captionAnimTarget() {
        int audioIdx = editorTimeline.getSelectedAudioIndex();
        if (audioIdx >= 0 && audioIdx < project.getTimeline().getAudioClips().size()) return null;
        Clip c = getSelectedClip();
        return (c != null && c.hasTranscript()) ? c : null;
    }

    /**
     * The caption timing control: two sliders, In and Out, each 0–50% of every caption line.
     *
     * <p><b>Why this is not the tape carets.</b> The carets were the first design and the user
     * rejected them for captions after driving them: <i>"to get a fifty percent fade in, fifty
     * percent fade out, I'm gonna be having to do a lot of dragging over perhaps a thirty minute
     * clip. And that just won't do."</i> Captions ride long videos and arrive line after line, so
     * a per-line gesture on a timeline is the wrong instrument entirely — the value wanted is one
     * value for the whole clip, and it belongs where the rest of the caption's look is authored.
     * The carets remain the right control for a TEXT BOX, which is a single object with a single
     * span you can actually see.</p>
     *
     * <p><b>Why a percentage and not a duration.</b> The same reason the model changed: a
     * duration set once is most of a short line and a flicker on a long one, so it could not be
     * set once at all. 40% is 40% of every line, which is what "set it and forget it" requires.
     * The readout says "% of each line" for that reason — a bare "40%" would invite reading it as
     * 40% of the clip.</p>
     *
     * <p>Dragging previews live but records NOTHING; the undo step is written once on release,
     * against the value the gesture started from. See {@link #previewCaptionAnimZones}.</p>
     */
    private void addCaptionAnimRangeControl(@NonNull LinearLayout root, float d) {
        final Clip target = captionAnimTarget();
        if (target == null) return;

        // The slider's travel is 0..MAX_ZONE_PCT, expressed in whole percent so the readout is a
        // round number and the two ends are exactly 0% and 50%.
        final int maxPercent = Math.round(
                com.fadcam.ui.faditor.transcript.CaptionAnimator.MAX_ZONE_PCT * 100f);

        TextView heading = new TextView(this);
        heading.setText("Timing"); // TODO(strings)
        heading.setTextColor(0xFFAAAAAA);
        heading.setTextSize(12);
        heading.setPadding(0, (int) (8 * d), 0, 0);
        root.addView(heading);

        TextView hint = new TextView(this);
        // Named explicitly because the whole feature turns on it: this is per LINE, not per clip.
        hint.setText("Applied to every caption line, as a share of that line"); // TODO(strings)
        hint.setTextColor(0xFF777777);
        hint.setTextSize(11);
        hint.setPadding(0, (int) (2 * d), 0, (int) (4 * d));
        root.addView(hint);

        final TextView readout = new TextView(this);
        readout.setTextColor(0xFFCCCCCC);
        readout.setTextSize(11);

        // One updater for both sliders so the two readouts can never disagree with the model.
        final Runnable refresh = () -> {
            Clip now = captionAnimTarget();
            if (now == null) return;
            int in = Math.round(now.getCaptionAnimInPct() * 100f);
            int out = Math.round(now.getCaptionAnimOutPct() * 100f);
            // TODO(strings)
            readout.setText("In " + in + "%   Out " + out + "%   of each line"
                    + (in + out >= maxPercent * 2 ? "  ·  in ends as out begins" : ""));
        };

        // G12: In and Out on ONE line — same half treatment as audio fades
        android.widget.LinearLayout timingRow = new android.widget.LinearLayout(this);
        timingRow.setOrientation(android.widget.LinearLayout.HORIZONTAL);
        timingRow.setGravity(android.view.Gravity.CENTER_VERTICAL);
        View inSlider = makeCaptionAnimSlider(timingRow, d, "In", maxPercent,
                Math.round(target.getCaptionAnimInPct() * 100f), true, refresh);
        View outSlider = makeCaptionAnimSlider(timingRow, d, "Out", maxPercent,
                Math.round(target.getCaptionAnimOutPct() * 100f), false, refresh);
        android.widget.LinearLayout.LayoutParams lpIn = new android.widget.LinearLayout.LayoutParams(0, android.widget.LinearLayout.LayoutParams.WRAP_CONTENT, 0.5f);
        android.widget.LinearLayout.LayoutParams lpOut = new android.widget.LinearLayout.LayoutParams(0, android.widget.LinearLayout.LayoutParams.WRAP_CONTENT, 0.5f);
        lpOut.leftMargin = (int)(8*d);
        timingRow.addView(inSlider, lpIn);
        timingRow.addView(outSlider, lpOut);
        root.addView(timingRow);
        readout.setPadding(0, (int) (2 * d), 0, 0);
        root.addView(readout);
        refresh.run();
    }

    /**
     * One labelled 0–50% slider for {@link #addCaptionAnimRangeControl}.
     *
     * @param isIn true for the entrance zone, false for the exit — the ONLY difference between
     *             the two sliders, so they are one method rather than two that can drift apart.
     */
    @NonNull
    private View makeCaptionAnimSlider(@NonNull LinearLayout parent, float d, @NonNull String label,
                                       int maxPercent, int startPercent, boolean isIn,
                                       @NonNull Runnable refresh) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);

        TextView name = new TextView(this);
        name.setText(label); // TODO(strings)
        name.setTextColor(0xFFCCCCCC);
        name.setTextSize(11);
        name.setMinEms(2);
        row.addView(name);

        SeekBar bar = new SeekBar(this);
        bar.setMax(maxPercent);
        bar.setProgress(Math.max(0, Math.min(maxPercent, startPercent)));
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(0,
                LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
        lp.setMargins((int) (6 * d), 0, 0, 0);
        row.addView(bar, lp);

        // Captured on the FIRST touch, not on every change: it is the value the undo step must
        // return to, and the clip's own value is being overwritten by the live preview.
        final float[] gestureStart = new float[2];
        bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(SeekBar sb, int p, boolean fromUser) {
                if (!fromUser) return;
                Clip now = captionAnimTarget();
                if (now == null) return;
                float pct = p / 100f;
                previewCaptionAnimZones(
                        isIn ? pct : now.getCaptionAnimInPct(),
                        isIn ? now.getCaptionAnimOutPct() : pct);
                refresh.run();
            }
            @Override public void onStartTrackingTouch(SeekBar sb) {
                Clip now = captionAnimTarget();
                if (now == null) return;
                gestureStart[0] = now.getCaptionAnimInPct();
                gestureStart[1] = now.getCaptionAnimOutPct();
            }
            @Override public void onStopTrackingTouch(SeekBar sb) {
                Clip now = captionAnimTarget();
                if (now == null) return;
                // Hand the model back to where the gesture started, then commit forward through
                // the one recording path — so the undo step spans the WHOLE drag as one entry
                // rather than the last pixel of it.
                float endIn = now.getCaptionAnimInPct();
                float endOut = now.getCaptionAnimOutPct();
                now.setCaptionAnimZones(gestureStart[0], gestureStart[1]);
                applyCaptionAnimZones(gestureStart[0], gestureStart[1], endIn, endOut);
                refresh.run();
            }
        });
        return row;
    }

    /**
     * Commit an in/out zone change. Values arrive as a FRACTION OF EACH LINE (0…0.5) and go
     * through {@code setCaptionAnimZones}, the one setter, which clamps them.
     *
     * <p>For a caller that has not already moved the clip — a caret drag, which paints its own
     * ghost and commits once on release. A slider is live, so it must use the four-argument form
     * and hand over the values from BEFORE its gesture started; by the time it releases, the
     * clip's current value is its own preview, not the undo target.</p>
     */
    private void applyCaptionAnimZones(float inPct, float outPct) {
        final Clip cc = captionAnimTarget();
        if (cc == null) return;
        applyCaptionAnimZones(cc.getCaptionAnimInPct(), cc.getCaptionAnimOutPct(), inPct, outPct);
    }

    /**
     * Live, un-recorded zone update for a control that previews while it is being dragged. No undo
     * step and no autosave: a slider fires this on every pixel, and one undo entry per pixel would
     * bury the user's real history under a hundred of its own.
     */
    private void previewCaptionAnimZones(float inPct, float outPct) {
        final Clip cc = captionAnimTarget();
        if (cc == null) return;
        cc.setCaptionAnimZones(inPct, outPct);
        bindCaptionData(cc);
    }

    /** @see #applyCaptionAnimZones(float, float) */
    private void applyCaptionAnimZones(float beforeIn, float beforeOut,
                                       float inPct, float outPct) {
        final Clip cc = captionAnimTarget();
        if (cc == null) return;
        cc.setCaptionAnimZones(inPct, outPct);
        final float afterIn = cc.getCaptionAnimInPct();
        final float afterOut = cc.getCaptionAnimOutPct();
        // Float == is safe here ONLY because every value on either side has been through
        // CaptionAnimator.clampZonePct, which maps NaN and -0.0f to positive zero. Without that,
        // NaN != NaN would record a "no-op" undo step on every single commit forever. If the clamp
        // is ever loosened, this comparison has to change with it.
        if (beforeIn == afterIn && beforeOut == afterOut) return;
        // TODO(strings)
        undoManager.recordAction(new EditActions.LambdaAction("Text animation timing",
                () -> { cc.setCaptionAnimZones(afterIn, afterOut); bindCaptionData(cc); },
                () -> { cc.setCaptionAnimZones(beforeIn, beforeOut); bindCaptionData(cc); }));
        bindCaptionData(cc);
        editorTimeline.invalidate();
        scheduleAutoSave();
    }

    /**
     * Choose a preset.
     *
     * <p><b>Picking a preset with both zones at zero seeds an entrance.</b> Zero-length zones ARE
     * the off state — that is the timing model and it is why there is no enable switch — but it
     * means that on a fresh clip every tile in the picker would apply cleanly and change nothing
     * on screen, and the user would reasonably conclude the feature is broken. Choosing a preset
     * is an explicit request to animate, so it seeds half the usable entrance range and leaves the
     * exit at zero. It is one undo step with the preset, and the range control then says exactly
     * what happened.</p>
     */
    private void applyCaptionAnimPreset(
            @NonNull com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset preset) {
        final Clip cc = captionAnimTarget();
        if (cc == null) return;
        final String before = cc.getCaptionAnimPreset();
        final float beforeIn = cc.getCaptionAnimInPct();
        final float beforeOut = cc.getCaptionAnimOutPct();
        final String after = preset.name();

        float seedIn = beforeIn;
        if (preset != com.fadcam.ui.faditor.transcript.CaptionAnimator.Preset.NONE
                && beforeIn <= 0f && beforeOut <= 0f) {
            seedIn = com.fadcam.ui.faditor.transcript.CaptionAnimator.MAX_ZONE_PCT / 2f;
        }
        final float afterIn = seedIn;
        if (before.equals(after) && beforeIn == afterIn) return;

        cc.setCaptionAnimPreset(after);
        cc.setCaptionAnimZones(afterIn, beforeOut);
        final float clampedIn = cc.getCaptionAnimInPct();
        final float clampedOut = cc.getCaptionAnimOutPct();
        // TODO(strings)
        undoManager.recordAction(new EditActions.LambdaAction("Text animation",
                () -> {
                    cc.setCaptionAnimPreset(after);
                    cc.setCaptionAnimZones(clampedIn, clampedOut);
                    bindCaptionData(cc);
                },
                () -> {
                    cc.setCaptionAnimPreset(before);
                    cc.setCaptionAnimZones(beforeIn, beforeOut);
                    bindCaptionData(cc);
                }));
        bindCaptionData(cc);
        editorTimeline.invalidate();
        scheduleAutoSave();
    }

    /** Choose what animates as one unit. Orthogonal to the preset — see SPEC_TEXT_ANIMATION. */
    private void applyCaptionAnimGranularity(
            @NonNull com.fadcam.ui.faditor.transcript.CaptionAnimator.Granularity g) {
        final Clip cc = captionAnimTarget();
        if (cc == null) return;
        final String before = cc.getCaptionAnimGranularity();
        final String after = g.name();
        if (before.equals(after)) return;
        cc.setCaptionAnimGranularity(after);
        // TODO(strings)
        undoManager.recordAction(new EditActions.LambdaAction("Text animation unit",
                () -> { cc.setCaptionAnimGranularity(after); bindCaptionData(cc); },
                () -> { cc.setCaptionAnimGranularity(before); bindCaptionData(cc); }));
        bindCaptionData(cc);
        scheduleAutoSave();
    }

    /** Deep-copy snapshot of a clip's caption-style keyframe list (for undo capture). */
    private java.util.List<Clip.CaptionStyleKeyframe> snapshotCaptionStyleKeyframes(@NonNull Clip cc) {
        java.util.List<Clip.CaptionStyleKeyframe> out = new java.util.ArrayList<>();
        for (Clip.CaptionStyleKeyframe kf : cc.getCaptionStyleKeyframes()) {
            out.add(new Clip.CaptionStyleKeyframe(kf.timeMs, kf.styleId));
        }
        return out;
    }

    /** True when two caption-style keyframe lists are identical (time + styleId, in order). */
    private boolean captionStyleKeyframesEqual(
            @NonNull java.util.List<Clip.CaptionStyleKeyframe> a,
            @NonNull java.util.List<Clip.CaptionStyleKeyframe> b) {
        if (a.size() != b.size()) return false;
        for (int i = 0; i < a.size(); i++) {
            Clip.CaptionStyleKeyframe ka = a.get(i), kb = b.get(i);
            if (ka.timeMs != kb.timeMs || !ka.styleId.equals(kb.styleId)) return false;
        }
        return true;
    }

    /**
     * Record an undo action for a caption-style keyframe edit on {@code cc}, given the
     * before-snapshot captured prior to the mutation. No-op if nothing changed.
     */
    private void recordCaptionStyleKeyframeEdit(
            @NonNull Clip cc, @NonNull java.util.List<Clip.CaptionStyleKeyframe> before) {
        java.util.List<Clip.CaptionStyleKeyframe> after = snapshotCaptionStyleKeyframes(cc);
        if (captionStyleKeyframesEqual(before, after)) return;
        undoManager.recordAction(
                new EditActions.CaptionStyleKeyframesAction(cc, before, after));
    }

    private void saveCurrentVisualizerStyle(
            @NonNull com.fadcam.ui.faditor.model.WaveformOverlayInstance overlay) {
        if (project == null) return;
        String pinned = project.getPinnedAssetDir();
        if (pinned == null) {
            Toast.makeText(this, "Pin a folder first (push-pin icon) to save your look",
                    Toast.LENGTH_SHORT).show();
            return;
        }
        java.util.List<com.fadcam.ui.faditor.model.WaveformStyle> builtins =
                com.fadcam.ui.faditor.waveform.WaveformStyleIO.loadBuiltins(this);
        com.fadcam.ui.faditor.model.WaveformStyle base = null;
        for (com.fadcam.ui.faditor.model.WaveformStyle s : builtins) {
            if (s.id.equals(overlay.getStyleId())) { base = s; break; }
        }
        if (base == null && !builtins.isEmpty()) base = builtins.get(0);
        if (base == null) return;
        // Route through the shared resolver so a CUSTOMIZED layer stack (customStyleJson) is saved,
        // not just the preset+overrides (SPEC_VIZ_ENGINE §4, Layers UI lane).
        com.fadcam.ui.faditor.model.WaveformStyle resolved =
                com.fadcam.ui.faditor.waveform.WaveformStyleIO.resolveEffectiveStyle(overlay, base);
        com.fadcam.ui.faditor.model.WaveformStyle effective = (resolved != null ? resolved : base).copy();
        String stamp = new java.text.SimpleDateFormat("MMdd_HHmmss", java.util.Locale.US)
                .format(new java.util.Date());
        effective.id = "my_viz_" + stamp;
        effective.displayName = "My Visualizer " + stamp;
        String fileName = com.fadcam.ui.faditor.waveform.WaveformStyleIO.saveToPinned(
                this, android.net.Uri.parse(pinned), effective);
        Toast.makeText(this, fileName != null ? "Saved " + fileName + " to your folder"
                : "Save failed", Toast.LENGTH_SHORT).show();
    }

    /** SAF export: writes the overlay's EFFECTIVE style (preset + per-instance overrides applied,
     *  same computation as {@link #saveCurrentVisualizerStyle}) to a user-chosen file anywhere,
     *  as opposed to Save's pinned-project-folder shortcut. */
    private void exportCurrentVisualizerStyle(
            @NonNull com.fadcam.ui.faditor.model.WaveformOverlayInstance overlay) {
        java.util.List<com.fadcam.ui.faditor.model.WaveformStyle> builtins =
                com.fadcam.ui.faditor.waveform.WaveformStyleIO.loadBuiltins(this);
        com.fadcam.ui.faditor.model.WaveformStyle base = null;
        for (com.fadcam.ui.faditor.model.WaveformStyle s : builtins) {
            if (s.id.equals(overlay.getStyleId())) { base = s; break; }
        }
        if (base == null && !builtins.isEmpty()) base = builtins.get(0);
        if (base == null) return;
        // Same shared resolver as Save — export the customized stack when present.
        com.fadcam.ui.faditor.model.WaveformStyle resolved =
                com.fadcam.ui.faditor.waveform.WaveformStyleIO.resolveEffectiveStyle(overlay, base);
        com.fadcam.ui.faditor.model.WaveformStyle effective = (resolved != null ? resolved : base).copy();
        pendingVisualizerExportStyle = effective;
        String fileName = (effective.id == null || effective.id.isEmpty() ? "visualizer" : effective.id)
                + com.fadcam.ui.faditor.waveform.WaveformStyleIO.USER_STYLE_SUFFIX;
        visualizerStyleExportLauncher.launch(fileName);
    }

    /** SAF import: applies an imported {@link com.fadcam.ui.faditor.model.WaveformStyle} JSON
     *  live to {@code target} (the overlay open in the Rolodex) — same effect as picking a
     *  carousel style. Session-only (not persisted); use 💾 Save afterward to pin it. */
    private void onVisualizerStyleImported(
            @NonNull com.fadcam.ui.faditor.model.WaveformOverlayInstance target,
            @NonNull com.fadcam.ui.faditor.model.WaveformStyle imported) {
        target.setStyleId(imported.id);
        if (waveformOverlayView != null) {
            waveformOverlayView.putStyle(imported);
            waveformOverlayView.invalidate();
        }
        scheduleAutoSave();
        Toast.makeText(this, "Imported " + imported.displayName, Toast.LENGTH_SHORT).show();
    }

    /** Synthetic waveform data for rendering style-preview thumbnails (a representative audio shape). */
    private com.fadcam.ui.faditor.model.WaveformData sampleWaveformData() {
        int n = 80, bands = 32;
        float[] amps = new float[n];
        float[][] spec = new float[n][bands];
        for (int i = 0; i < n; i++) {
            amps[i] = (float) (0.25 + 0.6 * Math.abs(Math.sin(i * 0.28))
                    * (0.6 + 0.4 * Math.sin(i * 0.05)));
            for (int b = 0; b < bands; b++) {
                spec[i][b] = (float) (0.15 + 0.7 * Math.abs(Math.sin((i * 0.3) + b * 0.5))
                        * (1.0 - b / (double) bands * 0.7));
            }
        }
        return new com.fadcam.ui.faditor.model.WaveformData(amps, spec, 2000);
    }

