    /**
     * The full row builder. {@code keyframeProp}, when given, swaps the drop-only diamond for
     * the shared {@link KeyframeDiamondControl} (‹ ♦ › with prev/next, tap-drop/delete and
     * long-press ease picker); otherwise the old drop-only {@link #diamondButton} is used.
     */
    @NonNull
    private View buildStyleRow(@NonNull com.fadcam.ui.faditor.model.TextOverlayItem item,
                               @NonNull String label, boolean allowNoneColor,
                               @NonNull java.util.function.Supplier<Integer> getColor,
                               @NonNull java.util.function.Consumer<Integer> setColor,
                               @NonNull java.util.function.Supplier<Integer> getSlider,
                               @NonNull java.util.function.Consumer<Float> setSlider,
                               @NonNull java.util.function.Supplier<Boolean> isArmed,
                               @NonNull Runnable dropKeyframe,
                               @NonNull java.util.function.Supplier<Boolean> mixed,
                               @Nullable java.util.function.Consumer<Runnable> repaintOut,
                               @Nullable ObjectMenuSheet.Prop keyframeProp) {
        float d = getResources().getDisplayMetrics().density;
        int gap = Math.round(8 * d);

        android.widget.LinearLayout row = new android.widget.LinearLayout(this);
        row.setOrientation(android.widget.LinearLayout.HORIZONTAL);
        row.setGravity(android.view.Gravity.CENTER_VERTICAL);
        row.setPadding(0, gap, 0, 0);

        row.addView(colorSwatchButton(d, allowNoneColor, getColor, c -> {
            setColor.accept(c == null ? android.graphics.Color.TRANSPARENT : c);
            refreshOverlayPreview();
            scheduleAutoSave();
        }, label, mixed, repaintOut));

        TextView desc = new TextView(this);
        desc.setText(label);
        desc.setTextColor(0xFFCCCCCC);
        desc.setTextSize(12.5f);
        desc.setPadding(gap, 0, gap, 0);
        desc.setWidth(Math.round(84 * d));
        row.addView(desc);

        android.widget.SeekBar bar = new android.widget.SeekBar(this);
        bar.setMax(100);
        bar.setProgress(Math.max(0, Math.min(100, getSlider.get())));
        bar.setLayoutParams(new android.widget.LinearLayout.LayoutParams(
                0, android.widget.LinearLayout.LayoutParams.WRAP_CONTENT, 1f));
        bar.setOnSeekBarChangeListener(new android.widget.SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(android.widget.SeekBar s, int p, boolean fromUser) {
                if (!fromUser) return;
                setSlider.accept((float) p);
                refreshOverlayPreview();
            }
            @Override public void onStartTrackingTouch(android.widget.SeekBar s) {}
            @Override public void onStopTrackingTouch(android.widget.SeekBar s) { scheduleAutoSave(); }
        });
        row.addView(bar);

        if (keyframeProp != null) {
            row.addView(buildTextDiamond(item, keyframeProp));
        } else {
            row.addView(diamondButton(d, isArmed, dropKeyframe));
        }
        return row;
    }

    /**
     * The keyframe diamond — a filled purple diamond when armed, hollow otherwise, tapping
     * drops/updates a key at the current playhead. Same visual language as
     * {@code FxPanel.diamond}, deliberately not shared code with it: that one keys an
     * {@code FxStack} slot, this one keys a {@code TextOverlayItem} style track, and the two
     * models have no common interface to key against.
     */
    @NonNull
    private View diamondButton(float d, @NonNull java.util.function.Supplier<Boolean> isArmed,
                               @NonNull Runnable onTap) {
        TextView t = new TextView(this) {
            @Override protected void onDraw(android.graphics.Canvas c) {
                super.onDraw(c);
            }
        };
        Runnable refresh = () -> {
            t.setText("◆");
            t.setTextColor(isArmed.get() ? 0xFFB388FF : 0xFF666666);
        };
        refresh.run();
        t.setTextSize(15);
        int pad = Math.round(8 * d);
        t.setPadding(pad, pad, pad, pad);
        t.setOnClickListener(v -> { onTap.run(); refresh.run(); scheduleAutoSave(); });
        return t;
    }

    /**
     * A small round colour-swatch button that opens {@link ColorPickerDialog} — the one picker
     * used for every colour control in the text drawer, live-previewing on every drag and
     * reverting on Cancel per its own contract.
     */
    @NonNull
    private View colorSwatchButton(float d, boolean allowNone,
                                   @NonNull java.util.function.Supplier<Integer> get,
                                   @NonNull java.util.function.Consumer<Integer> onPicked,
                                   @NonNull String title) {
        return colorSwatchButton(d, allowNone, get, onPicked, title, null, null);
    }

    /**
     * {@code mixed}, when non-null, switches the swatch to the W5-2 split "MIXED" mark
     * ({@link MixedSwatchDrawable}) whenever it returns true; {@code repaintOut}, when given,
     * receives the swatch's repaint lambda so a session can refresh it on selection changes.
     */
    @NonNull
    private View colorSwatchButton(float d, boolean allowNone,
                                   @NonNull java.util.function.Supplier<Integer> get,
                                   @NonNull java.util.function.Consumer<Integer> onPicked,
                                   @NonNull String title,
                                   @Nullable java.util.function.Supplier<Boolean> mixed,
                                   @Nullable java.util.function.Consumer<Runnable> repaintOut) {
        View swatch = new View(this);
        int size = Math.round(28 * d);
        android.widget.LinearLayout.LayoutParams lp =
                new android.widget.LinearLayout.LayoutParams(size, size);
        swatch.setLayoutParams(lp);
        Runnable paint = () -> {
            if (mixed != null && mixed.get()) {
                swatch.setBackground(new com.fadcam.ui.faditor.tools.MixedSwatchDrawable());
                return;
            }
            int c = get.get();
            android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
            bg.setShape(android.graphics.drawable.GradientDrawable.OVAL);
            bg.setColor(allowNone && c == android.graphics.Color.TRANSPARENT ? 0x00000000 : c);
            bg.setStroke(Math.round(1.5f * d), 0xFF888888);
            swatch.setBackground(bg);
        };
        paint.run();
        if (repaintOut != null) repaintOut.accept(paint);
        swatch.setOnClickListener(v -> {
            boolean isMixed = mixed != null && mixed.get();
            Integer initial = isMixed ? null
                    : (allowNone && get.get() == android.graphics.Color.TRANSPARENT
                            ? null : get.get());
            // The colour picker (a bottom sheet) and this drawer no longer collide: the text
            // drawer is TOP-down since 2026-08-10, so the old W2-4 horizontal slide-aside is
            // unnecessary here. (The FX panel still needs its own transition — see the FX
            // button, which swaps the drawers.)
            com.fadcam.ui.faditor.tools.ColorPickerDialog.show(this, title, initial, allowNone,
                    c -> { onPicked.accept(c); paint.run(); },
                    c -> { onPicked.accept(c); paint.run(); },
                    null, null);
        });
        return swatch;
    }

    /**
     * The SHADOW row: everything the other STYLE rows have (colour · description · blur slider ·
     * keyframe) PLUS the direction knob and its angle read-out, plus a distance slider — "all of
     * those values will go under the same keyframe" (JoyRaptor), which is
     * {@code TextOverlayItem.addShadowKeyframeAt}: one tap keys angle + distance + blur together.
     */
    @NonNull
    private View buildShadowRow(@NonNull com.fadcam.ui.faditor.model.TextOverlayItem item) {
        float d = getResources().getDisplayMetrics().density;
        int gap = Math.round(8 * d);

        android.widget.LinearLayout box = new android.widget.LinearLayout(this);
        box.setOrientation(android.widget.LinearLayout.VERTICAL);

        // Main row: colour · label · BLUR slider · diamond (the shared row shape).
        box.addView(buildStyleRow(item, getString(R.string.faditor_text_decor_shadow), false,
                item::getShadowColorInt, item::setShadowColorInt,
                () -> Math.round(item.animatedShadowRadiusPx(lastPlayheadAbsoluteMs)),
                v -> item.setShadowRadiusPx(v),
                textStyleProp(item,
                        com.fadcam.ui.faditor.model.TextOverlayItem.TRACK_SHADOW_RADIUS,
                        getString(R.string.faditor_text_decor_shadow), 0f, 100f,
                        item::animatedShadowRadiusPx,
                        (v, ms) -> {
                            item.setShadowRadiusPx(v);
                            if (item.isShadowArmed()) item.addShadowKeyframeAt(ms);
                        },
                        item::isShadowArmed)));

        // Knob + angle read-out + distance slider, all writing the SAME keyframe as the row
        // above when the shadow is armed. Angle and Distance sit on ONE line (user, 2026-08-10:
        // "distance on the same line as the shadow angle") so the row doesn't eat a second line.
        android.widget.LinearLayout knobRow = new android.widget.LinearLayout(this);
        knobRow.setOrientation(android.widget.LinearLayout.HORIZONTAL);
        knobRow.setGravity(android.view.Gravity.CENTER_VERTICAL);
        knobRow.setPadding(0, gap / 2, 0, 0);

        ShadowDirectionKnob knob = new ShadowDirectionKnob(this);
        int knobSize = Math.round(46 * d);
        knobRow.addView(knob, new android.widget.LinearLayout.LayoutParams(knobSize, knobSize));

        TextView angleReadout = new TextView(this);
        angleReadout.setTextColor(0xFFCCCCCC);
        angleReadout.setTextSize(13);
        angleReadout.setPadding(gap, 0, gap, 0);
        Runnable syncAngle = () -> {
            angleReadout.setText(Math.round(item.getShadowAngleDeg()) + "°");
            knob.setAngleDeg(item.getShadowAngleDeg());
        };
        syncAngle.run();
        knobRow.addView(angleReadout);

        // "tap on to enter specific value" — the same look-like-text idiom ColorPickerDialog's
        // H/S/B fields use.
        angleReadout.setOnClickListener(v -> {
            android.widget.EditText in = new android.widget.EditText(this);
            in.setInputType(android.text.InputType.TYPE_CLASS_NUMBER
                    | android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);
            in.setText(String.valueOf(Math.round(item.getShadowAngleDeg())));
            new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                    .setTitle("Shadow angle") // TODO(strings)
                    .setView(in)
                    .setPositiveButton(android.R.string.ok, (dlg, w) -> {
                        try {
                            item.setShadowAngleDeg(Float.parseFloat(in.getText().toString().trim()));
                            if (item.isShadowArmed()) item.addShadowKeyframeAt(lastPlayheadAbsoluteMs);
                            syncAngle.run();
                            refreshOverlayPreview();
                            scheduleAutoSave();
                        } catch (NumberFormatException ignored) { }
                    })
                    .setNegativeButton(android.R.string.cancel, null)
                    .show();
        });

        knob.setOnAngleChanged(angle -> {
            item.setShadowAngleDeg(angle);
            if (item.isShadowArmed()) item.addShadowKeyframeAt(lastPlayheadAbsoluteMs);
            angleReadout.setText(Math.round(item.getShadowAngleDeg()) + "°");
            refreshOverlayPreview();
        });
        knob.setOnAngleCommitted(() -> scheduleAutoSave());

        // Distance slider, same line as the angle (no label row of its own): the label is a
        // short inline word so the two share the one horizontal line without wrapping.
        TextView distLabel = new TextView(this);
        distLabel.setText("Dist"); // TODO(strings)
        distLabel.setTextColor(0xFFAAAAAA);
        distLabel.setTextSize(12);
        distLabel.setPadding(0, 0, gap / 2, 0);
        knobRow.addView(distLabel);
        android.widget.SeekBar distBar = new android.widget.SeekBar(this);
        distBar.setMax(100);
        distBar.setProgress(Math.round(item.animatedShadowDistancePx(lastPlayheadAbsoluteMs)));
        distBar.setOnSeekBarChangeListener(new android.widget.SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(android.widget.SeekBar s, int p, boolean fromUser) {
                if (!fromUser) return;
                item.setShadowDistancePx(p);
                if (item.isShadowArmed()) item.addShadowKeyframeAt(lastPlayheadAbsoluteMs);
                refreshOverlayPreview();
            }
            @Override public void onStartTrackingTouch(android.widget.SeekBar s) {}
            @Override public void onStopTrackingTouch(android.widget.SeekBar s) { scheduleAutoSave(); }
        });
        android.widget.LinearLayout.LayoutParams distLp =
                new android.widget.LinearLayout.LayoutParams(0,
                        android.widget.LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
        knobRow.addView(distBar, distLp);

        box.addView(knobRow);

        return box;
    }

    /**
     * SPEC_TEXT_DRAWER follow-up (2026-08-08): "start motion here / end motion here", visible
     * only when a motion preset is assigned. Writes {@code TextOverlayItem.motionStartMs/EndMs}
     * — a SEPARATE range from the on-screen time range, so a box that is visible for a long
     * stretch can still have a short animation instead of one stretched across its whole
     * duration.
     *
     * <p><b>Known gap, reported rather than hidden:</b> this wires the two buttons and the
     * model fields, but does NOT yet (a) draw the drag-carrot range handles on the timeline
     * block the way loop-animation/slide-trim handles do, nor (b) make the entrance/exit
     * evaluator in {@code TextBoxRenderer}/{@code TextOverlayLayer}/{@code CompositeExportOverlay}
     * actually read this range instead of the object's full start..end span. Both are real
     * remaining work — see the session report.</p>
     */
    /**
     * The single horizontal line that holds the motion-trim chips, the selection status and the
     * delete affordance together (user, 2026-08-10: "start span end | whole clear | trashcan
     * icon"). The motion chips appear only when a motion preset is assigned; the selection
     * status ("Whole text"/"N selected") and Clear chip are always present, exactly as the old
     * status row was — this just puts them on the same line as the range controls to save a row.
     */
    @NonNull
    private View buildTextMotionRangeSection(
            @NonNull com.fadcam.ui.faditor.model.TextOverlayItem item,
            @NonNull TextStyleSession session) {
        float d = getResources().getDisplayMetrics().density;
        int gap = Math.round(6 * d);

        android.widget.LinearLayout row = new android.widget.LinearLayout(this);
        row.setOrientation(android.widget.LinearLayout.HORIZONTAL);
        row.setGravity(android.view.Gravity.CENTER_VERTICAL);
        row.setPadding(0, gap / 2, 0, gap / 2);

        // ── TIME TRIM, first on the line ────────────────────────────────────────────────────
        // Start here / Span whole / End here for the overlay's own visible range, as the three
        // compact purple chips the image drawer uses, ahead of the selection controls. These
        // replace the pair of plain Buttons that sat at the very bottom of the drawer under the
        // opacity slider, where they were both hard to find and styled unlike anything near them.
        // Routed through the SHARED helpers, so the chip, the image drawer's chip and the object
        // sheet's chip cannot disagree about what "End here" means.
        row.addView(markerChip(d, MARKER_COLOR_OBJECT, R.drawable.ic_marker_flag_start,
                getString(R.string.faditor_trim_start_here),
                () -> setOverlayRangeEdgeAtPlayhead(item, true),
                () -> promptForTimeMs(R.string.faditor_trim_start_here, item.getStartMs(),
                        ms -> setOverlayRangeEdgeAtMs(item, true, ms)),
                () -> Math.abs(item.getStartMs() - lastPlayheadAbsoluteMs)
                        < MARKER_CHIP_EPSILON_MS));
        row.addView(markerChip(d, MARKER_COLOR_OBJECT, R.drawable.ic_marker_flag_span,
                getString(R.string.faditor_trim_span_whole),
                () -> spanOverlayOverTimeline(item), null,
                () -> overlaySpansWholeTimeline(item)));
        row.addView(markerChip(d, MARKER_COLOR_OBJECT, R.drawable.ic_marker_flag_end,
                getString(R.string.faditor_trim_end_here),
                () -> setOverlayRangeEdgeAtPlayhead(item, false),
                () -> promptForTimeMs(R.string.faditor_trim_end_here, overlayEndForPrompt(item),
                        ms -> setOverlayRangeEdgeAtMs(item, false, ms)),
                () -> item.getEndMs() != Long.MAX_VALUE
                        && Math.abs(item.getEndMs() - lastPlayheadAbsoluteMs)
                                < MARKER_CHIP_EPSILON_MS));

        // MOTION trim chips — the animation sub-range, not the object's time range.
        //
        // These used to sit on the SAME line as the time trio above, producing two
        // identically-worded "Start here / Span whole / End here" groups on one row, alongside
        // the selection status, Clear and the trash. JoyRaptor, 2026-08-18: 'I'm seeing a second
        // "start here", "spa-" buttons (the last one looks truncated), and I'm not entirely sure
        // what they do.' Both halves of that report are the same defect: the row overflowed, so
        // "Span whole" ellipsised to "Spa-", and nothing on screen said which range the second
        // trio governed.
        //
        // They now get their own labelled line. Same chips, same shared helper, same
        // long-press-to-type behaviour — only the arrangement changed. The label is the part
        // that was actually missing: identical wording is fine once the group says what it
        // applies to.
        android.widget.LinearLayout motionRow = null;
        // (original comment retained below)
        // — the animation sub-range, not the object's time range. Only present
        // when there is an animation to bound, and deliberately AFTER the time chips so the two
        // identically-worded trios are never adjacent.
        if (item.hasTextAnim()) {
            motionRow = new android.widget.LinearLayout(this);
            motionRow.setOrientation(android.widget.LinearLayout.HORIZONTAL);
            motionRow.setGravity(android.view.Gravity.CENTER_VERTICAL);
            motionRow.setPadding(0, 0, 0, gap / 2);
            TextView motionLabel = new TextView(this);
            motionLabel.setText("Animation"); // TODO(strings)
            motionLabel.setTextColor(0xFF9E9E9E);
            motionLabel.setTextSize(11);
            android.widget.LinearLayout.LayoutParams mlp =
                    new android.widget.LinearLayout.LayoutParams(
                            android.widget.LinearLayout.LayoutParams.WRAP_CONTENT,
                            android.widget.LinearLayout.LayoutParams.WRAP_CONTENT);
            mlp.rightMargin = Math.round(8 * d);
            motionRow.addView(motionLabel, mlp);
            // DIMMED WHEN NOT RUNNING. The timings are kept when the preset is None (so comparing
            // options never destroys work), which means the row can now show real numbers for an
            // animation that is switched off. JoyRaptor asked the right question: "are the timings
            // hidden from the user so they dont distract the user into thinking animations are
            // actually live?"
            //
            // Dimmed rather than hidden, deliberately. Hiding them would make the timings feel
            // deleted — the very anxiety that made clearing them wrong — and would take away the
            // ability to adjust timing while auditioning with the animation off. Half opacity
            // reads as "present but inert", which is exactly what they are.
            motionRow.setAlpha(item.isTextAnimActive() ? 1f : 0.45f);
            final android.widget.LinearLayout mRow = motionRow;
            View startBtn = markerChip(d, MARKER_COLOR_MOTION,
                    R.drawable.ic_marker_flag_start,
                    getString(R.string.faditor_motion_start_here), () -> {
                long start = lastPlayheadAbsoluteMs;
                long end = item.hasMotionRange()
                        ? Math.max(item.getMotionEndMs(), start + 1) : item.getEndMs();
                item.setMotionRange(start, end);
                refreshOverlayPreview();
                scheduleAutoSave();
            }, () -> promptForTimeMs(R.string.faditor_motion_start_here,
                    item.motionRangeStartMs(),
                    ms -> { item.setMotionRange(ms, Math.max(ms + 1, item.getMotionEndMs()));
                            refreshOverlayPreview(); scheduleAutoSave(); }),
                    () -> item.hasMotionRange()
                            && Math.abs(item.getMotionStartMs() - lastPlayheadAbsoluteMs)
                                    < MARKER_CHIP_EPSILON_MS);
            mRow.addView(startBtn);

            View spanBtn = markerChip(d, MARKER_COLOR_MOTION,
                    R.drawable.ic_marker_flag_span,
                    getString(R.string.faditor_motion_span_whole), () -> {
                item.clearMotionRange();
                refreshOverlayPreview();
                scheduleAutoSave();
            }, null, () -> !item.hasMotionRange());
            mRow.addView(spanBtn);

            View endBtn = markerChip(d, MARKER_COLOR_MOTION,
                    R.drawable.ic_marker_flag_end,
                    getString(R.string.faditor_motion_end_here), () -> {
                long end = lastPlayheadAbsoluteMs;
                long start = item.hasMotionRange()
                        ? Math.min(item.getMotionStartMs(), end - 1) : item.getStartMs();
                item.setMotionRange(start, end);
                refreshOverlayPreview();
                scheduleAutoSave();
            }, () -> promptForTimeMs(R.string.faditor_motion_end_here,
                    item.motionRangeEndMs(project.getTimeline().getTotalDurationMs()),
                    ms -> { item.setMotionRange(Math.min(item.getMotionStartMs(), ms - 1), ms);
                            refreshOverlayPreview(); scheduleAutoSave(); }),
                    () -> item.hasMotionRange()
                            && Math.abs(item.getMotionEndMs() - lastPlayheadAbsoluteMs)
                                    < MARKER_CHIP_EPSILON_MS);
            mRow.addView(endBtn);

            // THE OTHER TWO TRIANGLES. JoyRaptor counted four markers on the tape and asked whether
            // "the wiring for four buttons was made and only two shown for lack of room" — the
            // honest answer was that the amber entrance/exit carets never had buttons at all, in
            // any amount of room. They do now, and they are the same shapes and colour the tape
            // draws, so the row reads as the tape does. TODO(strings)
            View sep = new View(this);
            sep.setBackgroundColor(0x33FFFFFF);
            android.widget.LinearLayout.LayoutParams slp =
                    new android.widget.LinearLayout.LayoutParams(
                            Math.max(1, Math.round(d)), Math.round(20 * d));
            slp.rightMargin = Math.round(8 * d);
            slp.leftMargin = Math.round(2 * d);
            sep.setLayoutParams(slp);
            mRow.addView(sep);

            mRow.addView(markerChip(d, MARKER_COLOR_ZONE, R.drawable.ic_marker_flag_start,
                    getString(R.string.faditor_zone_in_ends_here),
                    () -> setTextAnimZoneAtPlayhead(item, true), null,
                    () -> zoneMatchesPlayhead(item, true)));
            mRow.addView(markerChip(d, MARKER_COLOR_ZONE, R.drawable.ic_marker_flag_span,
                    getString(R.string.faditor_zone_clear),
                    () -> applyTextAnimZones(item.getId(), item.getTextAnimInPct(),
                            item.getTextAnimOutPct(), 0f, 0f), null,
                    () -> item.getTextAnimInPct() <= 0f && item.getTextAnimOutPct() <= 0f));
            mRow.addView(markerChip(d, MARKER_COLOR_ZONE, R.drawable.ic_marker_flag_end,
                    getString(R.string.faditor_zone_out_starts_here),
                    () -> setTextAnimZoneAtPlayhead(item, false), null,
                    () -> zoneMatchesPlayhead(item, false)));
        }

        // Push the selection controls to the far right, mirroring the image drawer's chips-left /
        // "Clear all keyframes"-right rhythm. Without this the trim chips and the word "delete"
        // run together into one undifferentiated line of small text.
        row.addView(new android.widget.Space(this),
                new android.widget.LinearLayout.LayoutParams(0, 0, 1f));

        // The selection status + Clear chip (folded in from the old status row). "Select all"
        // sits right beside "Clear" so the context makes it clear Clear removes the selection.
        final TextView status = new TextView(this);
        status.setTextColor(0xFF888888);
        status.setTextSize(11);
        status.setMaxLines(1);
        // Ellipsize rather than push: this row's job is to keep the trim chips and the trashcan
        // reachable, and the status is the one thing on it that can lose a character harmlessly.
        status.setEllipsize(android.text.TextUtils.TruncateAt.END);
        row.addView(status);

        TextView clearChip = new TextView(this);
        clearChip.setText(R.string.faditor_text_selection_clear);
        clearChip.setTextColor(0xFFB388FF);
        clearChip.setTextSize(12);
        int cp = Math.round(8 * d);
        clearChip.setPadding(cp, cp / 2, cp, cp / 2);
        clearChip.setOnClickListener(v -> {
            if (session.item.isTimer()) return;
            if (session.hasSelection()) {
                TextStyleResolver.clearRange(session.spans, session.selStart, session.selEnd);
            } else {
                TextStyleResolver.clearAll(session.spans);
            }
            TextStyleResolver.normalize(session.spans, session.len());
            session.refresh.run();
            refreshOverlayPreview();
            scheduleAutoSave();
        });
        row.addView(clearChip);

        // The DELETE affordance at the END of the line, as the TRASHCAN ICON the spec actually
        // asked for — "Start span end | whole clear | trashcan icon" (user, 2026-08-10). It was
        // the literal word "delete" at 16sp, which is the widest thing on a row that now also
        // carries three trim chips: measured on the Note 9 (2026-08-12) it was clipped off the
        // right edge. The icon says the same thing in a fifth of the width, and it is the glyph
        // the bottom toolbox's own Delete tool uses, so the two read as the same verb.
        android.widget.ImageView deleteGlyph = new android.widget.ImageView(this);
        deleteGlyph.setImageResource(R.drawable.ic_delete);
        deleteGlyph.setColorFilter(0xFFE57373);
        int dg = Math.round(6 * d);
        deleteGlyph.setPadding(dg, dg, dg, dg);
        deleteGlyph.setOnClickListener(v -> deleteTextOverlay(item, session));
        row.addView(deleteGlyph, new android.widget.LinearLayout.LayoutParams(
                Math.round(30 * d), Math.round(30 * d)));

        Runnable refresh = () -> {
            if (session.hasSelection()) {
                int n = session.selEnd - session.selStart;
                status.setText(getString(R.string.faditor_text_selection_count, n));
                clearChip.setTextColor(0xFFB388FF);
            } else {
                status.setText(getString(R.string.faditor_text_selection_whole));
                clearChip.setTextColor(0xFF666666);
            }
        };
        session.refreshers.add(refresh);
        refresh.run();
        if (motionRow == null) return row;
        // Two lines only when there IS an animation to bound; an un-animated box keeps the
        // single compact row it always had.
        android.widget.LinearLayout col = new android.widget.LinearLayout(this);
        col.setOrientation(android.widget.LinearLayout.VERTICAL);
        col.addView(row);
        col.addView(motionRow);
        return col;
    }

    /**
     * The compact pill chip used by the motion-range Start/Span/End trim. Styled to match the
     * long-hold context menu's trim options on a text object in the timeline (user, 2026-08-10:
     * "take the start here / end here stylings from the menu I get when I long-hold on the text
     * object in the timeline view. It looks better than the purple lettering") — light text on a
     * dark rounded pill with a subtle border, not purple lettering.
     */
    @NonNull
    /** Colour of the object's own range controls — the green of its trim handles. */
    private static final int MARKER_COLOR_OBJECT = 0xFF4CAF50;
    /** Motion-range markers on the tape. */
    private static final int MARKER_COLOR_MOTION = 0xFFB388FF;
    /** Anim-zone (entrance/exit) carets on the tape. */
    private static final int MARKER_COLOR_ZONE   = 0xFFFFC107;

    /** Idle tint: these read as inert until they have something to say. */
    private static final int MARKER_CHIP_IDLE = 0xFF9E9E9E;
    /** How close the playhead must be to count as "already there" (~1 frame at 25fps). */
    private static final long MARKER_CHIP_EPSILON_MS = 40L;

    /** A chip that can re-evaluate its own "already there" state as the playhead moves. */
    private static final class MarkerChipBinding {
        final java.lang.ref.WeakReference<android.widget.ImageView> ref;
        final int markerColor;
        final java.util.function.BooleanSupplier alreadyThere;
        MarkerChipBinding(android.widget.ImageView v, int c,
                          java.util.function.BooleanSupplier a) {
            this.ref = new java.lang.ref.WeakReference<>(v);
            this.markerColor = c;
            this.alreadyThere = a;
        }
    }

    private final java.util.List<MarkerChipBinding> markerChips = new java.util.ArrayList<>();

    /** Blend toward white — the hover/press brighten. */
    private static int lighten(int c, float amt) {
        int a = (c >>> 24) & 0xFF, r = (c >> 16) & 0xFF, g = (c >> 8) & 0xFF, b = c & 0xFF;
        r = Math.round(r + (255 - r) * amt);
        g = Math.round(g + (255 - g) * amt);
        b = Math.round(b + (255 - b) * amt);
        return (a << 24) | (r << 16) | (g << 8) | b;
    }

    /**
     * A round chip carrying JoyRaptor's checkered-flag icon, for the Start / Span / End controls.
     *
     * <p>JoyRaptor, 2026-08-19: the triangles "are too Vague So I made up little checkered flag icons
     * with arrows to show the starting from a checkered flag, or going to a checkered flag, or a
     * checkered flag expanding". The flag is the destination; the arrow says which way you are
     * going relative to it. The timeline keeps its triangles — those are markers, these are verbs.
     *
     * <p><b>The tint is the whole point of the control.</b> Idle grey means "tapping does
     * something". When the marker this chip drives is ALREADY where a tap would put it, the chip
     * adopts that marker's own colour — green for the object's range, purple for the motion range,
     * amber for the entrance/exit zones — so the answer to "would this change anything?" is
     * readable without tapping to find out. {@code alreadyThere} is re-evaluated on every playhead
     * move, because the answer changes as the playhead does.
     *
     * <p>Press and hover brighten whatever the current tint is, rather than switching to a fixed
     * highlight, so the feedback never contradicts the state.
     *
     * <p>Vector, not PNG: a PNG would need one asset per colour per density, and the colour here
     * is computed at runtime.
     */
    private View markerChip(float d, int markerColor, int iconRes, @NonNull String contentDesc,
                            @NonNull Runnable onTap, @Nullable Runnable onLongPress,
                            @Nullable java.util.function.BooleanSupplier alreadyThere) {
        android.widget.ImageView v = new android.widget.ImageView(this);
        v.setImageResource(iconRes);
        v.setScaleType(android.widget.ImageView.ScaleType.FIT_CENTER);
        // Small padding only — no backing plate. JoyRaptor, 2026-08-19: "let's remove the chip behind.
        // So these things fit together a little bit better". The circle also fought the artwork:
        // each icon fills its own 2048 box edge to edge, so a circle inscribed around it either
        // clipped the arrow or forced the flag smaller than it was drawn to be.
        int pad = Math.round(2 * d);
        v.setPadding(pad, pad, pad, pad);
        v.setContentDescription(contentDesc);

        // Borderless ripple so a tap still registers without a plate to draw it on.
        android.util.TypedValue tv = new android.util.TypedValue();
        if (getTheme().resolveAttribute(
                android.R.attr.selectableItemBackgroundBorderless, tv, true)) {
            v.setBackgroundResource(tv.resourceId);
        }

        v.setOnClickListener(x -> {
            onTap.run();
            refreshMarkerChips();   // the tap usually MAKES it "already there"
        });
        if (onLongPress != null) {
            v.setOnLongClickListener(x -> {
                x.performHapticFeedback(android.view.HapticFeedbackConstants.LONG_PRESS);
                onLongPress.run();
                return true;
            });
        }
        int size = Math.round(40 * d);
        android.widget.LinearLayout.LayoutParams lp =
                new android.widget.LinearLayout.LayoutParams(size, size);
        lp.rightMargin = Math.round(6 * d);
        v.setLayoutParams(lp);

        MarkerChipBinding binding = new MarkerChipBinding(v, markerColor,
                alreadyThere != null ? alreadyThere : () -> false);
        markerChips.add(binding);
        applyMarkerChipTint(binding);
        return v;
    }

    /** True when the overlay already covers the entire project — what "span whole" would do. */
    private boolean overlaySpansWholeTimeline(
            @NonNull com.fadcam.ui.faditor.model.TextOverlayItem o) {
        if (project == null) return false;
        long total = Math.max(1L, project.getTimeline().getTotalDurationMs());
        return o.getStartMs() == 0L
                && (o.getEndMs() == Long.MAX_VALUE || o.getEndMs() >= total);
    }

    private void applyMarkerChipTint(@NonNull MarkerChipBinding b) {
        android.widget.ImageView v = b.ref.get();
        if (v == null) return;
        boolean on;
        try {
            on = b.alreadyThere.getAsBoolean();
        } catch (RuntimeException e) {
            on = false;   // a predicate must never be able to take the drawer down
        }
        int base = on ? b.markerColor : MARKER_CHIP_IDLE;
        int bright = lighten(base, 0.4f);
        v.setImageTintList(new android.content.res.ColorStateList(
                new int[][]{
                        new int[]{android.R.attr.state_pressed},
                        new int[]{android.R.attr.state_hovered},
                        new int[0]},
                new int[]{bright, bright, base}));
    }

    /**
     * Re-evaluate every live marker chip. Called as the playhead moves, because "is the marker
     * already here?" is a question about the playhead. Detached chips are dropped rather than
     * retained — the drawers rebuild often and these must not outlive their rows.
     */
    private void refreshMarkerChips() {
        if (markerChips.isEmpty()) return;
        for (java.util.Iterator<MarkerChipBinding> it = markerChips.iterator(); it.hasNext(); ) {
            MarkerChipBinding b = it.next();
            android.widget.ImageView v = b.ref.get();
            if (v == null || !v.isAttachedToWindow()) { it.remove(); continue; }
            applyMarkerChipTint(b);
        }
    }

    /**
     * Set the entrance or exit ZONE from the playhead — the amber carets' missing buttons.
     *
     * <p>JoyRaptor, 2026-08-19, counting the markers: "I wonder if the wiring for four buttons was
     * made and only two shown for lack of room." There are four triangles but only ever one trio
     * of buttons: the purple motion-range pair had them, the amber zone pair did not, and could
     * only be dragged. This is the other half.
     *
     * <p>The zones are stored as FRACTIONS of the motion span (0…MAX_ZONE_PCT), not as times, so
     * the playhead has to be converted against {@code motionRangeStartMs/EndMs} — the same span
     * {@code unitProgress} divides by. Committing through {@link #applyTextAnimZones} rather than
     * writing the model directly means these buttons get the caret drag's undo step, its
     * no-op detection and its clamp for free, and cannot drift from it.
     */
    /** True when the entrance/exit zone already ends/starts at the playhead. */
    private boolean zoneMatchesPlayhead(
            @NonNull com.fadcam.ui.faditor.model.TextOverlayItem o, boolean entrance) {
        if (project == null) return false;
        long total = project.getTimeline().getTotalDurationMs();
        long start = o.motionRangeStartMs();
        long end = o.motionRangeEndMs(total);
        long span = Math.max(1L, end - start);
        float want = entrance
                ? (lastPlayheadAbsoluteMs - start) / (float) span
                : (end - lastPlayheadAbsoluteMs) / (float) span;
        want = com.fadcam.ui.faditor.transcript.CaptionAnimator.clampZonePct(want);
        float have = entrance ? o.getTextAnimInPct() : o.getTextAnimOutPct();
        return want > 0f && Math.abs(want - have) < 0.006f;
    }

    private void setTextAnimZoneAtPlayhead(
            @NonNull com.fadcam.ui.faditor.model.TextOverlayItem o, boolean entrance) {
        if (project == null) return;
        long ph = (editorTimeline != null)
                ? editorTimeline.getPlayheadPositionMs() : lastPlayheadAbsoluteMs;
        long total = project.getTimeline().getTotalDurationMs();
        long start = o.motionRangeStartMs();
        long end = o.motionRangeEndMs(total);
        long span = Math.max(1L, end - start);
        float pct = entrance ? (ph - start) / (float) span : (end - ph) / (float) span;
        float beforeIn = o.getTextAnimInPct();
        float beforeOut = o.getTextAnimOutPct();
        applyTextAnimZones(o.getId(), beforeIn, beforeOut,
                entrance ? pct : beforeIn, entrance ? beforeOut : pct);
    }



    /**
     * The shadow's direction knob — a small circular scrub control, drag to rotate. Bespoke View
     * for the same reason {@code ColorWheelView} is: no stock Android widget expresses "drag
     * around a centre to pick an angle".
     */
    private static final class ShadowDirectionKnob extends View {
        private float angleDeg = 0f;
        @Nullable private java.util.function.Consumer<Float> onAngleChanged;
        @Nullable private Runnable onAngleCommitted;
        private final android.graphics.Paint paint =
                new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);

        ShadowDirectionKnob(@NonNull Context ctx) { super(ctx); }

        void setAngleDeg(float v) { angleDeg = v; invalidate(); }
        void setOnAngleChanged(@NonNull java.util.function.Consumer<Float> l) { onAngleChanged = l; }
        void setOnAngleCommitted(@NonNull Runnable l) { onAngleCommitted = l; }

        @Override protected void onDraw(android.graphics.Canvas c) {
            super.onDraw(c);
            float w = getWidth(), h = getHeight();
            float cx = w / 2f, cy = h / 2f;
            float r = Math.min(w, h) / 2f - 2f;
            paint.setStyle(android.graphics.Paint.Style.STROKE);
            paint.setStrokeWidth(2f);
            paint.setColor(0xFF555555);
            c.drawCircle(cx, cy, r, paint);
            // 0° = straight down, matching TextOverlayItem's shadowDx/shadowDy convention.
            double rad = Math.toRadians(angleDeg);
            float ix = cx + (float) Math.sin(rad) * r;
            float iy = cy + (float) Math.cos(rad) * r;
            paint.setStyle(android.graphics.Paint.Style.FILL);
            paint.setColor(0xFFB388FF);
            c.drawCircle(ix, iy, r * 0.22f, paint);
        }

        @Override public boolean onTouchEvent(android.view.MotionEvent e) {
            switch (e.getActionMasked()) {
                case android.view.MotionEvent.ACTION_DOWN:
                case android.view.MotionEvent.ACTION_MOVE: {
                    // The knob sits inside the drawer's ScrollView; without this the drawer
                    // scrolls while the user scrubs the angle (user, 2026-08-10). Disallow the
                    // interception for the whole gesture, release on UP/CANCEL below.
                    if (e.getActionMasked() == android.view.MotionEvent.ACTION_DOWN
                            && getParent() != null) {
                        getParent().requestDisallowInterceptTouchEvent(true);
                    }
                    float cx = getWidth() / 2f, cy = getHeight() / 2f;
                    double rad = Math.atan2(e.getX() - cx, e.getY() - cy);
                    float deg = (float) Math.toDegrees(rad);
                    if (deg < 0f) deg += 360f;
                    angleDeg = deg;
                    invalidate();
                    if (onAngleChanged != null) onAngleChanged.accept(deg);
                    return true;
                }
                case android.view.MotionEvent.ACTION_UP:
                case android.view.MotionEvent.ACTION_CANCEL:
                    if (getParent() != null) getParent().requestDisallowInterceptTouchEvent(false);
                    if (onAngleCommitted != null) onAngleCommitted.run();
                    return true;
                default:
                    return false;
            }
        }
    }

    private View buildOverlayAnimationControls(
            @NonNull com.fadcam.ui.faditor.model.TextOverlayItem item) {
        float density = getResources().getDisplayMetrics().density;
        int gap = (int) (8 * density);

        android.widget.LinearLayout box = new android.widget.LinearLayout(this);
        box.setOrientation(android.widget.LinearLayout.VERTICAL);
        box.setPadding(0, gap * 2, 0, 0);

        TextView header = new TextView(this);
        header.setText(R.string.faditor_kf_section);
        header.setTextColor(0xFF888888);
        header.setTextSize(12);
        header.setTypeface(null, android.graphics.Typeface.BOLD);
        header.setAllCaps(true);
        header.setLetterSpacing(0.06f);
        box.addView(header);

        final TextView status = new TextView(this);
        status.setTextColor(0xFFAAAAAA);
        status.setTextSize(12);
        status.setPadding(0, gap / 2, 0, gap);
        box.addView(status);

        Runnable refreshStatus = () -> {
            int n = item.getKeyframes().get(com.fadcam.ui.faditor.keyframe.KeyframeSet.X) != null
                    ? item.getKeyframes().get(com.fadcam.ui.faditor.keyframe.KeyframeSet.X)
                            .keyframes.size() : 0;
            status.setText(n == 0
                    ? getString(R.string.faditor_kf_hint_start)
                    : getString(R.string.faditor_kf_hint_armed, n));
        };
        refreshStatus.run();

        // ── Opacity / transparency ──────────────────────────────────────
        // Mirrors the volume-keyframe model: when the overlay is ARMED (has
        // keyframes) the slider drops/updates an OPACITY keyframe at the
        // playhead (a fade); otherwise it sets the static opacity for the
        // whole overlay. Preview updates live.
        TextView opLabel = new TextView(this);
        opLabel.setText("OPACITY");
        opLabel.setTextColor(0xFF888888);
        opLabel.setTextSize(12);
        opLabel.setTypeface(null, android.graphics.Typeface.BOLD);
        opLabel.setAllCaps(true);
        opLabel.setLetterSpacing(0.06f);
        opLabel.setPadding(0, gap, 0, gap / 2);
        box.addView(opLabel);

        android.widget.LinearLayout opRow = new android.widget.LinearLayout(this);
        opRow.setOrientation(android.widget.LinearLayout.HORIZONTAL);
        opRow.setGravity(android.view.Gravity.CENTER_VERTICAL);

        final android.widget.SeekBar opBar = new android.widget.SeekBar(this);
        opBar.setMax(100);
        opBar.setProgress(Math.round(item.animatedOpacity(lastPlayheadAbsoluteMs) * 100f));
        android.widget.LinearLayout.LayoutParams opLp =
                new android.widget.LinearLayout.LayoutParams(
                        0, android.widget.LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
        opBar.setLayoutParams(opLp);
        opRow.addView(opBar);

        final TextView opPct = new TextView(this);
        opPct.setTextColor(0xFFCCCCCC);
        opPct.setTextSize(13);
        opPct.setPadding(gap, 0, 0, 0);
        opPct.setText(opBar.getProgress() + "%");
        opRow.addView(opPct);
        box.addView(opRow);

        opBar.setOnSeekBarChangeListener(new android.widget.SeekBar.OnSeekBarChangeListener() {
            @Override
            public void onProgressChanged(android.widget.SeekBar sb, int progress, boolean fromUser) {
                opPct.setText(progress + "%");
                if (!fromUser) return;
                float op = progress / 100f;
                if (item.isArmed()) {
                    item.addOpacityKeyframeAt(lastPlayheadAbsoluteMs, op);
                } else {
                    item.setOpacity(op);
                }
                if (overlayLayer != null) {
                    setTextOverlayPlayhead(lastPlayheadAbsoluteMs);
                    overlayLayer.rebuild();
                }
                syncTimelineOverlays();
            }

            @Override public void onStartTrackingTouch(android.widget.SeekBar sb) {}

            @Override
            public void onStopTrackingTouch(android.widget.SeekBar sb) {
                refreshStatus.run();
                scheduleAutoSave();
            }
        });

        // The "◆ Add keyframe" mega-button + "Clear" button are gone (D2a): the
        // drawer's ‹♦› control drops/removes single keys and "Clear all keyframes"
        // is a drawer action now. Opacity slider + range controls stay here.

        // Time-range controls: clip the overlay's appearance to the playhead.
        android.widget.LinearLayout rangeRow = new android.widget.LinearLayout(this);
        rangeRow.setOrientation(android.widget.LinearLayout.HORIZONTAL);

        // The Start/End buttons that used to live here MOVED UP onto the trim row in
        // buildTextMotionRangeSection (JoyRaptor, 2026-08-12: "start | span | end need to look nice and
        // be up on the same line and before select all / clear and delete"). They were also two
        // plain Buttons where the image drawer had three purple chips, and they duplicated
        // setOverlayRangeEdgeAtPlayhead's validation, undo step and toast — including the fix that
        // reads the LIVE playhead rather than the cached one, which these never got.
        box.addView(rangeRow);

        return box;
    }

    // ── Transcript editing ───────────────────────────────────────────

    private void setupTranscriptPanel() {
        transcriptPanel = findViewById(R.id.transcript_panel);
        transcriptView = findViewById(R.id.transcript_view);
        transcriptReopenTab = findViewById(R.id.transcript_reopen_tab);
        // H1 recovery: the shift is derived from geometry that can change UNDER an open
        // panel — rotation (the activity self-handles config changes, so nothing re-runs
        // showTranscriptPanel) and the very first layout when the panel was opened before
        // player_container had been measured (transcriptDrawerShiftPx answered 0 then).
        // Re-station instantly whenever the container's width changes while open. Skipped
        // while promoted: inside the PiP shell the container's width is not pillarbox
        // geometry (audit 084b1bc5 #2/#3/#4).
        View reflowContainer = findViewById(R.id.player_container);
        if (reflowContainer != null) {
            reflowContainer.addOnLayoutChangeListener(
                    (v, l, t, r, b, ol, ot, or2, ob2) -> {
                        if (!transcriptPanelOpen) return;
                        if (previewPip != null && previewPip.isPromoted()) return;
                        if ((r - l) != (or2 - ol)) applyTranscriptReflow(false);
                    });
        }
        transcriptBreakBtn = findViewById(R.id.transcript_break);
        transcriptProgress = findViewById(R.id.transcript_progress);
        transcriptProgressText = findViewById(R.id.transcript_progress_text);
        transcriptProgressBar = findViewById(R.id.transcript_progress_bar);
        transcriptModelChoice = findViewById(R.id.transcript_model_choice);
        transcriptVersionBar = findViewById(R.id.transcript_version_bar);
        transcriptVersionScroll = findViewById(R.id.transcript_version_scroll);
        if (transcriptPanel == null) return;

        if (transcriptionEngine == null) {
            transcriptionEngine = new com.fadcam.ui.faditor.transcript.TranscriptionEngine(this);
        }
        findViewById(R.id.transcript_model_fast).setOnClickListener(v ->
                startTranscription(com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType.FAST));
        findViewById(R.id.transcript_model_accurate).setOnClickListener(v ->
                startTranscription(com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType.ACCURATE));
        findViewById(R.id.transcript_model_whisper).setOnClickListener(v ->
                startTranscription(com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType.WHISPER_BASE_EN));

        // ── Search ──
        final View searchBar = findViewById(R.id.transcript_search_bar);
        final android.widget.EditText searchInput = findViewById(R.id.transcript_search_input);
        final TextView searchCount = findViewById(R.id.transcript_search_count);
        findViewById(R.id.transcript_search_btn).setOnClickListener(v -> {
            boolean show = searchBar.getVisibility() != View.VISIBLE;
            searchBar.setVisibility(show ? View.VISIBLE : View.GONE);
            if (show) {
                searchInput.requestFocus();
                showSoftKeyboard(searchInput);
            } else {
                transcriptView.clearSearch();
                pushSearchHitsToTimeline();
                hideSoftKeyboard(searchInput);
            }
        });
        searchInput.addTextChangedListener(new android.text.TextWatcher() {
            @Override public void beforeTextChanged(CharSequence s, int a, int b, int c) {}
            @Override public void onTextChanged(CharSequence s, int a, int b, int c) {}
            @Override public void afterTextChanged(android.text.Editable s) {
                int total = transcriptView.search(s.toString());
                searchCount.setText(total == 0 ? "0/0"
                        : transcriptView.getSearchCurrentOneBased() + "/" + total);
                pushSearchHitsToTimeline();
            }
        });
        findViewById(R.id.transcript_search_prev).setOnClickListener(v -> {
            int cur = transcriptView.moveSearch(-1);
            searchCount.setText(cur + "/" + transcriptView.getSearchTotal());
        });
        findViewById(R.id.transcript_search_next).setOnClickListener(v -> {
            int cur = transcriptView.moveSearch(1);
            searchCount.setText(cur + "/" + transcriptView.getSearchTotal());
        });
        findViewById(R.id.transcript_search_close).setOnClickListener(v -> {
            searchInput.setText("");
            transcriptView.clearSearch();
            pushSearchHitsToTimeline();
            searchBar.setVisibility(View.GONE);
            hideSoftKeyboard(searchInput);
        });
        // (helper below mirrors panel search hits onto the timeline words tape)

        transcriptView.setListener(new com.fadcam.ui.faditor.transcript.TranscriptPanelView.Listener() {
            @Override
            public void onSeekToMs(long sourceMs) {
                // A tapped word's time belongs to the clip whose TRANSCRIPT is on screen,
                // NOT to whatever happens to be selected at this instant. Those two come
                // apart during a double-tap: the first tap can land the playhead in a
                // neighbouring clip, which moves the selection, and 165ms later the second
                // tap of the SAME double-tap gets rebased onto that new clip. Measured on
                // the Note 20: a word at sourceMs=5700 resolved against a clip whose
                // in-point is 103389 produced timelineMs=-4608, clamped to 0 — the "jumped
                // to 0:00 and ate my double-tap" report.
                Timeline tl = project.getTimeline();
                int idx = -1;
                if (!transcriptIsForAudio && transcriptClipId != null) {
                    for (int i = 0; i < tl.getClipCount(); i++) {
                        Clip c = tl.getClip(i);
                        if (c != null && transcriptClipId.equals(c.getId())) { idx = i; break; }
                    }
                }
                if (idx < 0) idx = selectedClipIndex; // audio transcript / owner gone
                Clip clip = (idx >= 0 && idx < tl.getClipCount()) ? tl.getClip(idx) : null;
                if (clip == null) return;
                // The transcript covers the whole SOURCE, but a source is usually cut into
                // several clips — so a word the user scrolled to can easily belong to a
                // DIFFERENT clip than the one the panel is titled with. Re-home the tap on
                // whichever clip of the same source actually contains that source time, so
                // reading down the transcript and tapping lands where the word really is
                // instead of pinning to the owner clip's out-point.
                if (clip.getSourceUri() != null
                        && (sourceMs < clip.getInPointMs() || sourceMs > clip.getOutPointMs())) {
                    for (int i = 0; i < tl.getClipCount(); i++) {
                        Clip c = tl.getClip(i);
                        if (c == null || c.getSourceUri() == null) continue;
                        if (!c.getSourceUri().equals(clip.getSourceUri())) continue;
                        if (sourceMs >= c.getInPointMs() && sourceMs <= c.getOutPointMs()) {
                            idx = i;
                            clip = c;
                            break;
                        }
                    }
                }
                // Whatever clip we settled on, a word can only address time INSIDE its trim.
                // Clamping is the backstop that stops a word with no home (trimmed away, or
                // a stale transcript) computing a NEGATIVE timeline position, which the view
                // then pins to 0 — the original 0:00 report.
                long srcMs = Math.max(clip.getInPointMs(),
                        Math.min(sourceMs, clip.getOutPointMs()));
                long segStart = editorTimeline.getSegmentStartTimeMs(idx);
                long timelineMs = segStart + (long)
                        ((srcMs - clip.getInPointMs()) / clip.getSpeedMultiplier());
                playerManager.pause();
                editorTimeline.seekToTimelineMs(timelineMs);
            }

            @Override
            public void onStrikesChanged() {
                // Live, non-destructive: update the clip's skip-list so preview
                // skips it and the timeline shows it immediately.
                syncRemovedSpansFromTranscript();
            }

            @Override
            public void onEditWord(int index, @NonNull String currentText) {
                showWordScrubDrawer(index);
            }

            @Override
            public void onLineBreaksChanged() {
                // Caption-only edit; no timeline recomputation needed, just persist.
                updateTranscriptBreakButton();
                scheduleAutoSave();
            }

            @Override
            public void onActiveWordChanged(int index) {
                updateTranscriptBreakButton();
            }

            @Override
            public void onParagraphReordered(int fromIndex, int toIndex) {
                handleTranscriptParagraphReordered(fromIndex, toIndex);
            }

            @Override
            public void onParagraphRenameRequested(int paraIndex, @NonNull String currentTitle) {
                if (currentTranscript == null) return;
                final int pIdx = paraIndex;
                android.widget.EditText input = new android.widget.EditText(FaditorEditorActivity.this);
                input.setText(currentTitle);
                input.setHint("Chapter title");
                input.setSingleLine(true);
                input.selectAll();
                new com.google.android.material.dialog.MaterialAlertDialogBuilder(FaditorEditorActivity.this)
                        .setTitle(paraIndex + 1 + ". Rename paragraph — becomes a chapter")
                        .setView(input)
                        .setNegativeButton(android.R.string.cancel, null)
                        .setPositiveButton(android.R.string.ok, (dlg, w) -> {
                            String title = input.getText().toString().trim();
                            // D4 — a named paragraph IS a chapter; empty clears it
                            if (title.isEmpty()) currentTranscript.chapterTitles.remove(pIdx);
                            else currentTranscript.chapterTitles.put(pIdx, title);
                            if (transcriptView != null) transcriptView.invalidate();
                            scheduleAutoSave();
                            android.widget.Toast.makeText(FaditorEditorActivity.this,
                                    title.isEmpty() ? "Chapter cleared" : "Chapter: " + title,
                                    android.widget.Toast.LENGTH_SHORT).show();
                        })
                        .setNeutralButton("Copy chapters", (dlg, w) -> {
                            String text = transcriptView != null ? transcriptView.getYoutubeChaptersText() : "";
                            if (text.isEmpty()) text = "(no chapters yet — name a collapsed paragraph)";
                            android.content.ClipboardManager cm = (android.content.ClipboardManager) getSystemService(CLIPBOARD_SERVICE);
                            if (cm != null) cm.setPrimaryClip(android.content.ClipData.newPlainText("YouTube chapters", text));
                            android.widget.Toast.makeText(FaditorEditorActivity.this, "Chapters copied", android.widget.Toast.LENGTH_SHORT).show();
                        })
                        .show();
            }

            @Override
            public void onParagraphSpeakerRequested(int paraIndex, @androidx.annotation.Nullable String currentSpeaker) {
                if (currentTranscript == null) return;
                final int pIdx = paraIndex;
                android.widget.EditText input = new android.widget.EditText(FaditorEditorActivity.this);
                if (currentSpeaker != null) input.setText(currentSpeaker);
                input.setHint("Speaker name (empty to clear)");
                input.setSingleLine(true);
                input.selectAll();
                final String beforeSpeaker = currentTranscript.getParagraphSpeaker(pIdx);
                new com.google.android.material.dialog.MaterialAlertDialogBuilder(FaditorEditorActivity.this)
                        .setTitle("Speaker for paragraph " + (paraIndex + 1))
                        .setView(input)
                        .setNegativeButton(android.R.string.cancel, null)
                        .setNeutralButton("Clear", (dlg, w) -> {
                            String old = beforeSpeaker;
                            if (undoManager != null) {
                                undoManager.recordAction(new com.fadcam.ui.faditor.undo.EditActions.LambdaAction(
                                        "Clear speaker",
                                        () -> { if (old == null) currentTranscript.paragraphSpeakers.remove(pIdx); else currentTranscript.paragraphSpeakers.put(pIdx, old); if (transcriptView != null) transcriptView.invalidate(); },
                                        () -> { currentTranscript.paragraphSpeakers.remove(pIdx); if (transcriptView != null) transcriptView.invalidate(); scheduleAutoSave(); }));
                            } else {
                                currentTranscript.paragraphSpeakers.remove(pIdx);
                            }
                            if (transcriptView != null) transcriptView.invalidate();
                            scheduleAutoSave();
                            android.widget.Toast.makeText(FaditorEditorActivity.this, "Speaker cleared", android.widget.Toast.LENGTH_SHORT).show();
                        })
                        .setPositiveButton(android.R.string.ok, (dlg, w) -> {
                            String name = input.getText().toString().trim();
                            String old = beforeSpeaker;
                            String applied = name.isEmpty() ? null : name;
                            if (undoManager != null) {
                                undoManager.recordAction(new com.fadcam.ui.faditor.undo.EditActions.LambdaAction(
                                        name.isEmpty() ? "Clear speaker" : "Set speaker",
                                        () -> { if (old == null) currentTranscript.paragraphSpeakers.remove(pIdx); else currentTranscript.paragraphSpeakers.put(pIdx, old); if (transcriptView != null) transcriptView.invalidate(); scheduleAutoSave(); },
                                        () -> { if (applied == null) currentTranscript.paragraphSpeakers.remove(pIdx); else currentTranscript.paragraphSpeakers.put(pIdx, applied); if (transcriptView != null) transcriptView.invalidate(); scheduleAutoSave(); }));
                            }
                            if (name.isEmpty()) currentTranscript.paragraphSpeakers.remove(pIdx);
                            else currentTranscript.paragraphSpeakers.put(pIdx, name);
                            if (transcriptView != null) transcriptView.invalidate();
                            scheduleAutoSave();
                            android.widget.Toast.makeText(FaditorEditorActivity.this,
                                    name.isEmpty() ? "Speaker cleared" : "Speaker: " + name,
                                    android.widget.Toast.LENGTH_SHORT).show();
                        })
                        .show();
            }
        });

        findViewById(R.id.transcript_close).setOnClickListener(v -> showTranscriptPanel(false));
        transcriptReopenTab.setOnClickListener(v -> showTranscriptPanel(true));
        findViewById(R.id.transcript_clean).setOnClickListener(v -> {
            if (currentTranscript == null) return;
            int n = currentTranscript.strikeFillers();
            transcriptView.invalidate();
            syncRemovedSpansFromTranscript();
            Toast.makeText(this, getString(R.string.faditor_transcript_cleaned, n),
                    Toast.LENGTH_SHORT).show();
        });
        findViewById(R.id.transcript_apply).setOnClickListener(v -> commitTranscript());

        // D5: a DIRECT R.id reference, restored 2026-08-23. This was written as
        // getResources().getIdentifier("transcript_speaker", ...) to get a green run out of
        // tools/jvm-harness/typecheck.sh, whose R.jar is a build ARTEFACT from 2026-08-19 and
        // therefore cannot contain an id added today. That harness's own header says so, and
        // says what to do about it: "That is a true negative about this checker, not about
        // your code — it means the change needs a real Gradle build before it can be believed."
        //
        // The workaround is worse than the warning it silenced. A string lookup loses
        // compile-time checking (a rename becomes a silent no-op button), costs a runtime
        // resource scan, and — the real hazard — R8 resource shrinking in a RELEASE build can
        // strip an id that no compiled reference points at, so this would work in debug and
        // quietly vanish in the shipped app. GlTransitionCardBaker's getIdentifier call is
        // legitimate by contrast: those resource names are genuinely dynamic.
        android.view.View speakerBtn = findViewById(R.id.transcript_speaker);
        if (speakerBtn != null) {
            speakerBtn.setOnClickListener(v -> {
                if (currentTranscript == null || transcriptView == null) return;
                int para = transcriptView.getSelectedParagraph();
                if (para < 0) {
                    android.widget.Toast.makeText(this, "Tap a paragraph\u2019s rail to select it first", android.widget.Toast.LENGTH_SHORT).show();
                    return;
                }
                String cur = currentTranscript.getParagraphSpeaker(para);
                if (cur == null) cur = "";
                android.widget.EditText input = new android.widget.EditText(this);
                input.setText(cur);
                input.setHint("Speaker name");
                input.setSingleLine(true);
                input.selectAll();
                final int pIdx = para;
                final String beforeSpeaker2 = currentTranscript.getParagraphSpeaker(pIdx);
                new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                        .setTitle("Speaker for paragraph " + (para + 1))
                        .setView(input)
                        .setNegativeButton(android.R.string.cancel, null)
                        .setNeutralButton("Clear", (dlg, w) -> {
                            String old = beforeSpeaker2;
                            if (undoManager != null) {
                                undoManager.recordAction(new com.fadcam.ui.faditor.undo.EditActions.LambdaAction(
                                        "Clear speaker",
                                        () -> { if (old == null) currentTranscript.paragraphSpeakers.remove(pIdx); else currentTranscript.paragraphSpeakers.put(pIdx, old); transcriptView.invalidate(); },
                                        () -> { currentTranscript.paragraphSpeakers.remove(pIdx); transcriptView.invalidate(); scheduleAutoSave(); }));
                            } else {
                                currentTranscript.paragraphSpeakers.remove(pIdx);
                            }
                            currentTranscript.paragraphSpeakers.remove(pIdx);
                            transcriptView.invalidate();
                            scheduleAutoSave();
                            android.widget.Toast.makeText(this, "Speaker cleared", android.widget.Toast.LENGTH_SHORT).show();
                        })
                        .setPositiveButton(android.R.string.ok, (dlg, w) -> {
                            String name = input.getText().toString().trim();
                            String old = beforeSpeaker2;
                            String applied = name.isEmpty() ? null : name;
                            if (undoManager != null) {
                                undoManager.recordAction(new com.fadcam.ui.faditor.undo.EditActions.LambdaAction(
                                        name.isEmpty() ? "Clear speaker" : "Set speaker",
                                        () -> { if (old == null) currentTranscript.paragraphSpeakers.remove(pIdx); else currentTranscript.paragraphSpeakers.put(pIdx, old); transcriptView.invalidate(); scheduleAutoSave(); },
                                        () -> { if (applied == null) currentTranscript.paragraphSpeakers.remove(pIdx); else currentTranscript.paragraphSpeakers.put(pIdx, applied); transcriptView.invalidate(); scheduleAutoSave(); }));
                            }
                            if (name.isEmpty()) currentTranscript.paragraphSpeakers.remove(pIdx);
                            else currentTranscript.paragraphSpeakers.put(pIdx, name);
                            transcriptView.invalidate();
                            scheduleAutoSave();
                            android.widget.Toast.makeText(this, name.isEmpty() ? "Speaker cleared" : "Speaker: " + name, android.widget.Toast.LENGTH_SHORT).show();
                        })
                        .show();
            });
        }

        if (transcriptBreakBtn != null) {
            transcriptBreakBtn.setOnClickListener(v -> {
                int idx = transcriptView != null ? transcriptView.getActiveIndex() : -1;
                if (idx < 0 || currentTranscript == null || idx >= currentTranscript.words.size()) {
                    return;
                }
                com.fadcam.ui.faditor.transcript.TranscriptWord w = currentTranscript.words.get(idx);
                w.forceLineBreakAfter = !w.forceLineBreakAfter;
                transcriptView.invalidate();
                updateTranscriptBreakButton();
                scheduleAutoSave();
                android.widget.Toast.makeText(this,
                        w.forceLineBreakAfter ? "Paragraph break added" : "Paragraph break removed",
                        android.widget.Toast.LENGTH_SHORT).show();
            });
        }

        // Drag the left handle to resize the panel width.
        View handle = findViewById(R.id.transcript_resize_handle);
        handle.setOnTouchListener(new View.OnTouchListener() {
            float downRawX;
            int startWidth;

            @Override
            public boolean onTouch(View v, MotionEvent e) {
                switch (e.getActionMasked()) {
                    case MotionEvent.ACTION_DOWN:
                        downRawX = e.getRawX();
                        startWidth = transcriptPanel.getWidth();
                        return true;
                    case MotionEvent.ACTION_MOVE:
                        int dx = (int) (downRawX - e.getRawX());
                        int screenW = getResources().getDisplayMetrics().widthPixels;
                        int w = Math.max((int) (screenW * 0.30f),
                                Math.min((int) (screenW * 0.92f), startWidth + dx));
                        ViewGroup.LayoutParams lp = transcriptPanel.getLayoutParams();
                        lp.width = w;
                        transcriptPanel.setLayoutParams(lp);
                        return true;
                    case MotionEvent.ACTION_UP:
                    case MotionEvent.ACTION_CANCEL:
                        // The drawer's width just changed, so its half-width claim on the
                        // pillarbox slack changed with it (H1). Re-derive and re-station
                        // without animation — the finger already provided the motion.
                        // Skipped while promoted: player_container then lives inside the
                        // PiP shell, so its width is NOT the pillarbox geometry (audit #4).
                        if (transcriptPanelOpen
                                && (previewPip == null || !previewPip.isPromoted())) {
                            applyTranscriptReflow(false);
                        }
                        return true;
                }
                return false;
            }
        });

        // Bottom grab handle — swipe up to dismiss the transcript panel.
        View grabHandle = findViewById(R.id.transcript_grab_handle);
        grabHandle.setOnTouchListener(new View.OnTouchListener() {
            float downRawY;
            @Override
            public boolean onTouch(View v, MotionEvent e) {
                switch (e.getActionMasked()) {
                    case MotionEvent.ACTION_DOWN:
                        downRawY = e.getRawY();
                        v.setPressed(true);
                        return true;
                    case MotionEvent.ACTION_UP:
                    case MotionEvent.ACTION_CANCEL:
                        v.setPressed(false);
                        float dy = downRawY - e.getRawY();
                        float density = getResources().getDisplayMetrics().density;
                        if (dy > 30f * density) {
                            showTranscriptPanel(false);
                        }
                        return true;
                }
                return false;
            }
        });
    }

    /**
     * Highlight the caption-style chip matching {@code styleId} (the style of the clip
     * under the playhead) and un-highlight the rest, so the active style is obvious as the
     * playhead crosses clips with different caption styles.
     */
    private void handleTranscriptParagraphReordered(int from, int to) {
        if (project == null || currentTranscript == null) {
            android.widget.Toast.makeText(this, "No transcript to reorder", android.widget.Toast.LENGTH_SHORT).show();
            return;
        }
        // Find the clip that owns the current transcript
        com.fadcam.ui.faditor.model.Clip targetClip = null;
        String clipId = transcriptClipId;
        if (!transcriptIsForAudio && clipId != null) {
            for (int i = 0; i < project.getTimeline().getClipCount(); i++) {
                com.fadcam.ui.faditor.model.Clip c = project.getTimeline().getClip(i);
                if (c != null && clipId.equals(c.getId())) { targetClip = c; break; }
            }
        }
        if (targetClip == null) {
            if (transcriptIsForAudio) {
                android.widget.Toast.makeText(this, "Audio paragraph reorder not yet via EditScript — needs audio REORDER op", android.widget.Toast.LENGTH_LONG).show();
                com.fadcam.FLog.w("Faditor", "Paragraph reorder for audio not yet implemented via EditScript");
                return;
            }
            android.widget.Toast.makeText(this, "Could not find clip for paragraph reorder", android.widget.Toast.LENGTH_SHORT).show();
            return;
        }
        com.fadcam.ui.faditor.transcript.TranscriptParagraphs paras = com.fadcam.ui.faditor.transcript.TranscriptParagraphs.of(currentTranscript);
        if (paras.paragraphCount() <= 1 || from < 0 || to < 0 || from >= paras.paragraphCount() || to >= paras.paragraphCount() || from == to) return;
        java.util.List<Integer> order = new java.util.ArrayList<>();
        for (int i = 0; i < paras.paragraphCount(); i++) order.add(i);
        int moved = order.remove(from);
        order.add(to, moved);
        // D4/D5 — chapter titles and speaker labels ride the paragraph when it moves
        {
            java.util.Map<Integer,String> newChapters = new java.util.HashMap<>();
            java.util.Map<Integer,String> newSpeakers = new java.util.HashMap<>();
            for (int newIdx = 0; newIdx < order.size(); newIdx++) {
                int oldIdx = order.get(newIdx);
                String ch = currentTranscript.chapterTitles.get(oldIdx);
                if (ch != null) newChapters.put(newIdx, ch);
                String sp = currentTranscript.paragraphSpeakers.get(oldIdx);
                if (sp != null) newSpeakers.put(newIdx, sp);
            }
            currentTranscript.chapterTitles.clear();
            currentTranscript.chapterTitles.putAll(newChapters);
            currentTranscript.paragraphSpeakers.clear();
            currentTranscript.paragraphSpeakers.putAll(newSpeakers);
        }
        try {
            com.fadcam.ui.faditor.model.Timeline tl = project.getTimeline();
            long inPoint = targetClip.getInPointMs();
            long outPoint = targetClip.getOutPointMs();
            java.util.List<long[]> spans = new java.util.ArrayList<>();
            for (int p = 0; p < paras.paragraphCount(); p++) {
                int[] range = paras.paragraphs.get(p);
                long s = currentTranscript.words.get(range[0]).startMs;
                long e = currentTranscript.words.get(range[1]).endMs;
                s = Math.max(inPoint, Math.min(s, outPoint));
                e = Math.max(inPoint, Math.min(e, outPoint));
                spans.add(new long[]{s, e});
            }
            String baseId = targetClip.getId();
            String[] pieceId = new String[spans.size()];
            for (int i = 0; i < spans.size(); i++) pieceId[i] = baseId + "__nr" + i;
            org.json.JSONArray ops = new org.json.JSONArray();
            String restId = baseId;
            java.util.List<long[]> gaps = targetClip.getSilenceCandidates();
            long prevBoundary = inPoint;
            for (int i = 0; i < spans.size() - 1; i++) {
                long boundary = spans.get(i)[1];
                // Snap to silence if available (using reflection to access private method, fallback to raw)
                long snapped = boundary;
                try {
                    java.lang.reflect.Method m = com.fadcam.ui.faditor.ai.AIToolExecutor.class.getDeclaredMethod("snapBoundaryToSilence", long.class, java.util.List.class, long.class, long.class);
                    m.setAccessible(true);
                    snapped = (long) m.invoke(null, boundary, gaps, inPoint, outPoint);
                } catch (Exception ignored) {}
                if (snapped > prevBoundary + 100) boundary = snapped;
                prevBoundary = boundary;
                if (boundary <= inPoint + 100 || boundary >= outPoint - 100) {
                    android.widget.Toast.makeText(this, "Paragraph boundary outside clip trim", android.widget.Toast.LENGTH_SHORT).show();
                    return;
                }
                String firstId = pieceId[i];
                String secondId = (i == spans.size() - 2) ? pieceId[spans.size() - 1] : (baseId + "__rest" + (i + 1));
                org.json.JSONObject op = new org.json.JSONObject();
                op.put("type", "SPLIT_CLIP_AT_TIME");
                op.put("clipId", restId);
                op.put("atSourceMs", boundary);
                op.put("firstClipId", firstId);
                op.put("secondClipId", secondId);
                ops.put(op);
                restId = secondId;
            }
            int oIndex = tl.indexOfClip(targetClip);
            org.json.JSONArray newOrder = new org.json.JSONArray();
            for (int i = 0; i < tl.getClipCount(); i++) if (i != oIndex) {
                if (i < oIndex) newOrder.put(tl.getClip(i).getId());
            }
            for (int idx : order) newOrder.put(pieceId[idx]);
            for (int i = oIndex + 1; i < tl.getClipCount(); i++) newOrder.put(tl.getClip(i).getId());
            org.json.JSONObject reorder = new org.json.JSONObject();
            reorder.put("type", "REORDER_CLIPS");
            reorder.put("newOrder", newOrder);
            ops.put(reorder);
            org.json.JSONObject scriptObj = new org.json.JSONObject();
            scriptObj.put("version", 1);
            scriptObj.put("description", "Reorder paragraph " + from + " -> " + to);
            scriptObj.put("operations", ops);
            com.fadcam.ui.faditor.ai.EditScript script = com.fadcam.ui.faditor.ai.EditScript.fromJson(scriptObj.toString());
            com.fadcam.ui.faditor.ai.EditScriptApplier applier = new com.fadcam.ui.faditor.ai.EditScriptApplier();
            applier.setContext(this);
            com.fadcam.ui.faditor.ai.EditScriptApplier.Result result = applier.apply(project, script);
            if (!result.success) {
                android.widget.Toast.makeText(this, "Reorder failed: " + result.error, android.widget.Toast.LENGTH_LONG).show();
                return;
            }
            projectStorage.save(project);
            editorTimeline.setTimeline(tl, -1);
            syncTimelineOverlays();
            transcriptView.setTranscript(currentTranscript);
            scheduleAutoSave();
            android.widget.Toast.makeText(this, "Paragraph moved", android.widget.Toast.LENGTH_SHORT).show();
        } catch (Exception e) {
            android.widget.Toast.makeText(this, "Reorder error: " + e.getMessage(), android.widget.Toast.LENGTH_LONG).show();
            com.fadcam.FLog.e("Faditor", "Paragraph reorder failed", e);
        }
    }

    private void highlightActiveCaptionChip(@Nullable String styleId) {
        if (captionStyleChips.isEmpty()) return;
        if (styleId != null && styleId.equals(highlightedCaptionStyleId)) return;
        highlightedCaptionStyleId = styleId;
        for (java.util.Map.Entry<String, TextView> e : captionStyleChips.entrySet()) {
            TextView chip = e.getValue();
            boolean active = e.getKey().equals(styleId);
            int pl = chip.getPaddingLeft(), pt = chip.getPaddingTop();
            int pr = chip.getPaddingRight(), pb = chip.getPaddingBottom();
            if (active) {
                chip.setBackgroundColor(0x554DD0E1); // soft cyan = active style
            } else {
                chip.setBackgroundResource(R.drawable.floating_button_item_bg);
            }
            chip.setPadding(pl, pt, pr, pb); // background swap resets padding
        }
    }

    // ── Animated captions ────────────────────────────────────────────

    private void setupCaptions() {
        captionsActive = true;
        com.fadcam.ui.faditor.transcript.CaptionStyleStore.ensureInit(this);
        captionOverlay = findViewById(R.id.caption_overlay);
        audioCaptionOverlay = findViewById(R.id.audio_caption_overlay);
        captionStyleBar = findViewById(R.id.caption_style_bar);
        wireCaptionKfArmShortcut();
        rebuildCaptionStyleChips();
    }

    /**
     * (Re)build the bottom style ticker: built-in presets, then the user's saved
     * custom styles (JoyRaptor 2026-07-16 — "your own personal style at the ready"),
     * then the per-clip Hidden pill. Re-run after save/delete/import.
     */
    private void rebuildCaptionStyleChips() {
        android.widget.LinearLayout row = findViewById(R.id.caption_style_row);
        if (captionOverlay == null || row == null) return;
        row.removeAllViews();
        captionStyleChips.clear();
        highlightedCaptionStyleId = null;

        java.util.List<com.fadcam.ui.faditor.transcript.CaptionStyle> styles =
                new java.util.ArrayList<>(com.fadcam.ui.faditor.transcript.CaptionStyle.presets());
        styles.addAll(com.fadcam.ui.faditor.transcript.CaptionStyleStore.listed());

        int pad = (int) (10 * getResources().getDisplayMetrics().density);
        for (com.fadcam.ui.faditor.transcript.CaptionStyle s : styles) {
            TextView chip = new TextView(this);
            chip.setText(s.label);
            chip.setTextColor(s.activeColor);
            // Custom chips preview their own font; built-ins keep the classic bold.
            chip.setTypeface(s.isCustom() ? s.typeface() : android.graphics.Typeface.DEFAULT_BOLD);
            chip.setTextSize(14);
            chip.setPadding(pad, pad / 2, pad, pad / 2);
            chip.setBackgroundResource(R.drawable.floating_button_item_bg);
            android.widget.LinearLayout.LayoutParams lp =
                    new android.widget.LinearLayout.LayoutParams(
                            android.widget.LinearLayout.LayoutParams.WRAP_CONTENT,
                            android.widget.LinearLayout.LayoutParams.WRAP_CONTENT);
            lp.rightMargin = pad / 2;
            chip.setLayoutParams(lp);
            chip.setTag(s.id); // so we can highlight the active clip's style chip
            captionStyleChips.put(s.id, chip);
            chip.setOnClickListener(v -> {
                boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                        && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
                if (preferAudio) {
                    AudioClip ac = project.getTimeline().getAudioClips().get(editorTimeline.getSelectedAudioIndex());
                    if (ac != null && ac.hasTranscript()) {
                        ac.setCaptionStyleId(s.id);
                        ac.setCaptionsEnabled(true);
                        activeCaptionIsAudio = true;
                        audioCaptionClipId = ac.getId();
                        bindAudioCaptionData(ac);
                        audioCaptionOverlay.setStyle(s);
                        audioCaptionOverlay.setVisibility(View.VISIBLE);
                        if (captionStyleBar != null) { captionStyleBarRequested = true; captionStyleBar.setVisibility(View.VISIBLE); }
                        scheduleAutoSave();
                    }
                } else {
                    Clip cc = getSelectedClip();
                    if (cc != null) {
                        if (captionStyleKeyframeMode && cc.hasCaptionStyleKeyframes()) {
                            java.util.List<Clip.CaptionStyleKeyframe> beforeKfs =
                                    snapshotCaptionStyleKeyframes(cc);
                            com.fadcam.ui.faditor.captions.CaptionStyleKeyframeController.TapAction action =
                                    com.fadcam.ui.faditor.captions.CaptionStyleKeyframeController
                                            .tapActionFor(cc, lastSourcePositionInSegmentMs);
                            cc.addOrUpdateCaptionStyleKeyframe(lastSourcePositionInSegmentMs, s.id);
                            recordCaptionStyleKeyframeEdit(cc, beforeKfs);
                            cc.setCaptionsEnabled(true);
                            bindCaptionData(cc);
                            captionOverlay.setStyle(s);
                            captionOverlay.setVisibility(View.VISIBLE);
                            if (editorTimeline != null) editorTimeline.invalidate();
                            scheduleAutoSave();
                            refreshCaptionKeyframeDrawer();
                            Toast.makeText(this,
                                    action == com.fadcam.ui.faditor.captions.CaptionStyleKeyframeController.TapAction.REPLACE
                                            ? "Keyframe style replaced"
                                            : "Style keyframe dropped",
                                    Toast.LENGTH_SHORT).show();
                        } else if (cc.hasTranscript()) {
                            cc.setCaptionStyleId(s.id);
                            cc.setCaptionsEnabled(true);
                            activeCaptionIsAudio = false;
                            bindCaptionData(cc);
                            captionOverlay.setStyle(s);
                            captionOverlay.setVisibility(View.VISIBLE);
                            scheduleAutoSave();
                        }
                    }
                }
            });
            chip.setOnLongClickListener(v -> {
                showApplyStyleToAllClipsDialog(s.id, s.label);
                return true;
            });
            row.addView(chip);
        }
        // 6th pill: "Hidden" (eye-slash) — hides captions for THIS clip only (per-clip visibility).
        TextView hideChip = new TextView(this);
        hideChip.setText("visibility_off");
        hideChip.setTypeface(androidx.core.content.res.ResourcesCompat.getFont(this, R.font.materialicons));
        hideChip.setTextColor(0xFF9E9E9E);
        hideChip.setTextSize(16);
        hideChip.setIncludeFontPadding(false);
        hideChip.setGravity(android.view.Gravity.CENTER);
        hideChip.setPadding(pad, pad / 2, pad, pad / 2);
        hideChip.setBackgroundResource(R.drawable.floating_button_item_bg);
        android.widget.LinearLayout.LayoutParams hlp = new android.widget.LinearLayout.LayoutParams(
                android.widget.LinearLayout.LayoutParams.WRAP_CONTENT,
                android.widget.LinearLayout.LayoutParams.WRAP_CONTENT);
        hlp.rightMargin = pad / 2;
        hideChip.setLayoutParams(hlp);
        hideChip.setOnClickListener(v -> {
            boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                    && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
            if (preferAudio) {
                AudioClip ac = project.getTimeline().getAudioClips().get(editorTimeline.getSelectedAudioIndex());
                if (ac != null) {
                    ac.setCaptionsEnabled(false);
                    if (audioCaptionOverlay != null) audioCaptionOverlay.setVisibility(View.GONE);
                    scheduleAutoSave();
                    Toast.makeText(this, "Captions hidden — tap a style chip to show again", Toast.LENGTH_SHORT).show();
                }
            } else {
                Clip cc = getSelectedClip();
                if (cc != null) {
                    if (captionStyleKeyframeMode && cc.hasCaptionStyleKeyframes()) {
                        java.util.List<Clip.CaptionStyleKeyframe> beforeKfs =
                                snapshotCaptionStyleKeyframes(cc);
                        cc.addOrUpdateCaptionStyleKeyframe(lastSourcePositionInSegmentMs, "hidden");
                        recordCaptionStyleKeyframeEdit(cc, beforeKfs);
                        if (editorTimeline != null) editorTimeline.invalidate();
                        scheduleAutoSave();
                        refreshCaptionKeyframeDrawer();
                        if (captionOverlay != null) captionOverlay.setVisibility(View.GONE);
                    } else {
                        cc.setCaptionsEnabled(false);
                        if (captionOverlay != null) captionOverlay.setVisibility(View.GONE);
                        scheduleAutoSave();
                        Toast.makeText(this, "Captions hidden — tap a style chip to show again", Toast.LENGTH_SHORT).show();
                    }
                }
            }
        });
        hideChip.setOnLongClickListener(v -> {
            showHideCaptionsOnAllClipsDialog();
            return true;
        });
        row.addView(hideChip);
    }

    /**
     * Long-press on the "Hidden" (eye-slash) pill: offer to hide captions on ALL clips in
     * the timeline (video + audio), mirroring the style chips' apply-to-all long-press.
     * Caption-style keyframes are left untouched (captionsEnabled=false gates rendering
     * entirely); undo restores each clip's prior enabled state. One undoable step.
     */
    private void showHideCaptionsOnAllClipsDialog() {
        if (project == null) return;
        java.util.List<Clip> clips = project.getTimeline().getClips();
        java.util.List<AudioClip> audioClips = project.getTimeline().getAudioClips();
        if (clips.isEmpty() && audioClips.isEmpty()) return;

        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle("Hide captions on all clips?")
                .setMessage("Captions on every clip in the timeline will be hidden. "
                        + "Tap a style chip on a clip to show its captions again.")
                .setPositiveButton(android.R.string.ok, (d, w) -> hideCaptionsOnAllClips())
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /** Hide captions on every video + audio clip, recorded as a single undoable step. */
    private void hideCaptionsOnAllClips() {
        if (project == null) return;
        final java.util.List<Clip> videoTargets =
                new java.util.ArrayList<>(project.getTimeline().getClips());
        final java.util.List<AudioClip> audioTargets =
                new java.util.ArrayList<>(project.getTimeline().getAudioClips());
        final java.util.List<Boolean> videoBeforeEnabled = new java.util.ArrayList<>();
        for (Clip c : videoTargets) videoBeforeEnabled.add(c.isCaptionsEnabled());
        final java.util.List<Boolean> audioBeforeEnabled = new java.util.ArrayList<>();
        for (AudioClip a : audioTargets) audioBeforeEnabled.add(a.isCaptionsEnabled());

        Runnable applyForward = () -> {
            for (Clip c : videoTargets) c.setCaptionsEnabled(false);
            for (AudioClip a : audioTargets) a.setCaptionsEnabled(false);
            refreshCaptionOverlayVisibilityAfterBulkHide();
        };
        Runnable restoreBackward = () -> {
            for (int i = 0; i < videoTargets.size(); i++) {
                videoTargets.get(i).setCaptionsEnabled(videoBeforeEnabled.get(i));
            }
            for (int i = 0; i < audioTargets.size(); i++) {
                audioTargets.get(i).setCaptionsEnabled(audioBeforeEnabled.get(i));
            }
            refreshCaptionOverlayVisibilityAfterBulkHide();
        };

        applyForward.run();
        undoManager.recordAction(new EditActions.LambdaAction(
                "Hide captions on all clips", applyForward, restoreBackward));
        scheduleAutoSave();
        Toast.makeText(this, "Captions hidden on all clips", Toast.LENGTH_SHORT).show();
    }

    /**
     * Sync both caption overlays' visibility with the bound clips' captionsEnabled state after
     * a bulk hide (or its undo), mirroring refreshActiveCaptionOverlaysAfterBulkStyleChange.
     */
    private void refreshCaptionOverlayVisibilityAfterBulkHide() {
        if (captionOverlay != null) {
            Clip cc = getSelectedClip();
            if (cc != null && cc.hasTranscript() && cc.isCaptionsEnabled()) {
                bindCaptionData(cc);
                captionOverlay.setVisibility(View.VISIBLE);
            } else {
                captionOverlay.setVisibility(View.GONE);
            }
        }
        if (audioCaptionOverlay != null) {
            AudioClip ac = audioCaptionClipId != null ? findAudioClipById(audioCaptionClipId) : null;
            if (ac != null && ac.hasTranscript() && ac.isCaptionsEnabled()) {
                bindAudioCaptionData(ac);
                audioCaptionOverlay.setVisibility(View.VISIBLE);
            } else {
                audioCaptionOverlay.setVisibility(View.GONE);
            }
        }
        if (editorTimeline != null) editorTimeline.invalidate();
    }

    /**
     * Long-press on a caption style chip: offer to apply {@code styleId} to ALL clips in
     * the timeline (video clips, and audio clips that carry their own caption style/track),
     * optionally also copying caption position and/or size from the long-pressed source clip.
     * Base style only — per-clip caption-style KEYFRAMES are untouched. Undoable as one step.
     */
    private void showApplyStyleToAllClipsDialog(@NonNull String styleId, @NonNull String styleLabel) {
        if (project == null) return;
        java.util.List<Clip> clips = project.getTimeline().getClips();
        java.util.List<AudioClip> audioClips = project.getTimeline().getAudioClips();
        if (clips.isEmpty() && audioClips.isEmpty()) return;

        // Source values to (optionally) copy come from the currently selected clip/audio clip
        // (i.e. whichever clip the long-pressed chip would apply to under a normal tap).
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < audioClips.size());
        float srcCenterX, srcCenterY, srcSizeFraction;
        if (preferAudio) {
            AudioClip src = audioClips.get(editorTimeline.getSelectedAudioIndex());
            srcCenterX = src.getCaptionCenterX();
            srcCenterY = src.getCaptionCenterY();
            srcSizeFraction = src.getCaptionSizeFraction();
        } else {
            Clip src = getSelectedClip();
            if (src == null) {
                // Fall back to defaults matching Clip's own defaults.
                srcCenterX = 0.5f; srcCenterY = 0.82f; srcSizeFraction = 0.060f;
            } else {
                srcCenterX = src.getCaptionCenterX();
                srcCenterY = src.getCaptionCenterY();
                srcSizeFraction = src.getCaptionSizeFraction();
            }
        }
        final float fSrcCenterX = srcCenterX, fSrcCenterY = srcCenterY, fSrcSizeFraction = srcSizeFraction;

        int pad = (int) (20 * getResources().getDisplayMetrics().density);
        android.widget.LinearLayout root = new android.widget.LinearLayout(this);
        root.setOrientation(android.widget.LinearLayout.VERTICAL);
        root.setPadding(pad, pad / 2, pad, 0);

        TextView helper = new TextView(this);
        helper.setText("Apply “" + styleLabel + "” to all clips in the timeline?");
        helper.setTextColor(0xFFBBBBBB);
        helper.setTextSize(13);
        root.addView(helper);

        final android.widget.CheckBox copyPosition = new android.widget.CheckBox(this);
        copyPosition.setText("Also apply caption position to all clips");
        copyPosition.setTextColor(0xFFFFFFFF);
        copyPosition.setChecked(false);
        android.widget.LinearLayout.LayoutParams posLp =
                new android.widget.LinearLayout.LayoutParams(
                        android.widget.LinearLayout.LayoutParams.MATCH_PARENT,
                        android.widget.LinearLayout.LayoutParams.WRAP_CONTENT);
        posLp.topMargin = pad / 2;
        copyPosition.setLayoutParams(posLp);
        root.addView(copyPosition);

        final android.widget.CheckBox copySize = new android.widget.CheckBox(this);
        copySize.setText("Also apply caption size to all clips");
        copySize.setTextColor(0xFFFFFFFF);
        copySize.setChecked(false);
        android.widget.LinearLayout.LayoutParams sizeLp =
                new android.widget.LinearLayout.LayoutParams(
                        android.widget.LinearLayout.LayoutParams.MATCH_PARENT,
                        android.widget.LinearLayout.LayoutParams.WRAP_CONTENT);
        sizeLp.topMargin = pad / 4;
        copySize.setLayoutParams(sizeLp);
        root.addView(copySize);

        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle("Apply style to all clips?")
                .setView(root)
                .setPositiveButton(android.R.string.ok, (d, w) -> applyCaptionStyleToAllClips(
                        styleId, copyPosition.isChecked(), copySize.isChecked(),
                        fSrcCenterX, fSrcCenterY, fSrcSizeFraction))
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /**
     * Apply {@code styleId} to every video clip and every audio clip (that has captions
     * data) in the timeline, optionally also copying caption position and/or size from the
     * long-pressed source clip. Recorded as a single undoable step that restores each clip's
     * prior style/position/size on undo.
     * <p>
     * Per-clip caption-style KEYFRAMES take priority over the base style at render time
     * (see {@link Clip#captionStyleAtClipMs(long)}, used by both the live preview and
     * {@code ExportManager}/{@code CompositeExportOverlay}). If a clip has any keyframes,
     * merely changing its base style is invisible — the keyframed value keeps winning. So
     * that "apply to all" actually makes the chosen style show on every clip, any existing
     * caption-style keyframes on the video targets are cleared as part of this same step
     * (and restored verbatim on undo).
     */
    private void applyCaptionStyleToAllClips(@NonNull String styleId,
                                              boolean copyPosition, boolean copySize,
                                              float srcCenterX, float srcCenterY, float srcSizeFraction) {
        if (project == null) return;
        java.util.List<Clip> clips = project.getTimeline().getClips();
        java.util.List<AudioClip> audioClips = project.getTimeline().getAudioClips();

        // Snapshot "before" state for every clip so undo can restore it exactly.
        final java.util.List<Clip> videoTargets = new java.util.ArrayList<>(clips);
        final java.util.List<String> videoBeforeStyle = new java.util.ArrayList<>();
        final java.util.List<float[]> videoBeforePosSize = new java.util.ArrayList<>();
        final java.util.List<java.util.List<Clip.CaptionStyleKeyframe>> videoBeforeKeyframes =
                new java.util.ArrayList<>();
        for (Clip c : videoTargets) {
            videoBeforeStyle.add(c.getCaptionStyleId());
            videoBeforePosSize.add(new float[]{c.getCaptionCenterX(), c.getCaptionCenterY(), c.getCaptionSizeFraction()});
            videoBeforeKeyframes.add(snapshotCaptionStyleKeyframes(c));
        }
        final java.util.List<AudioClip> audioTargets = new java.util.ArrayList<>(audioClips);
        final java.util.List<String> audioBeforeStyle = new java.util.ArrayList<>();
        final java.util.List<float[]> audioBeforePosSize = new java.util.ArrayList<>();
        for (AudioClip a : audioTargets) {
            audioBeforeStyle.add(a.getCaptionStyleId());
            audioBeforePosSize.add(new float[]{a.getCaptionCenterX(), a.getCaptionCenterY(), a.getCaptionSizeFraction()});
        }
        // Was keyframe-editing mode active for the clip currently selected? If that clip's
        // keyframes get cleared below, mode gets turned off the same way deleteCurrentCaptionStyleKeyframe() does.
        final Clip selectedAtApplyTime = getSelectedClip();

        Runnable applyForward = () -> {
            for (int i = 0; i < videoTargets.size(); i++) {
                Clip c = videoTargets.get(i);
                c.setCaptionStyleId(styleId);
                if (copyPosition) c.setCaptionCenter(srcCenterX, srcCenterY);
                if (copySize) c.setCaptionSizeFraction(srcSizeFraction);
                // Clear style keyframes so the newly-applied base style actually renders —
                // otherwise a keyframed clip keeps showing its old keyframed style everywhere
                // the keyframe track covers (preview AND export both read keyframes first).
                if (c.hasCaptionStyleKeyframes()) {
                    c.clearCaptionStyleKeyframes();
                    if (c == selectedAtApplyTime) captionStyleKeyframeMode = false;
                }
            }
            for (int i = 0; i < audioTargets.size(); i++) {
                AudioClip a = audioTargets.get(i);
                a.setCaptionStyleId(styleId);
                if (copyPosition) a.setCaptionCenter(srcCenterX, srcCenterY);
                if (copySize) a.setCaptionSizeFraction(srcSizeFraction);
            }
            refreshActiveCaptionOverlaysAfterBulkStyleChange();
        };
        Runnable restoreBackward = () -> {
            for (int i = 0; i < videoTargets.size(); i++) {
                Clip c = videoTargets.get(i);
                c.setCaptionStyleId(videoBeforeStyle.get(i));
                float[] ps = videoBeforePosSize.get(i);
                if (copyPosition) c.setCaptionCenter(ps[0], ps[1]);
                if (copySize) c.setCaptionSizeFraction(ps[2]);
                c.setCaptionStyleKeyframes(videoBeforeKeyframes.get(i));
                // Undo restores the keyframes that existed before apply-to-all, so restore
                // keyframe-editing mode to match (it was only turned off if we cleared them).
                if (c == selectedAtApplyTime && c.hasCaptionStyleKeyframes()) {
                    captionStyleKeyframeMode = true;
                }
            }
            for (int i = 0; i < audioTargets.size(); i++) {
                AudioClip a = audioTargets.get(i);
                a.setCaptionStyleId(audioBeforeStyle.get(i));
                float[] ps = audioBeforePosSize.get(i);
                if (copyPosition) a.setCaptionCenter(ps[0], ps[1]);
                if (copySize) a.setCaptionSizeFraction(ps[2]);
            }
            refreshActiveCaptionOverlaysAfterBulkStyleChange();
        };

        applyForward.run();
        undoManager.recordAction(new EditActions.LambdaAction(
                "Apply caption style \"" + styleId + "\" to all clips", applyForward, restoreBackward));
        scheduleAutoSave();
        Toast.makeText(this, "Style applied to all clips", Toast.LENGTH_SHORT).show();
    }

    /**
     * Refresh whichever caption overlay(s) are currently bound so the visible preview reflects
     * a bulk style change immediately (mirrors what the single-chip tap handler does for the
     * one clip it targets). Used by both the forward-apply and the undo/redo restore paths.
     */
    private void refreshActiveCaptionOverlaysAfterBulkStyleChange() {
        if (captionsActive) {
            Clip cc = getSelectedClip();
            if (cc != null && cc.hasTranscript()) {
                bindCaptionData(cc);
            }
        }
        AudioClip ac = audioCaptionClipId != null ? findAudioClipById(audioCaptionClipId) : null;
        if (ac != null) {
            bindAudioCaptionData(ac);
        }
        if (editorTimeline != null) editorTimeline.invalidate();
        // Bulk apply may have cleared the selected clip's caption-style keyframes (or undo may
        // have restored them) — keep the keyframe-dot drawer in sync if it's showing.
        refreshCaptionKeyframeDrawer();
    }

    /** Toggle the caption customization drawer. */
    private void toggleCaptions() {
        showCaptionDrawer(!captionDrawerOpen);
    }

    /**
     * Bind and show the caption OVERLAY for {@code clip}, applying its persisted style and
     * position. Both callers are RESTORES — project load, and re-binding after a transcript
     * version switch — not user requests.
     *
     * <p><b>It no longer asks for the style chooser, and that is the fix.</b> It used to set
     * {@code captionStyleBarRequested} and force the bar visible. The flag means "the user asked
     * to see the chooser"; setting it from a restore made that a lie, and since project load
     * runs this for any clip with captions enabled, every such project opened with the chooser
     * pinned to the bottom of the preview — which is exactly the always-on behaviour that was
     * asked to be made contextual, and which JoyRaptor reported again on 2026-08-14. The per-tick
     * gate in updateCurrentTimeDisplay was correct all along; it was being handed a request
     * nobody made.
     *
     * <p>The chooser is still one tap away: the caption tap, the Captions tool and the style
     * picker all set the flag themselves, deliberately, at their own call sites.</p>
     */
    private void showCaptionsForClip(@NonNull Clip clip) {
        if (captionOverlay == null || !clip.hasTranscript()) return;
        captionsActive = true;
        bindCaptionData(clip);
        captionOverlay.setVisibility(View.VISIBLE);
    }

    /**
     * Bind the caption overlay's transcript / style / position to {@code clip} WITHOUT touching
     * visibility or the editing toolbar. Used by the playback loop to switch captions to the clip under
     * the playhead at each cut (captions are clip-specific, like the visualizer).
     */
    // ── Caption transcript windowing (audit 2.4) ─────────────────────────────
    //
    // The caption overlay must show EXACTLY the words the export will draw. Export builds
    // its captions from `t.windowed(in, out)` (CompositeExportOverlay), while the preview
    // used to bind the RAW full transcript. After a split that lands mid-phrase, the two
    // therefore disagreed: observed on device with a phrase spanning source 2250-4350ms
    // split at 3300 — the preview drew "is very cute she is white" in BOTH halves, while
    // the export correctly drew "is very cute" in the first and "she is white" in the
    // second. The user saw words in the preview that the render would never contain.
    //
    // Transcript.windowed() allocates a NEW Transcript on every call (sharing the same
    // TranscriptWord references). Binding it directly would hand CaptionOverlayView a
    // different instance on every re-bind, which defeats the identity check that stops
    // setData() resetting the active word — i.e. it would silently reintroduce the
    // "captions vanish on any re-bind while paused" bug fixed in eaff34b. Hence the cache:
    // the same clip at the same trim must yield the SAME object.
    //
    // The key includes the word count and the source transcript's identity so switching
    // transcript VERSION or gaining words re-windows; strike edits need no invalidation
    // because the word objects are shared with the source.
    @Nullable private String captionWindowKey;
    @Nullable private com.fadcam.ui.faditor.transcript.Transcript captionWindowCache;
    @Nullable private String audioCaptionWindowKey;
    @Nullable private com.fadcam.ui.faditor.transcript.Transcript audioCaptionWindowCache;

    private static String captionWindowKeyFor(
            @NonNull String ownerId, long inMs, long outMs,
            @NonNull com.fadcam.ui.faditor.transcript.Transcript full) {
        return ownerId + '|' + inMs + '|' + outMs + '|' + full.words.size()
                + '|' + System.identityHashCode(full);
    }

    @Nullable
    private com.fadcam.ui.faditor.transcript.Transcript windowedCaptionsFor(@NonNull Clip clip) {
        com.fadcam.ui.faditor.transcript.Transcript full = clip.getTranscript();
        if (full == null) return null;
        String key = captionWindowKeyFor(
                clip.getId(), clip.getInPointMs(), clip.getOutPointMs(), full);
        if (captionWindowCache == null || !key.equals(captionWindowKey)) {
            captionWindowKey = key;
            captionWindowCache = full.windowed(clip.getInPointMs(), clip.getOutPointMs());
        }
        return captionWindowCache;
    }

    @Nullable
    private com.fadcam.ui.faditor.transcript.Transcript windowedCaptionsFor(
            @NonNull AudioClip clip) {
        com.fadcam.ui.faditor.transcript.Transcript full = clip.getTranscript();
        if (full == null) return null;
        String key = captionWindowKeyFor(
                clip.getId(), clip.getInPointMs(), clip.getOutPointMs(), full);
        if (audioCaptionWindowCache == null || !key.equals(audioCaptionWindowKey)) {
            audioCaptionWindowKey = key;
            audioCaptionWindowCache = full.windowed(clip.getInPointMs(), clip.getOutPointMs());
        }
        return audioCaptionWindowCache;
    }

    private void bindCaptionData(@NonNull Clip clip) {
        if (captionOverlay == null) return;
        captionClipId = clip.getId();
        highlightActiveCaptionChip(clip.getCaptionStyleId());
        // Text animation (SPEC_TEXT_ANIMATION): the SAME four values the export path reads off
        // this clip, so preview and export animate identically. Set before setData so the very
        // first frame drawn after a bind already has them.
        captionOverlay.setCaptionAnimation(clip.getCaptionAnimPreset(),
                clip.getCaptionAnimGranularity(),
                clip.getCaptionAnimInPct(), clip.getCaptionAnimOutPct());
        captionOverlay.setData(windowedCaptionsFor(clip),
                com.fadcam.ui.faditor.transcript.CaptionStyle.byId(clip.getCaptionStyleId()),
                new com.fadcam.ui.faditor.transcript.CaptionOverlayView.Callback() {
                    @NonNull
                    @Override
                    public android.graphics.RectF getVideoContentRect() {
                        // Canvas-relative: caption size/position must match the export
                        // (font = fraction × canvas height), not the per-clip video rect.
                        return computeCanvasRect();
                    }

                    @Override
                    public void onMoved() {
                        final Clip cc = findClipById(captionClipId);
                        if (cc != null) {
                            final float beforeX = cc.getCaptionCenterX();
                            final float beforeY = cc.getCaptionCenterY();
                            final float afterX = captionOverlay.getCenterX();
                            final float afterY = captionOverlay.getCenterY();
                            cc.setCaptionCenter(afterX, afterY);
                            if (beforeX != afterX || beforeY != afterY) {
                                undoManager.recordAction(new EditActions.LambdaAction("Caption position",
                                        () -> cc.setCaptionCenter(afterX, afterY),
                                        () -> cc.setCaptionCenter(beforeX, beforeY)));
                            }
                            scheduleAutoSave();
                        }
                    }

                    @Override
                    public void onTapped() {
                        activeCaptionIsAudio = false;
                        if (captionStyleBar != null) {
                            captionStyleBarRequested = true;
        captionStyleBar.setVisibility(View.VISIBLE);
                        }
                    }

                    @Override
                    public void onDoubleTapped() {
                        // JoyRaptor 2026-07-16: double-tap the caption → its advanced UI
                        // (style bar + the Caption Keyframes drawer).
                        activeCaptionIsAudio = false;
                        if (captionStyleBar != null) {
                            captionStyleBarRequested = true;
        captionStyleBar.setVisibility(View.VISIBLE);
                        }
                        openCaptionKeyframeDrawer();
                    }

                    @Override
                    public void onLongPressed() {
                        // Long-press a caption → hide captions for THIS clip (tap=props,
                        // long-hold=delete, the interaction the user likes on the visualizer).
                        final Clip cc = findClipById(captionClipId);
                        if (cc != null) {
                            cc.setCaptionsEnabled(false);
                            captionOverlay.setVisibility(View.GONE);
                            undoManager.recordAction(new EditActions.LambdaAction("Hide captions",
                                    () -> cc.setCaptionsEnabled(false),
                                    () -> cc.setCaptionsEnabled(true)));
                            scheduleAutoSave();
                            Toast.makeText(FaditorEditorActivity.this,
                                    "Captions hidden for this clip", Toast.LENGTH_SHORT).show();
                        }
                    }
                });
        captionOverlay.setCenter(clip.getCaptionCenterX(), clip.getCaptionCenterY());
        // Audit 2.1: position was bound here and size was not, so the slider moved the
        // model and the export while the preview stayed at the view's 0.060f default.
        captionOverlay.setSizeFraction(clip.getCaptionSizeFraction());
    }

    private void bindAudioCaptionData(@NonNull AudioClip clip) {
        if (audioCaptionOverlay == null) return;
        audioCaptionClipId = clip.getId();
        highlightActiveCaptionChip(clip.getCaptionStyleId());
        audioCaptionOverlay.setData(windowedCaptionsFor(clip),   // audit 2.4 — match export
                com.fadcam.ui.faditor.transcript.CaptionStyle.byId(clip.getCaptionStyleId()),
                new com.fadcam.ui.faditor.transcript.CaptionOverlayView.Callback() {
                    @NonNull @Override
                    public android.graphics.RectF getVideoContentRect() {
                        // Canvas-relative so audio captions match the export size/position.
                        return computeCanvasRect();
                    }
                    @Override
                    public void onMoved() {
                        final AudioClip ac = findAudioClipById(audioCaptionClipId);
                        if (ac != null) {
                            final float beforeX = ac.getCaptionCenterX();
                            final float beforeY = ac.getCaptionCenterY();
                            final float afterX = audioCaptionOverlay.getCenterX();
                            final float afterY = audioCaptionOverlay.getCenterY();
                            ac.setCaptionCenter(afterX, afterY);
                            if (beforeX != afterX || beforeY != afterY) {
                                undoManager.recordAction(new EditActions.LambdaAction("Caption position",
                                        () -> ac.setCaptionCenter(afterX, afterY),
                                        () -> ac.setCaptionCenter(beforeX, beforeY)));
                            }
                            scheduleAutoSave();
                        }
                    }
                    @Override
                    public void onTapped() {
                        activeCaptionIsAudio = true;
                        if (captionStyleBar != null) {
                            captionStyleBarRequested = true;
        captionStyleBar.setVisibility(View.VISIBLE);
                        }
                    }
                    @Override
                    public void onDoubleTapped() {
                        activeCaptionIsAudio = true;
                        if (captionStyleBar != null) {
                            captionStyleBarRequested = true;
        captionStyleBar.setVisibility(View.VISIBLE);
                        }
                        openCaptionKeyframeDrawer();
                    }
                    @Override
                    public void onLongPressed() {
                        final AudioClip ac = findAudioClipById(audioCaptionClipId);
                        if (ac != null) {
                            ac.setCaptionsEnabled(false);
                            audioCaptionOverlay.setVisibility(View.GONE);
                            undoManager.recordAction(new EditActions.LambdaAction("Hide captions",
                                    () -> ac.setCaptionsEnabled(false),
                                    () -> ac.setCaptionsEnabled(true)));
                            scheduleAutoSave();
                            Toast.makeText(FaditorEditorActivity.this,
                                    "Captions hidden — tap a style chip to show again", Toast.LENGTH_SHORT).show();
                        }
                    }
                });
        audioCaptionOverlay.setCenter(clip.getCaptionCenterX(), clip.getCaptionCenterY());
        audioCaptionOverlay.setSizeFraction(clip.getCaptionSizeFraction()); // audit 2.1
    }

    /** After loading a saved project, re-show captions for the clip that had them. */
    private void restoreCaptionsAfterLoad() {
        if (captionOverlay == null) return;
        Timeline tl = project.getTimeline();
        // First try to restore a video clip with captions.
        for (int i = 0; i < tl.getClipCount(); i++) {
            Clip clip = tl.getClip(i);
            if (clip.isCaptionsEnabled() && clip.hasTranscript()) {
                currentTranscript = clip.getTranscript();
                transcriptClipId = clip.getId();
                activeCaptionIsAudio = false;
                showCaptionsForClip(clip);
                return;
            }
        }
        // Fallback to audio-clip captions.
        if (audioCaptionOverlay != null) {
            for (AudioClip ac : tl.getAudioClips()) {
                if (ac.isCaptionsEnabled() && ac.hasTranscript()) {
                    currentTranscript = ac.getTranscript();
                    transcriptClipId = ac.getId();
                    activeCaptionIsAudio = true;
                    audioCaptionClipId = ac.getId();
                    captionsActive = true;
                    bindAudioCaptionData(ac);
                    audioCaptionOverlay.setVisibility(View.VISIBLE);
                    return;
                }
            }
        }
    }

    private void showSoftKeyboard(@NonNull View v) {
        android.view.inputmethod.InputMethodManager imm =
                (android.view.inputmethod.InputMethodManager) getSystemService(INPUT_METHOD_SERVICE);
        if (imm != null) imm.showSoftInput(v,
                android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);
    }

    private void hideSoftKeyboard(@NonNull View v) {
        android.view.inputmethod.InputMethodManager imm =
                (android.view.inputmethod.InputMethodManager) getSystemService(INPUT_METHOD_SERVICE);
        if (imm != null) imm.hideSoftInputFromWindow(v.getWindowToken(), 0);
    }

    private void setupTransitionPanel() {
        transitionPanel = findViewById(R.id.transition_panel);
        if (transitionPanel == null) return;
        transitionPanel.setTranslationY(-getResources().getDisplayMetrics().heightPixels);
        transitionTypeViews.clear();
        // The panel must NOT insert on drop — that was sending every drop to the playhead seam (time 0 /
        // previous scene). Only the TIMELINE inserts now (with nearest-seam snapping + a live preview).
        // Dropping a card back on the panel just cancels. (Tapping a card still quick-inserts at playhead.)
        transitionPanel.setOnDragListener((v, event) ->
                event.getAction() == android.view.DragEvent.ACTION_DRAG_STARTED);
        setupTransitionDragDrop();
        findViewById(R.id.transition_panel_close).setOnClickListener(v -> {
            hideTransitionInspector();
            showTransitionPanel(false);
        });
        // Swipe UP on the header to dismiss the drawer (the user prefers a gesture over the X button).
        View transitionHeader = findViewById(R.id.transition_panel_header);
        if (transitionHeader != null) {
            final android.view.GestureDetector swipe = new android.view.GestureDetector(this,
                    new android.view.GestureDetector.SimpleOnGestureListener() {
                        @Override
                        public boolean onFling(android.view.MotionEvent e1, android.view.MotionEvent e2,
                                               float vx, float vy) {
                            if (vy < -700 && Math.abs(vy) > Math.abs(vx)) {
                                hideTransitionInspector();
                                showTransitionPanel(false);
                                return true;
                            }
                            return false;
                        }
                    });
            transitionHeader.setOnTouchListener((v, ev) -> {
                swipe.onTouchEvent(ev);
                return true;
            });
        }
        setupTransitionDrag(findViewById(R.id.transition_cross_dissolve), Transition.Type.CROSS_DISSOLVE);
        setupTransitionDrag(findViewById(R.id.transition_fade_black), Transition.Type.FADE_OUT_TO_BLACK);
        setupTransitionDrag(findViewById(R.id.transition_fade_white), Transition.Type.FADE_OUT_TO_WHITE);
        setupTransitionDrag(findViewById(R.id.transition_wipe), Transition.Type.WIPE_LEFT);
        setupTransitionDrag(findViewById(R.id.transition_radial), Transition.Type.RADIAL);
        setupTransitionDrag(findViewById(R.id.transition_linear_mirror), Transition.Type.LINEAR_MIRROR_WIPE);
        setupTransitionDrag(findViewById(R.id.transition_push), Transition.Type.PUSH_LEFT);
        setupTransitionDrag(findViewById(R.id.transition_glitch), Transition.Type.GLITCH);
        setupTransitionDrag(findViewById(R.id.transition_tv_channel), Transition.Type.TV_CHANNEL);
        // Replace the single "GL Effect" card with ONE card per GL transition in the catalog, so every
        // shader is browsable inline alongside the basics (no nested sub-list).
        View glCard = findViewById(R.id.transition_gl_shader);
        if (glCard != null) glCard.setVisibility(View.GONE);
        populateGlTransitionCards();
    }

    /** Append a preview card for each catalog GL transition to the transitions card row. */
    private void populateGlTransitionCards() {
        android.widget.LinearLayout basicsRow = findViewById(R.id.transition_card_row);
        if (basicsRow == null) return;
        float d = getResources().getDisplayMetrics().density;

        // Put GL effects (26 catalog + any user .glsl) in a SECOND scrolling row below the basics, so the
        // basic transitions aren't buried in one endless horizontal scroll.
        android.view.ViewParent scroll = basicsRow.getParent();
        if (!(scroll instanceof View)) return;
        android.view.ViewParent panelParent = ((View) scroll).getParent();
        if (!(panelParent instanceof android.view.ViewGroup)) return;
        android.view.ViewGroup panel = (android.view.ViewGroup) panelParent;
        int insertIdx = panel.indexOfChild((View) scroll) + 1;

        android.widget.LinearLayout glRow = new android.widget.LinearLayout(this);
        glRow.setOrientation(android.widget.LinearLayout.HORIZONTAL);
        int hp = (int) (10 * d);
        glRow.setPadding(hp, 0, hp, hp);

        for (com.fadcam.ui.faditor.gltransitions.GLTransitionCatalog.Entry e
                : com.fadcam.ui.faditor.gltransitions.GLTransitionCatalog.entries()) {
            glRow.addView(buildGlTransitionCard(e.id, e.displayName, d));
        }
        // Auto-append any user-supplied .glsl GL transitions found in the pinned folder (invisible when none).
        if (project != null && project.getPinnedAssetDir() != null) {
            for (com.fadcam.ui.faditor.gltransitions.GlExternalTransitions.Item item
                    : com.fadcam.ui.faditor.gltransitions.GlExternalTransitions.scanAndRegister(
                            this, android.net.Uri.parse(project.getPinnedAssetDir()))) {
                glRow.addView(buildGlTransitionCard(item.id, item.displayName, d));
            }
        }

        android.widget.HorizontalScrollView glScroll = new android.widget.HorizontalScrollView(this);
        glScroll.setHorizontalScrollBarEnabled(false);
        glScroll.addView(glRow);

        // "Pull down for more rows" (studio-drawers §C, the last remaining TODO): the GL-effects
        // row starts COLLAPSED so the basic transitions aren't buried; a discoverable affordance
        // bar reveals it on tap or a downward fling (up-fling / re-tap collapses it).
        View affordance = buildTransitionMoreAffordance(d);
        panel.addView(affordance, insertIdx);
        glScroll.setVisibility(View.GONE);
        panel.addView(glScroll, insertIdx + 1);
        transitionGlRow = glScroll;
        transitionGlExpanded = false;
    }

    /** The tappable "⌄ More effects" bar that reveals/collapses the GL-transition row. */
    private View buildTransitionMoreAffordance(float d) {
        android.widget.LinearLayout bar = new android.widget.LinearLayout(this);
        bar.setOrientation(android.widget.LinearLayout.HORIZONTAL);
        bar.setGravity(android.view.Gravity.CENTER);
        int vp = (int) (7 * d);
        bar.setPadding(0, vp, 0, vp);

        TextView label = new TextView(this);
        label.setTextColor(0xFFAAAAAA);
        label.setTextSize(12);
        label.setText(R.string.faditor_transitions_more_effects);
        bar.addView(label);
        transitionGlToggleLabel = label;

        final android.view.GestureDetector fling = new android.view.GestureDetector(this,
                new android.view.GestureDetector.SimpleOnGestureListener() {
                    @Override
                    public boolean onFling(android.view.MotionEvent e1, android.view.MotionEvent e2,
                                           float vx, float vy) {
                        if (Math.abs(vy) > Math.abs(vx) && Math.abs(vy) > 500) {
                            setTransitionGlRowExpanded(vy > 0); // pull down = reveal, up = collapse
                            return true;
                        }
                        return false;
                    }
                });
        bar.setOnTouchListener((v, ev) -> {
            fling.onTouchEvent(ev);
            return false; // still let the tap-to-toggle click through
        });
        bar.setOnClickListener(v -> setTransitionGlRowExpanded(!transitionGlExpanded));
        return bar;
    }

    /** Reveal or collapse the GL-transition row and flip the affordance chevron/label. */
    private void setTransitionGlRowExpanded(boolean expanded) {
        if (transitionGlRow == null) return;
        transitionGlExpanded = expanded;
        transitionGlRow.setVisibility(expanded ? View.VISIBLE : View.GONE);
        if (transitionGlToggleLabel != null) {
            transitionGlToggleLabel.setText(expanded
                    ? R.string.faditor_transitions_fewer_effects
                    : R.string.faditor_transitions_more_effects);
        }
    }

    /** Build one GL-transition preview card (used for both catalog + user-supplied shaders). */
    private View buildGlTransitionCard(@NonNull final String glId, @NonNull String label, float d) {
        android.widget.LinearLayout card = new android.widget.LinearLayout(this);
        card.setOrientation(android.widget.LinearLayout.VERTICAL);
        card.setGravity(android.view.Gravity.CENTER);
        int pad = (int) (8 * d);
        card.setPadding(pad, pad, pad, pad);
        card.setBackgroundColor(Color.parseColor("#332A2A2A"));
        android.widget.LinearLayout.LayoutParams clp =
                new android.widget.LinearLayout.LayoutParams((int) (96 * d), (int) (118 * d));
        clp.setMarginEnd((int) (8 * d));
        card.setLayoutParams(clp);

        com.fadcam.ui.faditor.player.TransitionPreviewCardView preview =
                new com.fadcam.ui.faditor.player.TransitionPreviewCardView(this);
        Transition demo = new Transition(Transition.Type.GL_SHADER, 1500, 0);
        demo.glTransitionId = glId;
        preview.setTransition(demo);
        card.addView(preview, new android.widget.LinearLayout.LayoutParams((int) (64 * d), (int) (64 * d)));

        TextView lbl = new TextView(this);
        lbl.setText(label);
        lbl.setTextColor(0xFFFFFFFF);
        lbl.setTextSize(11);
        lbl.setMaxLines(1);
        lbl.setEllipsize(android.text.TextUtils.TruncateAt.END);
        android.widget.LinearLayout.LayoutParams llp = new android.widget.LinearLayout.LayoutParams(
                android.view.ViewGroup.LayoutParams.WRAP_CONTENT,
                android.view.ViewGroup.LayoutParams.WRAP_CONTENT);
        llp.topMargin = (int) (6 * d);
        card.addView(lbl, llp);

        card.setOnClickListener(v -> insertGlTransitionAtPlayhead(glId));
        card.setOnLongClickListener(v -> {
            View.DragShadowBuilder shadow = new View.DragShadowBuilder(v);
            v.startDragAndDrop(android.content.ClipData.newPlainText("glshader", glId),
                    shadow, "gl:" + glId, 0);
            return true;
        });
        return card;
    }

    private void setupTransitionDrag(View v, final Transition.Type type) {
        if (v == null) return;
        transitionTypeViews.put(type, v);
        // Swap the static preview swatch (first child) for an ANIMATED A→B demo of this transition.
        // The preview view is non-interactive, so the card's tap (add) and long-press (drag) still work.
        if (v instanceof android.view.ViewGroup) {
            android.view.ViewGroup card = (android.view.ViewGroup) v;
            if (card.getChildCount() > 0) {
                ViewGroup.LayoutParams lp = card.getChildAt(0).getLayoutParams();
                com.fadcam.ui.faditor.player.TransitionPreviewCardView preview =
                        new com.fadcam.ui.faditor.player.TransitionPreviewCardView(this);
                Transition demo = new Transition(type, 1500, 0);
                if (type == Transition.Type.GL_SHADER) demo.glTransitionId = "CrossZoom";
                preview.setTransition(demo);
                card.removeViewAt(0);
                card.addView(preview, 0, lp);
            }
        }
        v.setOnClickListener(view -> insertTransitionAtPlayhead(type));
        v.setOnLongClickListener(view -> {
            View.DragShadowBuilder shadow = new View.DragShadowBuilder(view);
            view.startDragAndDrop(android.content.ClipData.newPlainText("transition", type.name()), shadow, type, 0);
            return true;
        });
    }

    private void setupTransitionDragDrop() {
        if (editorTimeline == null) return;
        editorTimeline.setOnDragListener((v, event) -> {
            Object local = event.getLocalState();
            boolean isTransition = (local instanceof Transition.Type)
                    || (local instanceof String && ((String) local).startsWith("gl:"));
            switch (event.getAction()) {
                case android.view.DragEvent.ACTION_DRAG_STARTED:
                    // Collapse the panel so the timeline (which the open panel pushes down/off-screen) is
                    // reachable for the drop. The drag shadow keeps following the finger regardless.
                    if (isTransition && transitionPanelOpen) showTransitionPanel(false);
                    return isTransition;
                case android.view.DragEvent.ACTION_DRAG_LOCATION:
                    // Live preview: highlight the seam the transition will snap to as you move.
                    if (isTransition) {
                        editorTimeline.setTransitionDragSeam(
                                editorTimeline.getNearestSeamAtX(event.getX()));
                    }
                    return true;
                case android.view.DragEvent.ACTION_DRAG_ENDED:
                    editorTimeline.clearTransitionDrag();
                    return true;
                case android.view.DragEvent.ACTION_DROP:
                    editorTimeline.clearTransitionDrag();
                    int seam = editorTimeline.getNearestSeamAtX(event.getX());
                    if (local instanceof Transition.Type) {
                        insertTransitionAtSeam((Transition.Type) local, null, seam);
                        return true;
                    }
                    if (local instanceof String && ((String) local).startsWith("gl:")) {
                        insertTransitionAtSeam(Transition.Type.GL_SHADER,
                                ((String) local).substring(3), seam);
                        return true;
                    }
                    return true;
                default:
                    return false;
            }
        });
    }

    /**
     * Insert a transition at a specific seam (left-clip index) — snapped from the drop point to the
     * NEAREST seam boundary, so a drop over a cut lands on that cut (buttressing both clips) instead of
     * the old clip-centre mapping that drifted to the previous seam. Scrolls to reveal where it landed.
     */
    private void insertTransitionAtSeam(@NonNull Transition.Type type, @Nullable String glId, int seam) {
        if (project == null || editorTimeline == null) return;
        Timeline timeline = project.getTimeline();
        if (timeline.getClipCount() < 2) {
            Toast.makeText(this, R.string.faditor_transition_need_two_clips, Toast.LENGTH_SHORT).show();
            return;
        }
        seam = Math.max(0, Math.min(seam, timeline.getClipCount() - 2));
        Transition replaced = transitionAtSeam(seam);
        timeline.removeTransitionAtSeam(seam);
        Transition transition = new Transition(type, 600, seam);
        if (type == Transition.Type.GL_SHADER) {
            transition.glTransitionId = glId != null ? glId : "CrossZoom";
        }
        // Records the undo action and resyncs the player (a transition flips the project
        // gapless-INELIGIBLE — the engine can't render it and would play straight through the
        // seam, so the resync tears down to the legacy path, which renders transitions).
        addTransitionUndoable(transition, replaced);
        editorTimeline.setTransitions(timeline.getTransitions());
        editorTimeline.setSelectedTransitionIndex(timeline.getTransitions().size() - 1);
        updateTransitionSelection();
        editorTimeline.scrollToSeam(seam); // reveal where it landed so the user isn't hunting
        showTransitionInspector(timeline.getTransitions().size() - 1);
        saveProjectNow();
        Toast.makeText(this, R.string.faditor_transition_added, Toast.LENGTH_SHORT).show();
    }

    private void updateTransitionSelection() {
        if (project == null) return;
        Transition selected = null;
        if (editorTimeline != null) {
            int index = editorTimeline.getSelectedTransitionIndex();
            if (index >= 0 && index < project.getTimeline().getTransitions().size()) {
                selected = project.getTimeline().getTransitions().get(index);
            }
        }
        for (Map.Entry<Transition.Type, View> entry : transitionTypeViews.entrySet()) {
            View view = entry.getValue();
            if (view == null) continue;
            boolean selectedType = selected != null && selected.type == entry.getKey();
            view.setBackgroundColor(selectedType ? Color.parseColor("#2A4CAF50") : Color.parseColor("#332A2A2A"));
        }
    }

    private void showTransitionPanel(boolean show) {
        if (transitionPanel == null) return;
        if (show && visualizerDrawerOpen) showVisualizerDrawer(false); // mutually exclusive top drawers
        // Cover the top bar while choosing a transition (AI/pin/close/export aren't needed here) — this
        // also raises the drawer up. The top bar is restored when the drawer closes.
        View topBar = findViewById(R.id.editor_top_bar);
        if (topBar != null) topBar.setVisibility(show ? View.GONE : View.VISIBLE);
        transitionPanel.setVisibility(View.VISIBLE);
        transitionPanel.animate()
                .translationY(show ? 0f : -getResources().getDisplayMetrics().heightPixels)
                .setDuration(show ? 220 : 180)
                .setInterpolator(show
                        ? new android.view.animation.DecelerateInterpolator()
                        : new android.view.animation.AccelerateInterpolator())
                .withEndAction(() -> {
                    if (!show) transitionPanel.setVisibility(View.GONE);
                })
                .start();
        transitionPanelOpen = show;
        updateTransitionSelection();
    }

    private void insertTransitionAtPlayhead(@NonNull Transition.Type type) {
        insertTransitionAtPlayhead(type, type == Transition.Type.GL_SHADER ? "CrossZoom" : null);
    }

    /** Insert a GL transition with a specific catalog effect at the playhead seam. */
    private void insertGlTransitionAtPlayhead(@NonNull String glId) {
        insertTransitionAtPlayhead(Transition.Type.GL_SHADER, glId);
    }

    private void insertTransitionAtPlayhead(@NonNull Transition.Type type, @Nullable String glId) {
        if (project == null || editorTimeline == null) return;
        Timeline timeline = project.getTimeline();
        if (timeline.getClipCount() < 2) {
            Toast.makeText(this, R.string.faditor_transition_need_two_clips, Toast.LENGTH_SHORT).show();
            return;
        }
        int seam = resolveTransitionSeamAtPlayhead();
        if (seam < 0 || seam >= timeline.getClipCount()) {
            Toast.makeText(this, R.string.faditor_transition_need_two_clips, Toast.LENGTH_SHORT).show();
            return;
        }
        Transition replaced = transitionAtSeam(seam);
        timeline.removeTransitionAtSeam(seam);
        Transition transition = new Transition(type, 600, seam);
        if (type == Transition.Type.GL_SHADER) {
            transition.glTransitionId = glId != null ? glId : "CrossZoom";
        }
        // Undo record + player resync (transition ⇒ gapless-ineligible ⇒ legacy fallback).
        addTransitionUndoable(transition, replaced);
        editorTimeline.setTransitions(timeline.getTransitions());
        editorTimeline.setSelectedTransitionIndex(timeline.getTransitions().size() - 1);
        updateTransitionSelection();
        editorTimeline.invalidate();
        showTransitionInspector(timeline.getTransitions().size() - 1);
        showTransitionPanel(false);
        saveProjectNow();
        Toast.makeText(this, R.string.faditor_transition_added, Toast.LENGTH_SHORT).show();
    }

    /**
     * Returns the LEFT-clip index of the seam nearest the playhead — the {@code Transition.clipIndex}
     * convention (seam between clip[i] and clip[i+1], valid i in [0, clipCount-2]). Splits the clip at
     * the playhead to create a new seam when not near an existing boundary. (Previously returned the
     * RIGHT-clip / insert index, off by one, which orphaned every transition.)
     */
    private int resolveTransitionSeamAtPlayhead() {
        Timeline timeline = project.getTimeline();
        int clipCount = timeline.getClipCount();
        if (clipCount < 2) return -1;
        int maxSeam = clipCount - 2;
        long playhead = editorTimeline.getPlayheadPositionMs();

        // Existing boundaries: seam i sits at the start of clip[i+1].
        int bestSeam = 0;
        long best = Long.MAX_VALUE;
        for (int i = 0; i <= maxSeam; i++) {
            long boundaryTime = editorTimeline.getSegmentStartTimeMs(i + 1);
            long dist = Math.abs(playhead - boundaryTime);
            if (dist < best) {
                best = dist;
                bestSeam = i;
            }
        }
        if (best <= 350) return bestSeam;

        int seg = editorTimeline.getSegmentAtPlayhead();
        if (seg < 0 || seg >= clipCount) return bestSeam;
        Clip clip = timeline.getClip(seg);
        long segStart = editorTimeline.getSegmentStartTimeMs(seg);
        long localMs = Math.max(0, playhead - segStart);
        long effectiveMs = clip.getEffectiveDurationMs();
        if (localMs <= 350) {
            return Math.max(0, Math.min(seg - 1, maxSeam)); // boundary before clip seg = seam seg-1
        }
        if (localMs >= effectiveMs - 350) {
            return Math.max(0, Math.min(seg, maxSeam));      // boundary after clip seg = seam seg
        }
        long sourceSplitMs = clip.getInPointMs() + (long)(localMs * clip.getSpeedMultiplier());
        if (sourceSplitMs <= clip.getInPointMs() + 250 || sourceSplitMs >= clip.getOutPointMs() - 250) {
            return Math.max(0, Math.min(seg, maxSeam));
        }
        int splitIndex = timeline.splitAt(seg, sourceSplitMs);
        if (splitIndex < 0) return Math.max(0, Math.min(bestSeam, maxSeam));
        timeline.shiftTransitionsAfterSplit(splitIndex);
        selectedClipIndex = splitIndex + 1;
        editorTimeline.setTimeline(timeline, selectedClipIndex);
        editorTimeline.setTrimFromClip(timeline.getClip(selectedClipIndex));
        editorTimeline.setTransitions(timeline.getTransitions());
        refreshTotalTimeDisplay();
        saveProjectNow();
        // New clips at splitIndex and splitIndex+1; the seam between them = left index splitIndex.
        return splitIndex;
    }

    private void updateTransitionInspector(int index) {
        View inspector = findViewById(R.id.transition_inspector);
        if (inspector == null || inspector.getVisibility() != View.VISIBLE) return;
        TextView durationView = findViewById(R.id.transition_inspector_duration);
        if (durationView != null && project != null
                && index >= 0 && index < project.getTimeline().getTransitions().size()) {
            durationView.setText(TimeFormatter.formatAuto(project.getTimeline().getTransitions().get(index).durationMs));
        }
    }

    private void showTransitionInspector(int index) {
        View inspector = findViewById(R.id.transition_inspector);
        if (inspector == null) return;
        TextView typeView = findViewById(R.id.transition_inspector_type);
        TextView durationView = findViewById(R.id.transition_inspector_duration);
        View deleteView = findViewById(R.id.btn_transition_delete);
        if (index < 0 || project == null || index >= project.getTimeline().getTransitions().size()) {
            inspector.setVisibility(View.GONE);
            return;
        }
        Transition t = project.getTimeline().getTransitions().get(index);
        if (typeView != null) {
            // Tap the type to EXCHANGE it (any transition → any other). GL transitions show their
            // effect name; picking "GL Effect…" in the type picker opens the 26-entry GL chooser.
            typeView.setText((t.isGlShader()
                    ? com.fadcam.ui.faditor.gltransitions.GLTransitionCatalog.displayName(t.glTransitionId)
                    : t.type.name().replace('_', ' ')) + " ▾");
            typeView.setOnClickListener(v -> showTransitionTypePicker(t, index));
        }
        if (durationView != null) {
            durationView.setText(TimeFormatter.formatAuto(t.durationMs) + " ▾");
            durationView.setOnClickListener(v -> showTransitionDurationPicker(t, index));
        }
        if (deleteView != null) {
            deleteView.setOnClickListener(v -> deleteTransition(index));
        }
        inspector.setVisibility(View.VISIBLE);
    }

    /** Quick-pick a transition's duration from common presets. */
    private void showTransitionDurationPicker(@NonNull Transition transition, int index) {
        final long[] presets = {100L, 250L, 500L, 750L, 1000L, 1500L, 2000L, 3000L, 5000L, 8000L, 10000L};
        CharSequence[] labels = new CharSequence[presets.length];
        int checked = -1;
        for (int i = 0; i < presets.length; i++) {
            labels[i] = TimeFormatter.formatAuto(presets[i]);
            if (presets[i] == transition.durationMs) checked = i;
        }
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.faditor_transition_duration_title)
                .setSingleChoiceItems(labels, checked, (dialog, which) -> {
                    transition.durationMs = presets[which];
                    if (editorTimeline != null) {
                        editorTimeline.setTransitions(project.getTimeline().getTransitions());
                    }
                    saveProjectNow();
                    showTransitionInspector(index);
                    dialog.dismiss();
                })
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /** Exchange a transition's type in place (one curated option per family + GL effects). */
    private void showTransitionTypePicker(@NonNull Transition transition, int index) {
        final Transition.Type[] types = {
                Transition.Type.CROSS_DISSOLVE, Transition.Type.FADE_OUT_TO_BLACK,
                Transition.Type.FADE_OUT_TO_WHITE, Transition.Type.WIPE_LEFT,
                Transition.Type.PUSH_LEFT, Transition.Type.RADIAL,
                Transition.Type.LINEAR_MIRROR_WIPE, Transition.Type.GLITCH,
                Transition.Type.TV_CHANNEL, Transition.Type.GL_SHADER};
        final CharSequence[] labels = {"Cross Dissolve", "Fade to Black", "Fade to White",
                "Wipe", "Push", "Radial", "Mirror Wipe", "Glitch", "TV Channel", "GL Effect…"};
        int checked = -1;
        for (int i = 0; i < types.length; i++) {
            if (types[i] == transition.type) checked = i;
        }
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.faditor_transition_type_title)
                .setSingleChoiceItems(labels, checked, (dialog, which) -> {
                    Transition.Type picked = types[which];
                    transition.type = picked;
                    if (editorTimeline != null) {
                        editorTimeline.setTransitions(project.getTimeline().getTransitions());
                    }
                    saveProjectNow();
                    dialog.dismiss();
                    if (glTransitionPreviewView != null) glTransitionPreviewView.clear();
                    if (picked == Transition.Type.GL_SHADER) {
                        if (transition.glTransitionId == null) transition.glTransitionId = "CrossZoom";
                        showGlTransitionPicker(transition, index);
                    } else if (picked == Transition.Type.WIPE_LEFT || picked == Transition.Type.PUSH_LEFT) {
                        showTransitionDirectionPicker(transition, index, picked == Transition.Type.PUSH_LEFT);
                    } else {
                        showTransitionInspector(index);
                    }
                })
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /** Pick the direction for a wipe/push transition (the "+"-badge option). */
    private void showTransitionDirectionPicker(@NonNull Transition transition, int index, boolean push) {
        final Transition.Type[] types = push
                ? new Transition.Type[]{Transition.Type.PUSH_LEFT, Transition.Type.PUSH_RIGHT,
                        Transition.Type.PUSH_UP, Transition.Type.PUSH_DOWN}
                : new Transition.Type[]{Transition.Type.WIPE_LEFT, Transition.Type.WIPE_RIGHT,
                        Transition.Type.WIPE_UP, Transition.Type.WIPE_DOWN};
        final CharSequence[] labels = {"Left", "Right", "Up", "Down"};
        int checked = -1;
        for (int i = 0; i < types.length; i++) {
            if (types[i] == transition.type) checked = i;
        }
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.faditor_transition_direction_title)
                .setSingleChoiceItems(labels, checked, (dialog, which) -> {
                    transition.type = types[which];
                    if (editorTimeline != null) {
                        editorTimeline.setTransitions(project.getTimeline().getTransitions());
                    }
                    saveProjectNow();
                    dialog.dismiss();
                    showTransitionInspector(index);
                })
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    /** Choose which of the 26 GL transitions a GL_SHADER transition uses (from the catalog). */
    private void showGlTransitionPicker(@NonNull Transition transition, int index) {
        java.util.List<com.fadcam.ui.faditor.gltransitions.GLTransitionCatalog.Entry> entries =
                com.fadcam.ui.faditor.gltransitions.GLTransitionCatalog.entries();
        CharSequence[] labels = new CharSequence[entries.size()];
        int checked = -1;
        for (int i = 0; i < entries.size(); i++) {
            com.fadcam.ui.faditor.gltransitions.GLTransitionCatalog.Entry e = entries.get(i);
            labels[i] = e.displayName + "  ·  " + e.category;
            if (e.id.equals(transition.glTransitionId)) checked = i;
        }
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.faditor_gl_transition_pick_title)
                .setSingleChoiceItems(labels, checked, (dialog, which) -> {
                    transition.glTransitionId = entries.get(which).id;
                    dialog.dismiss();
                    if (editorTimeline != null) {
                        editorTimeline.setTransitions(project.getTimeline().getTransitions());
                    }
                    saveProjectNow();
                    showTransitionInspector(index);
                    if (glTransitionPreviewView != null) glTransitionPreviewView.clear();
                })
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    private void hideTransitionInspector() {
        View inspector = findViewById(R.id.transition_inspector);
        if (inspector != null) inspector.setVisibility(View.GONE);
    }

    private void deleteTransition(int index) {
        if (project == null || index < 0 || index >= project.getTimeline().getTransitions().size()) return;
        final Timeline timeline = project.getTimeline();
        final Transition removed = timeline.getTransitions().get(index);
        timeline.removeTransition(index);
        // Undoable (was not until 2026-07-18), and the resync RE-PROMOTES the session to the
        // gapless engine if removing this transition made the project eligible again — without
        // it the session stayed stranded on the legacy single-clip player.
        undoManager.recordAction(new EditActions.LambdaAction("Remove transition", // TODO(strings)
                () -> { // redo
                    removeTransitionObject(timeline, removed);
                    refreshTransitionUiAfterUndoRedo();
                    resyncPlayerForTransitionChange();
                },
                () -> { // undo
                    timeline.addTransition(removed);
                    refreshTransitionUiAfterUndoRedo();
                    resyncPlayerForTransitionChange();
                }));
        if (editorTimeline != null) {
            editorTimeline.setTransitions(timeline.getTransitions());
            editorTimeline.setSelectedTransitionIndex(-1);
        }
        updateTransitionSelection();
        hideTransitionInspector();
        resyncPlayerForTransitionChange();
        saveProjectNow();
        Toast.makeText(this, R.string.faditor_transition_removed, Toast.LENGTH_SHORT).show();
    }

    /**
     * Sprites tool (PLAN_SPRITE_ANIMATION S2): list the project's sprite sheets +
     * "+ New sprite sheet", launching the full-screen setup editor. Cross-activity
     * write-back rides the ChatAssistant pattern: our onPause autosave runs when the
     * editor activity opens; it saves + signalModified; we reload on resume.
     */
    /** S7: true when the sheet's source image can't be decoded (dead/moved URI). */
    private boolean isSpriteSheetMissing(@NonNull com.fadcam.ui.faditor.sprite.SpriteSheet sheet) {
        return spriteRendererFor(sheet.getId()) == null || missingSequenceFrames(sheet) > 0;
    }

    /**
     * How many of a SEQUENCE's frames cannot be opened. 0 for a grid sheet.
     *
     * <p>Needed because a sequence's renderer loads successfully if ANY ONE frame decodes — so
     * "is the sheet missing" was answering false for a sequence with 239 of 240 frames deleted.
     * ProjectIntegrity already checks all N; this is the same fact where the user can see it.</p>
     *
     * <p>Checks metadata, not pixels: opening 240 images to draw a warning label would be worse
     * than the warning is worth, and the 2026-08-05 integrity fix established that a metadata
     * query is the right probe (opening a cloud document can trigger a real download).</p>
     */
    private int missingSequenceFrames(@NonNull com.fadcam.ui.faditor.sprite.SpriteSheet sheet) {
        if (!sheet.isSequence()) return 0;
        Integer cached = sequenceMissingCounts.get(sheet.getId());
        if (cached != null) return cached;
        int missing = 0;
        for (String u : sheet.getFrameUris()) {
            if (u == null || u.isEmpty()) { missing++; continue; }
            try (android.os.ParcelFileDescriptor pfd =
                         getContentResolver().openFileDescriptor(Uri.parse(u), "r")) {
                if (pfd == null) missing++;
            } catch (Exception e) {
                missing++;
            }
        }
        sequenceMissingCounts.put(sheet.getId(), missing);
        return missing;
    }

    /**
     * Memoised per sheet id — the manager list rebuilds often and this touches the filesystem.
     * Invalidated by {@link #invalidateSpriteMissingState()}; without that the memo answered the
     * question once per Activity lifetime and both directions of the fact went stale.
     */
    private final java.util.Map<String, Integer> sequenceMissingCounts =
            new java.util.HashMap<>();

    /**
     * Re-ask the filesystem, once, about every sheet's missing frames.
     *
     * <p>Three caches answer "is this frame missing?" and all three were write-once: the
     * {@link #sequenceMissingCounts} memo above, each renderer's per-frame failure set, and the
     * timeline tape's copy of the same. So a frame renamed away stayed invisible until the
     * process died, and a frame RESTORED stayed marked missing just as long.</p>
     *
     * <p><b>Why here and not on the draw path:</b> the per-frame check is a
     * {@code openFileDescriptor} per frame — a 240-frame sequence re-statted every draw pass or
     * every played frame is file I/O on the hottest path there is. So this invalidates only at
     * the two coarse moments where the files can actually have changed underneath us — the user
     * opening the sprite-sheet manager (the screen that reports the fact) and the editor
     * resuming (the user has been away, possibly in a file manager) — and lets the existing lazy
     * per-frame detection repopulate from there.</p>
     *
     * <p>Decoded bitmaps survive: this clears FAILURE state only. Entries holding a null renderer
     * are dropped though — they cache "this sheet would not load at all", cost no pixels, and are
     * the only way a fully-restored sheet comes back.</p>
     */
    private void invalidateSpriteMissingState() {
        sequenceMissingCounts.clear();
        java.util.Iterator<java.util.Map.Entry<String,
                android.util.Pair<com.fadcam.ui.faditor.sprite.SpriteSheet,
                        com.fadcam.ui.faditor.sprite.SpriteSheetRenderer>>> it =
                spriteRendererCache.entrySet().iterator();
        while (it.hasNext()) {
            android.util.Pair<com.fadcam.ui.faditor.sprite.SpriteSheet,
                    com.fadcam.ui.faditor.sprite.SpriteSheetRenderer> p = it.next().getValue();
            if (p == null || p.second == null) { it.remove(); continue; }
            p.second.clearMissingCache();
        }
        if (editorTimeline != null) editorTimeline.clearSpriteMissingCache();
        if (spriteOverlayView != null) spriteOverlayView.invalidate();
    }

    private void openSpriteSheetManager() {
        // The list below is the screen that REPORTS missing frames, so it must re-check rather
        // than serve the answer it computed the first time it was opened.
        invalidateSpriteMissingState();
        java.util.List<com.fadcam.ui.faditor.sprite.SpriteSheet> sheets = project.getSpriteSheets();
        final int newIdx = sheets.size();
        final int seqFolderIdx = sheets.size() + 1;
        final int seqFilesIdx = sheets.size() + 2;
        final int avatarsIdx = sheets.size() + 3;
        final String[] items = new String[sheets.size() + 4];
        final boolean[] missing = new boolean[sheets.size()];
        for (int i = 0; i < sheets.size(); i++) {
            com.fadcam.ui.faditor.sprite.SpriteSheet s = sheets.get(i);
            missing[i] = isSpriteSheetMissing(s);
            // S7 discoverability: visible "missing" state right in the manager list
            // (inline literal — strings.xml is another agent's live file per protocol).
            // A sequence says HOW MANY frames are gone: "missing" on a 240-frame object that
            // still mostly works is not actionable, "12 of 240 frames missing" is.
            int gone = missingSequenceFrames(s);
            items[i] = !missing[i] ? s.getName()
                    : gone > 0
                        ? s.getName() + "  ⚠ " + gone + " of " + s.cellCount() + " frames missing"
                        : s.getName() + "  ⚠ missing";
        }
        items[newIdx] = getString(R.string.sprite_sheet_picker_new);
        // SPEC_IMAGE_SEQUENCE §3. Inline literals — strings.xml is another agent's live file
        // per the protocol note above. Folder first: it is the route §3a detection needs and
        // the only one that scales past the persistable-grant limit.
        items[seqFolderIdx] = "＋ Image sequence from folder…";
        items[seqFilesIdx] = "＋ Image sequence from files…";
        items[avatarsIdx] = getString(R.string.sprite_sheet_picker_avatars);

        android.widget.ArrayAdapter<String> adapter = new android.widget.ArrayAdapter<String>(
                this, android.R.layout.simple_list_item_1, items) {
            @NonNull @Override
            public View getView(int position, @Nullable View convertView, @NonNull ViewGroup parent) {
                View v = super.getView(position, convertView, parent);
                if (v instanceof TextView && position < missing.length && missing[position]) {
                    ((TextView) v).setTextColor(0xFFFF5252); // red tint for missing sheets
                }
                return v;
            }
        };

        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.sprite_sheet_picker_title)
                .setAdapter(adapter, (d, which) -> {
                    if (which == avatarsIdx) {
                        openAvatarStudioManager();
                        return;
                    }
                    if (which == seqFolderIdx) { pickSequenceFolder(); return; }
                    if (which == seqFilesIdx) { pickSequenceFiles(); return; }
                    if (which < sheets.size()) {
                        showSpriteSheetActions(sheets.get(which));
                        return;
                    }
                    launchSpriteSheetEditor(null); // + New sprite sheet
                })
                .show();
    }

    /** Existing sheet tapped: edit, place an instance, or relink dead art (S7). */
    private void showSpriteSheetActions(@NonNull com.fadcam.ui.faditor.sprite.SpriteSheet sheet) {
        boolean missing = isSpriteSheetMissing(sheet);
        String relinkLabel = getString(R.string.sprite_sheet_action_relink)
                + (missing ? "  ⚠" : ""); // inline literal, see class-level protocol note
        // An image SEQUENCE has no grid to edit and no single sheetUri to relink: the grid
        // editor would lay cols/rows arithmetic over frame 0 and could rewrite the one preset
        // that carries every authored weight, and "Relink" writes only sheetUri, which
        // frameUriAt() never reads — a silent no-op the user would read as a failed repair.
        // Offering neither is the honest state until a sequence-shaped version of each exists.
        final boolean seq = sheet.isSequence();
        String[] actions = seq
                ? new String[]{getString(R.string.sprite_sheet_action_place)}
                : new String[]{
                        getString(R.string.sprite_sheet_action_edit),
                        getString(R.string.sprite_sheet_action_place),
                        relinkLabel};
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(sheet.getName() + (seq ? "  ·  " + sheet.cellCount() + " frames" : ""))
                .setItems(actions, (d, which) -> {
                    if (seq) { placeSpriteOnVideo(sheet); return; }
                    if (which == 0) {
                        launchSpriteSheetEditor(sheet.getId());
                    } else if (which == 1) {
                        placeSpriteOnVideo(sheet);
                    } else {
                        startSpriteRelink(sheet);
                    }
                })
                .show();
    }

    /**
     * S7 relink UI: system file picker (ACTION_OPEN_DOCUMENT, image/*,
     * persistable URI permission — same import contract as {@code
     * SpriteSheetEditorActivity#importSheetImage}) to replace ONE sheet's
     * source image in place. Grid/cells/pivot/presets are untouched — only
     * {@code sheetUri} changes, so every placed {@link
     * com.fadcam.ui.faditor.sprite.SpriteOverlayItem} referencing this sheet
     * keeps working (same object/id, no re-point needed).
     */
    private void startSpriteRelink(@NonNull com.fadcam.ui.faditor.sprite.SpriteSheet sheet) {
        spriteRelinkPendingSheetId = sheet.getId();
        spriteRelinkPickerLauncher.launch(openDocumentIntent("image/*"));
    }

    /**
     * Apply a picked relink image: copy into the project bundle (mirrors
     * {@code SpriteSheetEditorActivity#importSheetImage}'s assets/ convention
     * so the stored URI stays project-relative on save), update the sheet's
     * {@code sheetUri} IN PLACE, invalidate the decode cache (identity-keyed —
     * mutating the same object won't auto-invalidate it), refresh preview +
     * palette, ONE undoable step, autosave.
     */
    private void applySpriteRelink(@NonNull String sheetId, @NonNull Uri pickedUri) {
        if (project == null) return;
        com.fadcam.ui.faditor.sprite.SpriteSheet sheet = project.spriteSheetById(sheetId);
        if (sheet == null) return;
        try {
            getContentResolver().takePersistableUriPermission(
                    pickedUri, Intent.FLAG_GRANT_READ_URI_PERMISSION);
        } catch (SecurityException e) {
            FLog.w(TAG, "Could not take persistable URI permission for sprite relink", e);
        }
        final String oldUri = sheet.getSheetUri();
        final String newUri;
        try {
            java.io.File assetsDir = new java.io.File(
                    projectStorage.projectDir(project.getId()), "assets");
            if (!assetsDir.exists()) assetsDir.mkdirs();
            java.io.File dest = new java.io.File(assetsDir,
                    "sheet-relink-" + java.util.UUID.randomUUID() + ".png");
            try (java.io.InputStream in = getContentResolver().openInputStream(pickedUri);
                 java.io.FileOutputStream out = new java.io.FileOutputStream(dest)) {
                byte[] buf = new byte[64 * 1024];
                int n;
                while (in != null && (n = in.read(buf)) > 0) out.write(buf, 0, n);
            }
            newUri = Uri.fromFile(dest).toString();
        } catch (Exception e) {
            Toast.makeText(this, R.string.sprite_editor_import_failed, Toast.LENGTH_LONG).show();
            return;
        }
        applySpriteRelinkUri(sheetId, newUri);
        undoManager.recordAction(new EditActions.LambdaAction("Relink sprite sheet",
                () -> applySpriteRelinkUri(sheetId, newUri),
                () -> applySpriteRelinkUri(sheetId, oldUri)));
        scheduleAutoSave();
        Toast.makeText(this, sheet.getName() + ": relinked", Toast.LENGTH_SHORT).show();
    }

    /** Redo/undo body: point the sheet (same object/id) at a URI and refresh
     *  every cached/rendered consumer. Never re-creates the SpriteSheet. */
    private void applySpriteRelinkUri(@NonNull String sheetId, @NonNull String uri) {
        if (project == null) return;
        com.fadcam.ui.faditor.sprite.SpriteSheet sheet = project.spriteSheetById(sheetId);
        if (sheet == null) return;
        sheet.setSheetUri(uri);
        // Identity-keyed cache: mutating the SAME object doesn't invalidate it.
        android.util.Pair<com.fadcam.ui.faditor.sprite.SpriteSheet,
                com.fadcam.ui.faditor.sprite.SpriteSheetRenderer> cached =
                spriteRendererCache.remove(sheetId);
        if (cached != null && cached.second != null) cached.second.recycle();
        // The relink is precisely a change to which files exist — the memo's answer is now stale.
        sequenceMissingCounts.remove(sheetId);
        if (spriteOverlayView != null) spriteOverlayView.invalidate();
        if (spritePalettePanel != null && spritePalettePanel.isAttachedToWindow()) {
            spritePalettePanel.rebuild();
        }
    }

    private void launchSpriteSheetEditor(@Nullable String sheetId) {
        android.content.Intent it = new android.content.Intent(this,
                com.fadcam.ui.faditor.sprite.SpriteSheetEditorActivity.class);
        it.putExtra(com.fadcam.ui.faditor.sprite.SpriteSheetEditorActivity
                .EXTRA_PROJECT_ID, project.getId());
        if (sheetId != null) {
            it.putExtra(com.fadcam.ui.faditor.sprite.SpriteSheetEditorActivity
                    .EXTRA_SHEET_ID, sheetId);
        }
        startActivity(it);
    }

    /**
     * S4 placement: drop a sprite instance at the playhead, first cell showing
     * from time 0 of the item (a single-cell "hold" — S5's lane + the S3 palette
     * add real frame animation on top). One undo step; persists via autosave.
     */
    @Nullable
    private com.fadcam.ui.faditor.sprite.SpriteOverlayItem placeSpriteOnVideo(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteSheet sheet) {
        if (project == null) return null;
        final com.fadcam.ui.faditor.sprite.SpriteOverlayItem item =
                com.fadcam.ui.faditor.sprite.SpriteOverlayItem.create(sheet.getId());
        // T8: every placed sprite gets its OWN lane (unique layerId) so two sprites never
        // collapse onto one shared "sprite" track and overlap (FEEDBACK_20260706 #2).
        item.setLayerId(com.fadcam.ui.faditor.model.Timeline.spriteLayerIdFor(item));
        if (sheet.isSequence()) {
            // A sequence placed from the manager must ANIMATE. Dropping a cell key here — the
            // sprite default — pins it to one still, which looks like the import silently
            // failed. Same single preset key and same natural length the import path uses, so
            // both routes produce the same object.
            sheet.ensureSequencePreset();
            item.getFrameTrack().put(com.fadcam.ui.faditor.sprite.FrameTrack.Key.ofPreset(
                    0, com.fadcam.ui.faditor.sprite.SpriteSheet.SEQUENCE_PRESET_ID));
            long start = Math.max(0, lastPlayheadAbsoluteMs);
            com.fadcam.ui.faditor.sprite.SpriteSheet.Preset p = sheet.sequencePreset();
            long span = com.fadcam.ui.faditor.sprite.SequenceTiming.totalMsForFps(
                    p == null ? null : p.weights, sheet.cellCount(),
                    p != null && p.fps > 0f ? p.fps : sheet.getFps());
            item.setTimeRange(start, start + span);
        } else {
            item.getFrameTrack().put(
                    com.fadcam.ui.faditor.sprite.FrameTrack.Key.ofCell(0, firstEnabledCell(sheet)));
            item.setTimeRange(Math.max(0, lastPlayheadAbsoluteMs), Long.MAX_VALUE);
        }
        project.getTimeline().addSpriteOverlay(item);
        syncTimelineOverlays();
        undoManager.recordAction(new EditActions.LambdaAction("Place sprite",
                () -> { project.getTimeline().addSpriteOverlay(item); syncTimelineOverlays(); },
                () -> { project.getTimeline().removeSpriteOverlay(item); syncTimelineOverlays(); }));
        scheduleAutoSave();
        Toast.makeText(this, R.string.sprite_placed, Toast.LENGTH_SHORT).show();
        return item;
    }

    // ── Image sequences (SPEC_IMAGE_SEQUENCE §3 import) ──────────────────────

    /**
     * §3 entry A: the user picks the frames themselves.
     *
     * <p>No detection is needed or wanted here — an explicit multi-selection IS the answer to
     * "which files", so §3a's conservatism has already been satisfied by the user's own fingers.
     * The frames are still ordered NUMERICALLY by name rather than by pick order, because
     * "select all" in a file picker does not promise an order and {@code frame_9} must still
     * precede {@code frame_10}.</p>
     */
    private void pickSequenceFiles() {
        Intent it = openDocumentIntent("image/*");
        it.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
        sequenceFilesPickerLauncher.launch(it);
    }

    /**
     * §3 entry B: the user points at the FOLDER, and §3a detection runs.
     *
     * <p>This is the route the spec's detection rule actually needs: a document URI from
     * OPEN_DOCUMENT cannot enumerate its own siblings, so "look in the same folder for names that
     * differ only by a trailing number" is only expressible against a tree grant.</p>
     *
     * <p>It is also the route that SCALES. A tree grant is ONE persistable permission covering
     * every child, where multi-selecting 240 frames would try to persist 240 grants and run into
     * the per-package limit — losing access to arbitrary frames later, which would look like
     * random files going missing rather than like a permission problem.</p>
     */
    private void pickSequenceFolder() {
        Intent it = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        it.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION
                | Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
        sequenceFolderPickerLauncher.launch(it);
    }

    private void onSequenceFilesPicked(@NonNull Intent data) {
        java.util.List<Uri> uris = new java.util.ArrayList<>();
        android.content.ClipData clip = data.getClipData();
        if (clip != null) {
            for (int i = 0; i < clip.getItemCount(); i++) {
                Uri u = clip.getItemAt(i).getUri();
                if (u != null) uris.add(u);
            }
        } else if (data.getData() != null) {
            uris.add(data.getData());
        }
        if (uris.isEmpty()) return;
        if (uris.size() == 1) {
            // One image is a still, not a sequence. Say so and point at the route that can
            // actually find the rest, rather than silently importing a one-frame "animation".
            new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                    .setTitle("Only one image")
                    .setMessage("A sequence needs more than one frame. Pick the folder your "
                            + "frames are in and I'll look for the rest.")
                    .setPositiveButton("Pick folder", (d, w) -> pickSequenceFolder())
                    .setNegativeButton("Cancel", null)
                    .show();
            return;
        }
        for (Uri u : uris) {
            try {
                getContentResolver().takePersistableUriPermission(
                        u, Intent.FLAG_GRANT_READ_URI_PERMISSION);
            } catch (SecurityException | IllegalArgumentException e) {
                // Non-fatal and expected past the per-package grant limit. The URI still works
                // for this session; consolidation is what makes it durable.
                FLog.w(TAG, "sequence: could not persist grant for " + u, e);
            }
        }
        // Sort by display name numerically, using the detector's own comparator via a synthetic
        // run — one ordering rule for both entry points.
        java.util.List<String> names = new java.util.ArrayList<>();
        java.util.Map<String, Uri> byName = new java.util.LinkedHashMap<>();
        for (int i = 0; i < uris.size(); i++) {
            String n = displayNameOf(uris.get(i));
            if (n == null) n = "frame_" + i;
            // Two files in different folders can share a name; disambiguate so neither is lost.
            while (byName.containsKey(n)) n = n + "_";
            names.add(n);
            byName.put(n, uris.get(i));
        }
        com.fadcam.ui.faditor.sprite.SequenceDetector.Candidate cand =
                com.fadcam.ui.faditor.sprite.SequenceDetector.detect(names.get(0), names);
        java.util.List<String> ordered = new java.util.ArrayList<>();
        if (cand != null) {
            for (String n : cand.names) ordered.add(byName.get(n).toString());
        } else {
            // Unnumbered names (photo.jpg, sunset.jpg): keep the picker's order rather than
            // inventing one.
            for (Uri u : uris) ordered.add(u.toString());
        }
        // The detector filters siblings to the first pick's stem AND extension, so a mixed
        // selection (shot_001..040.png + shot_041..045.jpg, or two different stems) quietly
        // loses the rest. The user EXPLICITLY chose those files — dropping them without a word
        // is the silent data loss this path's own comment claims cannot happen here.
        final int dropped = uris.size() - ordered.size();
        final java.util.List<String> finalOrdered = ordered;
        final String name = suggestSequenceName(names.get(0));
        if (dropped > 0) {
            new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                    .setTitle(dropped + " of " + uris.size() + " files left out")
                    .setMessage("A sequence is one run of images with the same name and file "
                            + "type. I kept the " + ordered.size() + " that match \""
                            + name + "\" and left the rest out.\n\nImport those "
                            + ordered.size() + "?")
                    .setPositiveButton("Import " + ordered.size(), (d, w) -> offerSequenceImport(
                            com.fadcam.ui.faditor.sprite.SequenceImportDialog
                                    .headlineForPicked(finalOrdered), finalOrdered, name))
                    .setNegativeButton("Cancel", null)
                    .show();
            return;
        }
        offerSequenceImport(
                com.fadcam.ui.faditor.sprite.SequenceImportDialog.headlineForPicked(ordered),
                ordered, name);
    }

    private void onSequenceFolderPicked(@NonNull Uri treeUri) {
        try {
            getContentResolver().takePersistableUriPermission(
                    treeUri, Intent.FLAG_GRANT_READ_URI_PERMISSION);
        } catch (SecurityException | IllegalArgumentException e) {
            FLog.w(TAG, "sequence: could not persist tree grant", e);
        }
        java.util.List<String> names = new java.util.ArrayList<>();
        java.util.Map<String, Uri> byName = new java.util.LinkedHashMap<>();
        try {
            String docId = android.provider.DocumentsContract.getTreeDocumentId(treeUri);
            Uri children = android.provider.DocumentsContract
                    .buildChildDocumentsUriUsingTree(treeUri, docId);
            try (android.database.Cursor c = getContentResolver().query(children, new String[]{
                    android.provider.DocumentsContract.Document.COLUMN_DOCUMENT_ID,
                    android.provider.DocumentsContract.Document.COLUMN_DISPLAY_NAME}, null, null, null)) {
                while (c != null && c.moveToNext()) {
                    String id = c.getString(0), name = c.getString(1);
                    if (name == null || !com.fadcam.ui.faditor.sprite.SequenceDetector
                            .isImageName(name)) continue;
                    names.add(name);
                    byName.put(name, android.provider.DocumentsContract
                            .buildDocumentUriUsingTree(treeUri, id));
                }
            }
        } catch (Exception e) {
            FLog.w(TAG, "sequence: could not list folder", e);
        }
        if (names.isEmpty()) {
            Toast.makeText(this, "No images in that folder", Toast.LENGTH_SHORT).show();
            return;
        }
        // Detect from the FIRST numbered image. §3a is explicit that the result is an OFFER with
        // a count — the dialog shows it and the user can decline, which is the whole protection
        // against a holiday folder of IMG_0001…IMG_0400 being read as an animation.
        String seed = null;
        for (String n : names) {
            if (com.fadcam.ui.faditor.sprite.SequenceDetector.isNumbered(n)) {
                seed = n;
                break;
            }
        }
        com.fadcam.ui.faditor.sprite.SequenceDetector.Candidate cand = seed == null ? null
                : com.fadcam.ui.faditor.sprite.SequenceDetector.detect(seed, names);
        if (cand == null) {
            Toast.makeText(this, "No numbered image sequence found in that folder",
                    Toast.LENGTH_LONG).show();
            return;
        }
        java.util.List<String> ordered = new java.util.ArrayList<>();
        for (String n : cand.names) {
            Uri u = byName.get(n);
            if (u != null) ordered.add(u.toString());
        }
        offerSequenceImport(cand.describe(), ordered, suggestSequenceName(cand.stem));
    }

    /** Display name for a SAF document URI, or null. */
    @Nullable
    private String displayNameOf(@NonNull Uri uri) {
        try (android.database.Cursor c = getContentResolver().query(uri, new String[]{
                android.provider.OpenableColumns.DISPLAY_NAME}, null, null, null)) {
            if (c != null && c.moveToFirst()) return c.getString(0);
        } catch (Exception ignored) { }
        return null;
    }

    /** A readable sheet name from a filename stem: {@code "shot_"} → {@code "shot"}. */
    @NonNull
    private String suggestSequenceName(@Nullable String stemOrName) {
        if (stemOrName == null || stemOrName.trim().isEmpty()) return "Sequence";
        String s = stemOrName;
        int dot = s.lastIndexOf('.');
        if (dot > 0) s = s.substring(0, dot);
        s = s.replaceAll("[0-9]+$", "").replaceAll("[-_. ]+$", "").trim();
        return s.isEmpty() ? "Sequence" : s;
    }

    /**
     * A sequence offer that must wait for the activity to be resumed.
     *
     * <p><b>Why this exists, proven on device 2026-08-06.</b> Returning from the SAF picker can
     * RECREATE this activity, and the {@code ActivityResult} is delivered before the new window
     * is attached. A dialog shown at that moment is created — logcat shows the {@code Dialog}
     * lines — and then destroyed with the old window a few ms later, so the user taps "Allow" on
     * the folder and lands back in the editor with nothing to show for it and no error anywhere.
     *
     * <p>The same shape as the missing-file dialog in HANDOFF_20260804c ("fired during load and
     * was lost"), which is why this parks on the lifecycle rather than guessing at a delay.</p>
     */
    @Nullable private Runnable pendingSequenceOffer;

    /** Ask §3b's one question, then build the sheet and place it. */
    private void offerSequenceImport(@NonNull String headline,
                                     @NonNull java.util.List<String> frameUris,
                                     @NonNull String name) {
        if (frameUris.isEmpty()) return;
        final Runnable show = () -> {
            if (isFinishing() || isDestroyed()) return;
            com.fadcam.ui.faditor.sprite.SequenceImportDialog.show(this, headline,
                    frameUris.size(), fps -> createSequenceSheetAndPlace(name, frameUris, fps));
        };
        // getLifecycle() rather than a flag we maintain ourselves: the result can arrive either
        // before or after onResume depending on whether the activity survived the picker, and
        // only one of those two paths may run.
        if (getLifecycle().getCurrentState().isAtLeast(
                androidx.lifecycle.Lifecycle.State.RESUMED)) {
            getWindow().getDecorView().post(show);
        } else {
            pendingSequenceOffer = show;
        }
    }

    /**
     * Build the sequence sheet, register it on the project, and place an instance at the
     * playhead spanning its natural length.
     *
     * <p>Unlike a sprite, a sequence is placed with a CONCRETE end rather than open-ended: its
     * whole timing model is "total duration divided by weights", so an object with no end has no
     * frame durations either. That is also §6's resolution for open-ended playback — keep the
     * affordance, but always resolve to a real length.</p>
     */
    private void createSequenceSheetAndPlace(@NonNull String name,
                                             @NonNull java.util.List<String> frameUris,
                                             float fps) {
        if (project == null) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet sheet =
                com.fadcam.ui.faditor.sprite.SpriteSheet.create(name,
                        frameUris.isEmpty() ? "" : frameUris.get(0));
        sheet.setSequenceFrames(frameUris);
        sheet.setFps(fps);
        sheet.ensureSequencePreset();
        project.getSpriteSheets().add(sheet);

        final com.fadcam.ui.faditor.sprite.SpriteOverlayItem item =
                com.fadcam.ui.faditor.sprite.SpriteOverlayItem.create(sheet.getId());
        item.setLayerId(com.fadcam.ui.faditor.model.Timeline.spriteLayerIdFor(item));
        // ONE frame-track entry running the whole sequence as a preset — which is what makes
        // the timing a single integer array the dope sheet and the AI can both reason about.
        item.getFrameTrack().put(com.fadcam.ui.faditor.sprite.FrameTrack.Key.ofPreset(
                0, com.fadcam.ui.faditor.sprite.SpriteSheet.SEQUENCE_PRESET_ID));
        long start = Math.max(0, lastPlayheadAbsoluteMs);
        long span = com.fadcam.ui.faditor.sprite.SequenceTiming.totalMsForFps(
                sheet.ensureSequencePreset().weights, frameUris.size(), fps);
        item.setTimeRange(start, start + span);
        project.getTimeline().addSpriteOverlay(item);
        syncTimelineOverlays();

        // ONE undo step covers BOTH the sheet registration and the placement. Undoing a placement
        // and being left with an orphan sheet in the manager would be the user's action only
        // half-reversed.
        undoManager.recordAction(new EditActions.LambdaAction("Import image sequence",
                () -> {
                    if (!project.getSpriteSheets().contains(sheet)) {
                        project.getSpriteSheets().add(sheet);
                    }
                    project.getTimeline().addSpriteOverlay(item);
                    syncTimelineOverlays();
                },
                () -> {
                    project.getTimeline().removeSpriteOverlay(item);
                    project.getSpriteSheets().remove(sheet);
                    syncTimelineOverlays();
                }));
        scheduleAutoSave();
        Toast.makeText(this, frameUris.size() + " frames · "
                        + com.fadcam.ui.faditor.sprite.DurationParser.formatMs(span),
                Toast.LENGTH_SHORT).show();
    }

    // ── Dope-sheet edits (SPEC_IMAGE_SEQUENCE §5) ────────────────────────────

    /**
     * Write new weights onto a sequence and re-length the object to match.
     *
     * <p><b>Adding a hold makes the object LONGER; it does not speed everything else up.</b>
     * fps is the stored authority (§2), so Σweights/fps is the run's length and holding frame 3
     * for five beats adds four beats to the whole thing — the animator's expectation, and the
     * direction that leaves the cadence they chose alone. The opposite convention would mean
     * lengthening one hold silently retimed every other frame.</p>
     *
     * <p>Note this is the exact INVERSE of dragging the object's edge in RELATIVE mode (§2a),
     * which keeps the weights and moves fps. Together they are the two things a user can mean,
     * and each leaves the other's authored value untouched.</p>
     */
    private void applySequenceWeights(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteOverlayItem item,
            @NonNull java.util.List<Integer> weights, @NonNull String label) {
        if (project == null) return;
        // Weights are sheet-scoped too: editing a hold on one placement would otherwise
        // retime every other copy of the same sequence.
        final com.fadcam.ui.faditor.sprite.SpriteSheet sheet = sheetForExclusiveEdit(item);
        if (sheet == null || !sheet.isSequence()) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet.Preset preset = sheet.sequencePreset();
        if (preset == null) return;

        final java.util.List<Integer> before = new java.util.ArrayList<>(preset.weights);
        final long beforeStart = item.getStartMs(), beforeEnd = item.getEndMs();
        final java.util.List<Integer> after = com.fadcam.ui.faditor.sprite.SequenceTiming
                .fit(weights, preset.frames.size());

        Runnable apply = () -> {
            preset.weights.clear();
            preset.weights.addAll(after);
            long span = com.fadcam.ui.faditor.sprite.SequenceTiming.totalMsForFps(
                    after, preset.frames.size(),
                    preset.fps > 0f ? preset.fps : sheet.getFps());
            item.setTimeRange(beforeStart, beforeStart + span);
            syncTimelineOverlays();
        };
        Runnable undo = () -> {
            preset.weights.clear();
            preset.weights.addAll(before);
            item.setTimeRange(beforeStart, beforeEnd);
            syncTimelineOverlays();
        };
        apply.run();
        undoManager.recordAction(new EditActions.LambdaAction(label, apply, undo));
        scheduleAutoSave();
        if (spriteOverlayView != null) spriteOverlayView.invalidate();
    }

    /** §5c.7 order operations. Weights travel WITH their frames, so holds stay on their images. */
    private void applySequenceReorder(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteOverlayItem item, @NonNull String op) {
        if (project == null) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet sheet = sheetForExclusiveEdit(item);
        if (sheet == null || !sheet.isSequence()) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet.Preset preset = sheet.sequencePreset();
        if (preset == null) return;

        final java.util.List<String> beforeUris =
                new java.util.ArrayList<>(sheet.getFrameUris());
        final java.util.List<Integer> beforeW = new java.util.ArrayList<>(preset.weights);

        java.util.List<String> uris = new java.util.ArrayList<>(beforeUris);
        java.util.List<Integer> ws = com.fadcam.ui.faditor.sprite.SequenceTiming
                .fit(preset.weights, uris.size());
        if ("REVERSE".equals(op)) {
            com.fadcam.ui.faditor.sprite.SequenceTiming.reverse(uris, ws);
        } else {
            // Seeded from the clock: the SHUFFLE itself need not be reproducible (undo restores
            // the exact previous order), but SequenceTiming takes a seed so the harness can
            // assert that frames and weights move together.
            com.fadcam.ui.faditor.sprite.SequenceTiming.shuffle(uris, ws,
                    System.currentTimeMillis());
        }
        final java.util.List<String> afterUris = uris;
        final java.util.List<Integer> afterW = ws;

        Runnable apply = () -> {
            sheet.setSequenceFrames(afterUris);
            sheet.ensureSequencePreset();
            preset.weights.clear();
            preset.weights.addAll(afterW);
            invalidateSpriteRenderer(sheet.getId());
            syncTimelineOverlays();
        };
        Runnable undo = () -> {
            sheet.setSequenceFrames(beforeUris);
            sheet.ensureSequencePreset();
            preset.weights.clear();
            preset.weights.addAll(beforeW);
            invalidateSpriteRenderer(sheet.getId());
            syncTimelineOverlays();
        };
        apply.run();
        undoManager.recordAction(new EditActions.LambdaAction(
                "REVERSE".equals(op) ? "Reverse frames" : "Shuffle frames", apply, undo));
        scheduleAutoSave();
        if (spriteOverlayView != null) spriteOverlayView.invalidate();
    }

    /** Drop cached decoders for a sheet whose frames changed, so the next draw re-reads them. */
    private void invalidateSpriteRenderer(@NonNull String sheetId) {
        android.util.Pair<com.fadcam.ui.faditor.sprite.SpriteSheet,
                com.fadcam.ui.faditor.sprite.SpriteSheetRenderer> cached =
                spriteRendererCache.remove(sheetId);
        if (cached != null && cached.second != null) cached.second.recycle();
        // Frames changed under a stable id, so the memoised missing-count no longer describes it.
        sequenceMissingCounts.remove(sheetId);
        if (editorTimeline != null) editorTimeline.invalidateSpriteRenderer(sheetId);
    }

    /**
     * FF-A: turn the selected frame-track keys into a reusable {@link
     * com.fadcam.ui.faditor.sprite.SpriteSheet.Preset}, and collapse those keys into one preset
     * key so the timeline shows the run as the single thing it now is.
     */
    private void makePresetFromKeys(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteOverlayItem item,
            @NonNull java.util.List<Integer> keyIndices) {
        if (project == null) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet sheet =
                project.spriteSheetById(item.getSheetId());
        if (sheet == null) return;
        java.util.List<com.fadcam.ui.faditor.sprite.FrameTrack.Key> keys =
                item.getFrameTrack().keys();
        java.util.List<Integer> idx = new java.util.ArrayList<>(keyIndices);
        java.util.Collections.sort(idx);
        if (idx.size() < 2) {
            Toast.makeText(this, "Select at least two frames", Toast.LENGTH_SHORT).show();
            return;
        }
        final com.fadcam.ui.faditor.sprite.SpriteSheet.Preset preset =
                new com.fadcam.ui.faditor.sprite.SpriteSheet.Preset(
                        java.util.UUID.randomUUID().toString(),
                        "Preset " + (sheet.getPresets().size() + 1));
        preset.type = "loop";
        long anchor = 0;
        boolean first = true;
        // CONSUMED, not "selected": a preset key in the selection contributes no frame, so it
        // must not be collapsed away either. Removing keys this loop skipped would delete the
        // animation they drove and put it in neither the new preset nor the surviving track —
        // a silent destructive edit behind a toast that reads like success.
        final java.util.Set<Integer> consumed = new java.util.HashSet<>();
        for (Integer i : idx) {
            if (i == null || i < 0 || i >= keys.size()) continue;
            com.fadcam.ui.faditor.sprite.FrameTrack.Key k = keys.get(i);
            if (k.presetId != null) continue;      // already a preset run: not a frame
            if (first) { anchor = k.timeMs; first = false; }
            preset.frames.add(k.cellIndex);
            consumed.add(i);
        }
        if (preset.frames.size() < 2) {
            Toast.makeText(this, "Those keys can't make a preset", Toast.LENGTH_SHORT).show();
            return;
        }
        final long anchorMs = anchor;
        final java.util.List<com.fadcam.ui.faditor.sprite.FrameTrack.Key> before =
                new java.util.ArrayList<>(keys);
        final java.util.List<com.fadcam.ui.faditor.sprite.FrameTrack.Key> after =
                new java.util.ArrayList<>();
        for (int i = 0; i < before.size(); i++) {
            if (consumed.contains(i)) continue;
            after.add(before.get(i));
        }
        after.add(com.fadcam.ui.faditor.sprite.FrameTrack.Key.ofPreset(anchorMs, preset.id));

        Runnable apply = () -> {
            if (sheet.presetById(preset.id) == null) sheet.getPresets().add(preset);
            restoreFrameKeys(item, after);
        };
        Runnable undo = () -> {
            sheet.getPresets().remove(preset);
            restoreFrameKeys(item, before);
        };
        apply.run();
        undoManager.recordAction(new EditActions.LambdaAction("Make preset", apply, undo));
        scheduleAutoSave();
        Toast.makeText(this, preset.name + " · " + preset.frames.size() + " frames",
                Toast.LENGTH_SHORT).show();
    }

    /**
     * §3d — <b>Convert to sprite sheet</b>, as a drawer ACTION rather than an import branch.
     *
     * <p>The user originally wanted a second import path that builds a sprite object instead.
     * The spec moves it here on purpose: <i>"at import the user cannot yet know which they want;
     * as an action it is discoverable later and reversible."</i></p>
     *
     * <p>Packs the N frames into one grid PNG in the project bundle, builds a grid sheet with the
     * same cadence, and carries the WEIGHTS across on an equivalent preset — so converting does
     * not quietly throw away the timing the user authored. The original sequence sheet is left in
     * the project: conversion re-points this item, it does not destroy the source.</p>
     */
    private void convertSequenceToSpriteSheet(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteOverlayItem item) {
        if (project == null) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet seq =
                project.spriteSheetById(item.getSheetId());
        if (seq == null || !seq.isSequence()) {
            Toast.makeText(this, "Not an image sequence", Toast.LENGTH_SHORT).show();
            return;
        }
        final int n = seq.cellCount();
        if (n <= 0) return;
        Toast.makeText(this, "Packing " + n + " frames…", Toast.LENGTH_SHORT).show();

        final String seqId = seq.getId();
        thumbnailExecutorRun(() -> {
            com.fadcam.ui.faditor.sprite.SpriteSheet packed = null;
            try {
                packed = com.fadcam.ui.faditor.sprite.SequencePacker.pack(
                        this, seq,
                        new java.io.File(
                                projectStorage.projectDir(project.getId()), "assets"));
            } catch (Exception | OutOfMemoryError e) {
                FLog.w(TAG, "sequence → sheet pack failed", e);
            }
            final com.fadcam.ui.faditor.sprite.SpriteSheet result = packed;
            runOnUiThread(() -> {
                if (result == null) {
                    Toast.makeText(this, "Couldn't pack that sequence", Toast.LENGTH_LONG).show();
                    return;
                }
                final String oldSheetId = seqId;
                final java.util.List<com.fadcam.ui.faditor.sprite.FrameTrack.Key> before =
                        new java.util.ArrayList<>(item.getFrameTrack().keys());
                final java.util.List<com.fadcam.ui.faditor.sprite.FrameTrack.Key> after =
                        java.util.Collections.singletonList(
                                com.fadcam.ui.faditor.sprite.FrameTrack.Key.ofPreset(0,
                                        com.fadcam.ui.faditor.sprite.SpriteSheet
                                                .SEQUENCE_PRESET_ID));
                Runnable apply = () -> {
                    if (project.spriteSheetById(result.getId()) == null) {
                        project.getSpriteSheets().add(result);
                    }
                    item.setSheetId(result.getId());
                    restoreFrameKeys(item, after);
                    syncTimelineOverlays();
                };
                Runnable undo = () -> {
                    item.setSheetId(oldSheetId);
                    restoreFrameKeys(item, before);
                    project.getSpriteSheets().remove(result);
                    syncTimelineOverlays();
                };
                apply.run();
                undoManager.recordAction(
                        new EditActions.LambdaAction("Convert to sprite sheet", apply, undo));
                scheduleAutoSave();
                if (spriteOverlayView != null) spriteOverlayView.invalidate();
                Toast.makeText(this, "Packed into a "
                        + result.getCols() + "×" + result.getRows() + " sheet",
                        Toast.LENGTH_SHORT).show();
            });
        });
    }

    /** Run off the UI thread on the shared thumbnail executor (packing decodes N images). */
    private void thumbnailExecutorRun(@NonNull Runnable r) {
        new Thread(r, "seq-pack").start();
    }

    // ── §6 looping / §2a resize mode ─────────────────────────────────────────

    /** Cycle the sequence's wrap: once → loop → ping-pong. Ping-pong preserves weights. */
    private void cycleSequenceLoopMode(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteOverlayItem item) {
        if (project == null) return;
        // Sheet-scoped (preset.type) AND item-scoped (endBehavior) in one action, so without
        // copy-on-write cycling on one placement left every other copy with a wrap type it
        // never asked for while keeping its own end behaviour — two halves of one setting out
        // of step, which is exactly what this method's comment claims to prevent.
        final com.fadcam.ui.faditor.sprite.SpriteSheet sheet = sheetForExclusiveEdit(item);
        if (sheet == null) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet.Preset p = sheet.sequencePreset();
        if (p == null) return;
        final String before = p.type;
        final String after = "once".equals(before) ? "loop"
                : ("loop".equals(before) ? "pingpong" : "once");
        Runnable apply = () -> {
            p.type = after;
            // endBehavior is what applies AFTER the last frame-track entry; keeping the two in
            // step is what makes the chip mean one thing instead of two half-things.
            item.setEndBehavior("once".equals(after) ? "hold" : after);
            syncTimelineOverlays();
        };
        Runnable undo = () -> {
            p.type = before;
            item.setEndBehavior("once".equals(before) ? "hold" : before);
            syncTimelineOverlays();
        };
        apply.run();
        undoManager.recordAction(new EditActions.LambdaAction("Loop mode", apply, undo));
        scheduleAutoSave();
        if (spriteOverlayView != null) spriteOverlayView.invalidate();
    }

    /**
     * §6: toggle the "continues until blocked" intent, then RESOLVE it immediately.
     *
     * <p>Resolution is not deferred to playback: the length is written as a real number now, so
     * undo restores a number the user saw and nothing depends on neighbours at render time.</p>
     */
    private void toggleSequenceContinues(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteOverlayItem item) {
        if (project == null) return;
        final boolean before = item.isContinuesUntilBlocked();
        final long beforeStart = item.getStartMs(), beforeEnd = item.getEndMs();
        Runnable apply = () -> {
            item.setContinuesUntilBlocked(!before);
            if (!before) {
                resolveSequenceOpenEnds();
            } else {
                item.setClippedByNeighbour(false);
            }
            syncTimelineOverlays();
        };
        Runnable undo = () -> {
            item.setContinuesUntilBlocked(before);
            item.setTimeRange(beforeStart, beforeEnd);
            item.setClippedByNeighbour(false);
            syncTimelineOverlays();
        };
        apply.run();
        undoManager.recordAction(new EditActions.LambdaAction("Continue to next", apply, undo));
        scheduleAutoSave();
        if (item.isClippedByNeighbour()) {
            // "Never silently" (§6): if a neighbour cut it short, say so at the moment it
            // happens as well as marking it on the tape.
            Toast.makeText(this, "Shortened by the next object in this lane",
                    Toast.LENGTH_SHORT).show();
        }
    }

    /**
     * §6: give every "continues" sequence a concrete length, per lane.
     *
     * <p>Called after edits that can change what blocks what. Cheap and idempotent — it reports
     * whether anything actually moved, so calling it on every change cannot create churn.</p>
     */
    private boolean resolveSequenceOpenEnds() {
        if (project == null || project.getTimeline() == null) return false;
        // ONE lane-grouping rule, shared with the AI path — see
        // SequenceAiOps.resolveOpenEndsPerLane for what having two of them cost.
        com.fadcam.ui.faditor.ai.SequenceAiOps.resolveOpenEndsPerLane(project);
        return false;
    }

    /** §2a: toggle what dragging this sequence's edge MEANS. Also visible on the tape. */
    private void cycleSequenceResizeMode(
            @NonNull com.fadcam.ui.faditor.sprite.SpriteOverlayItem item) {
        if (project == null) return;
        final com.fadcam.ui.faditor.sprite.SpriteSheet sheet = sheetForExclusiveEdit(item);
        if (sheet == null) return;
        final com.fadcam.ui.faditor.sprite.SequenceTiming.ResizeMode before = sheet.getResizeMode();
        final com.fadcam.ui.faditor.sprite.SequenceTiming.ResizeMode after =
                before == com.fadcam.ui.faditor.sprite.SequenceTiming.ResizeMode.RELATIVE
                        ? com.fadcam.ui.faditor.sprite.SequenceTiming.ResizeMode.ABSOLUTE
                        : com.fadcam.ui.faditor.sprite.SequenceTiming.ResizeMode.RELATIVE;
        Runnable apply = () -> { sheet.setResizeMode(after); syncTimelineOverlays(); };
        Runnable undo = () -> { sheet.setResizeMode(before); syncTimelineOverlays(); };
        apply.run();
        undoManager.recordAction(new EditActions.LambdaAction("Resize mode", apply, undo));
        scheduleAutoSave();
        Toast.makeText(this,
                after == com.fadcam.ui.faditor.sprite.SequenceTiming.ResizeMode.ABSOLUTE
                        ? "Dragging the edge now adds/removes frames"
                        : "Dragging the edge now retimes all frames",
                Toast.LENGTH_SHORT).show();
    }

    /** Lowest-index ENABLED cell (cells with no meta default to enabled). */
    private int firstEnabledCell(@NonNull com.fadcam.ui.faditor.sprite.SpriteSheet sheet) {
        for (int i = 0; i < sheet.cellCount(); i++) {
            com.fadcam.ui.faditor.sprite.SpriteSheet.Cell meta = sheet.cellAt(i);
            if (meta == null || meta.enabled) return i;
        }
        return 0;
    }

    /**
     * Avatar Studio rig list (PLAN_AVATAR_STUDIO A1-UI): the project's rigs +
     * "+ New avatar", launching the matrix editor. Same write-back pattern as
     * the sprite setup editor. Editor-side surface stays THIN per the
     * architecture contract — authoring lives entirely in Avatar Studio.
     */
    private void openAvatarStudioManager() {
        java.util.List<com.fadcam.ui.faditor.avatar.AvatarRig> rigs = project.getAvatarRigs();
        // A4 editor slice: library avatars are INSERTABLE as timeline objects
        // (architecture contract: avatar = standalone droppable object). The
        // insert entries live in this same dialog — one avatar surface.
        final java.util.List<com.fadcam.ui.faditor.avatar.AvatarLibrary.Entry> lib =
                com.fadcam.ui.faditor.avatar.AvatarLibrary.list(this);
        String[] items = new String[rigs.size() + 1 + lib.size()];
        for (int i = 0; i < rigs.size(); i++) items[i] = rigs.get(i).getName();
        items[rigs.size()] = getString(R.string.avatar_studio_new);
        for (int i = 0; i < lib.size(); i++) {
            items[rigs.size() + 1 + i] = "⇓ Insert \"" + lib.get(i).rig.getName() + "\"";
        }
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.avatar_studio_title)
                .setItems(items, (d, which) -> {
                    if (which > rigs.size()) {
                        insertAvatarFromLibrary(lib.get(which - rigs.size() - 1));
                        return;
                    }
                    android.content.Intent it = new android.content.Intent(this,
                            com.fadcam.ui.faditor.avatar.AvatarStudioActivity.class);
                    it.putExtra(com.fadcam.ui.faditor.avatar.AvatarStudioActivity
                            .EXTRA_PROJECT_ID, project.getId());
                    if (which < rigs.size()) {
                        it.putExtra(com.fadcam.ui.faditor.avatar.AvatarStudioActivity
                                .EXTRA_RIG_ID, rigs.get(which).getId());
                    }
                    startActivity(it);
                })
                .show();
    }

    /**
     * A4 editor slice (THIN, per architecture contract): import a library
     * avatar into this project and place it at the playhead. The placed item
     * is a 1-cell sprite sheet holding the rig's NEUTRAL pose baked by
     * {@link com.fadcam.ui.faditor.avatar.AvatarNeutralBaker} — it rides the
     * complete sprite pipeline (preview/export/lanes/undo) with zero new
     * compositor surface. The rig + its REAL sheets also import (idempotent by
     * id) so the later bake-to-keyframes slice can upgrade the placed item to
     * a live puppet; the baked asset's name carries the rig linkage.
     */
    private void insertAvatarFromLibrary(
            @NonNull com.fadcam.ui.faditor.avatar.AvatarLibrary.Entry entry) {
        java.io.File assetsDir = new java.io.File(
                projectStorage.projectDir(project.getId()), "assets");
        if (!assetsDir.exists() && !assetsDir.mkdirs()) {
            Toast.makeText(this, "Couldn't create project assets", Toast.LENGTH_SHORT).show();
            return;
        }
        // 1) Neutral-pose bake → 1-cell sheet asset.
        String assetName = com.fadcam.ui.faditor.avatar.AvatarNeutralBaker
                .neutralAssetName(entry.rig);
        java.io.File baked = new java.io.File(assetsDir, assetName);
        if (!com.fadcam.ui.faditor.avatar.AvatarNeutralBaker.bakeNeutralPng(
                this, entry.rig, entry.sheets, baked, 1024)) {
            Toast.makeText(this, "Avatar bake failed", Toast.LENGTH_SHORT).show();
            return;
        }
        // 2) Register (or refresh) the baked sheet — stable id from the rig so
        // re-inserting the same avatar reuses one sheet def.
        String bakedSheetId = "avatar-neutral-" + entry.rig.getId();
        com.fadcam.ui.faditor.sprite.SpriteSheet bakedSheet =
                project.spriteSheetById(bakedSheetId);
        if (bakedSheet == null) {
            bakedSheet = new com.fadcam.ui.faditor.sprite.SpriteSheet(bakedSheetId,
                    "Avatar: " + entry.rig.getName(),
                    android.net.Uri.fromFile(baked).toString());
            bakedSheet.setGrid(1, 1); // whole PNG is the one cell (default is 3x3)
            project.getSpriteSheets().add(bakedSheet);
        } else {
            bakedSheet.setSheetUri(android.net.Uri.fromFile(baked).toString());
        }
        // 3) Import the rig + its real sheets (idempotent by id) for the
        // live-render/bake upgrade path.
        for (com.fadcam.ui.faditor.sprite.SpriteSheet s : entry.sheets) {
            if (project.spriteSheetById(s.getId()) != null) continue;
            try {
                java.io.File dest = new java.io.File(assetsDir, "sheet-" + s.getId() + ".png");
                try (java.io.InputStream in = getContentResolver()
                        .openInputStream(android.net.Uri.parse(s.getSheetUri()));
                     java.io.FileOutputStream out = new java.io.FileOutputStream(dest)) {
                    byte[] buf = new byte[64 * 1024];
                    int n;
                    while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
                }
                com.fadcam.ui.faditor.sprite.SpriteSheet copy =
                        com.fadcam.ui.faditor.sprite.SpriteSheet.fromJson(s.toJson());
                copy.setSheetUri(android.net.Uri.fromFile(dest).toString());
                project.getSpriteSheets().add(copy);
            } catch (Exception e) {
                // Missing source sheet: the neutral bake still placed fine; the
                // upgrade path will surface the MISSING affordance honestly.
            }
        }
        com.fadcam.ui.faditor.avatar.AvatarRig existing =
                project.avatarRigById(entry.rig.getId());
        if (existing != null) project.getAvatarRigs().remove(existing);
        project.getAvatarRigs().add(entry.rig);
        // 4) Place at the playhead via the proven sprite path (lane, undo,
        // autosave, toast all included). The explicit avatarRigId linkage is
        // what the bake-to-keyframes upgrade keys on (the asset-name
        // convention is a human-readable mirror, not the machine contract).
        com.fadcam.ui.faditor.sprite.SpriteOverlayItem placed =
                placeSpriteOnVideo(bakedSheet);
        if (placed != null) {
            placed.setAvatarRigId(entry.rig.getId());
            scheduleAutoSave();
        }
    }

    /** Opens the panel; reuses an existing transcript, picks a model, or transcribes. */
    private void openTranscriptPanel() {
        if (inCropMode) exitCropMode(false);

        // Determine whether we're editing an audio clip's transcript or a video clip's.
        resolveTranscriptTarget();

        if (!transcriptIsForAudio) {
            Clip clip = getSelectedClip();
            if (clip == null) return;
            if (clip.isImageClip()) {
                Toast.makeText(this, R.string.faditor_transcript_image, Toast.LENGTH_SHORT).show();
                return;
            }
        }

        boolean alreadyOpen = transcriptPanel != null
                && transcriptPanel.getVisibility() == View.VISIBLE;
        showTranscriptPanel(true);
        if (!alreadyOpen || currentTranscript == null) {
            loadTranscriptPanelContent();
        } else {
            // Panel is already open and may have a stale transcript/selection;
            // refresh to match the newly selected clip.
            loadTranscriptPanelContent();
        }
    }

    /** Decides whether the transcript panel targets the selected audio clip or video clip. */
    private void resolveTranscriptTarget() {
        transcriptIsForAudio = false;
        transcriptAudioIndex = -1;
        if (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size()) {
            AudioClip audioClip = project.getTimeline().getAudioClips()
                    .get(editorTimeline.getSelectedAudioIndex());
            if (audioClip != null) {
                transcriptIsForAudio = true;
                transcriptAudioIndex = editorTimeline.getSelectedAudioIndex();
            }
        }
    }

    /**
     * Tell the transcript panel which slice of the source the CURRENT clip owns, so the rest
     * of the source (the sibling clips a split produced) draws dimmed and reads as "elsewhere
     * in this recording, tap to go there". Every clip cut from one source keeps the whole
     * source transcript, so without this the panel gives no clue where the current clip ends.
     *
     * <p>Windows by the clip whose transcript is actually on screen: usually the selected
     * clip, but if the selection has moved to a clip that has no transcript of its own the
     * panel still shows the previous clip's, and windowing by the new selection would dim an
     * unrelated source's words at random.</p>
     */
    private void applyTranscriptClipWindow() {
        if (transcriptView == null) return;
        if (transcriptIsForAudio) {
            java.util.List<AudioClip> audio = project.getTimeline().getAudioClips();
            if (transcriptAudioIndex >= 0 && transcriptAudioIndex < audio.size()) {
                AudioClip ac = audio.get(transcriptAudioIndex);
                if (ac != null) {
                    transcriptView.setClipWindow(ac.getInPointMs(), ac.getOutPointMs());
                    return;
                }
            }
            transcriptView.clearClipWindow();
            return;
        }
        Clip owner = getSelectedClip();
        if (owner == null || currentTranscript == null
                || owner.getActiveNamedTranscript() == null
                || owner.getActiveNamedTranscript().transcript != currentTranscript) {
            // Fall back to the clip the displayed transcript was bound from.
            owner = null;
            Timeline tl = project.getTimeline();
            if (transcriptClipId != null) {
                for (int i = 0; i < tl.getClipCount(); i++) {
                    Clip c = tl.getClip(i);
                    if (c != null && transcriptClipId.equals(c.getId())) { owner = c; break; }
                }
            }
        }
        if (owner == null) {
            transcriptView.clearClipWindow();
            return;
        }
        transcriptView.setClipWindow(owner.getInPointMs(), owner.getOutPointMs());
    }

    /** Loads the transcript (or model picker) for the current target without animating the panel. */
    private void loadTranscriptPanelContent() {
        resolveTranscriptTarget();

        if (transcriptIsForAudio && transcriptAudioIndex >= 0
                && transcriptAudioIndex < project.getTimeline().getAudioClips().size()) {
            AudioClip audioClip = project.getTimeline().getAudioClips().get(transcriptAudioIndex);
            if (audioClip == null) return;
            if (audioClip.hasTranscript()) {
                currentTranscript = audioClip.getTranscript();
                transcriptClipId = audioClip.getId();
            }
            refreshTranscriptVersionBar();
            if (currentTranscript != null && audioClip.getId().equals(transcriptClipId)) {
                transcriptModelChoice.setVisibility(View.GONE);
                transcriptProgress.setVisibility(View.GONE);
                transcriptView.setVisibility(View.VISIBLE);
                transcriptView.setTranscript(currentTranscript);
                applyTranscriptClipWindow();
                return;
            }
        } else {
            Clip clip = getSelectedClip();
            if (clip == null) return;
            if (clip.hasTranscript()) {
                currentTranscript = clip.getTranscript();
                transcriptClipId = clip.getId();
            }
            refreshTranscriptVersionBar();
            if (currentTranscript != null && clip.getId().equals(transcriptClipId)) {
                transcriptModelChoice.setVisibility(View.GONE);
                transcriptProgress.setVisibility(View.GONE);
                transcriptView.setVisibility(View.VISIBLE);
                transcriptView.setTranscript(currentTranscript);
                applyTranscriptClipWindow();
                return;
            }
        }

        // G4: before falling back to model picker, scan for existing transcripts
        // in the project — if any exist, show a picker so the user can reach them.
        if (!showTranscriptPicker()) {
            // No transcripts exist in the project at all — fall back to model picker
            transcriptProgress.setVisibility(View.GONE);
            transcriptView.setVisibility(View.GONE);
            transcriptModelChoice.setVisibility(View.VISIBLE);
            updateModelChoiceReadyLabels();
        }
    }

    /** G4 — show a picker of all clips in the project that have transcripts.
     * Returns true if a picker was shown (i.e. at least one transcript exists),
     * false if no transcripts exist in the project (falls back to model picker). */
    private boolean showTranscriptPicker() {
        if (project == null) return false;
        java.util.List<com.fadcam.ui.faditor.model.Clip> clips = project.getTimeline().getClips();
        java.util.List<com.fadcam.ui.faditor.model.AudioClip> audioClips = project.getTimeline().getAudioClips();
        java.util.ArrayList<String> labels = new java.util.ArrayList<>();
        java.util.ArrayList<Object> targets = new java.util.ArrayList<>();
        // Video clips
        for (int i = 0; i < clips.size(); i++) {
            com.fadcam.ui.faditor.model.Clip c = clips.get(i);
            if (c == null || !c.hasTranscript()) continue;
            String label = formatTranscriptEntry(c, c.getId().equals(transcriptClipId) && !transcriptIsForAudio);
            labels.add(label);
            targets.add(c);
        }
        // Audio clips
        for (int i = 0; i < audioClips.size(); i++) {
            com.fadcam.ui.faditor.model.AudioClip ac = audioClips.get(i);
            if (ac == null || !ac.hasTranscript()) continue;
            String label = formatTranscriptEntry(ac, ac.getId().equals(transcriptClipId) && transcriptIsForAudio);
            labels.add(label);
            targets.add(ac);
        }
        if (labels.isEmpty()) return false;
        // Sort by timeline position
        java.util.ArrayList<Long> sortKeys = new java.util.ArrayList<>();
        for (Object t : targets) {
            if (t instanceof com.fadcam.ui.faditor.model.Clip) {
                com.fadcam.ui.faditor.model.Clip c = (com.fadcam.ui.faditor.model.Clip) t;
                int idx = clips.indexOf(c);
                long pos = (idx >= 0) ? project.getTimeline().getClipStartMs(idx) + c.getInPointMs() : 0;
                sortKeys.add(pos);
            } else if (t instanceof com.fadcam.ui.faditor.model.AudioClip) {
                com.fadcam.ui.faditor.model.AudioClip ac = (com.fadcam.ui.faditor.model.AudioClip) t;
                long pos = ac.getOffsetMs() + ac.getInPointMs();
                sortKeys.add(pos);
            } else {
                sortKeys.add(0L);
            }
        }
        // Simple insertion sort by position
        for (int i = 1; i < labels.size(); i++) {
            long key = sortKeys.get(i);
            String label = labels.get(i);
            Object target = targets.get(i);
            int j = i - 1;
            while (j >= 0 && sortKeys.get(j) > key) {
                sortKeys.set(j + 1, sortKeys.get(j));
                labels.set(j + 1, labels.get(j));
                targets.set(j + 1, targets.get(j));
                j--;
            }
            sortKeys.set(j + 1, key);
            labels.set(j + 1, label);
            targets.set(j + 1, target);
        }
        // Build dialog
        final int[] selectedIdx = {0};
        final java.util.List<Object> finalTargets = targets;
        com.google.android.material.dialog.MaterialAlertDialogBuilder builder = new com.google.android.material.dialog.MaterialAlertDialogBuilder(this);
        builder.setTitle("Select a transcript");
        builder.setSingleChoiceItems(labels.toArray(new String[0]), -1, (dialog, which) -> selectedIdx[0] = which);
        builder.setPositiveButton(android.R.string.ok, (dialog, which) -> {
            Object target = finalTargets.get(selectedIdx[0]);
            if (target instanceof com.fadcam.ui.faditor.model.Clip) {
                com.fadcam.ui.faditor.model.Clip c = (com.fadcam.ui.faditor.model.Clip) target;
                transcriptIsForAudio = false;
                transcriptClipId = c.getId();
                transcriptAudioIndex = -1;
                currentTranscript = c.getTranscript();
            } else if (target instanceof com.fadcam.ui.faditor.model.AudioClip) {
                com.fadcam.ui.faditor.model.AudioClip ac = (com.fadcam.ui.faditor.model.AudioClip) target;
                transcriptIsForAudio = true;
                transcriptAudioIndex = project.getTimeline().getAudioClips().indexOf(ac);
                transcriptClipId = ac.getId();
                currentTranscript = ac.getTranscript();
            }
            if (transcriptView != null) transcriptView.setTranscript(currentTranscript);
            applyTranscriptClipWindow();
            transcriptView.invalidate();
            scheduleAutoSave();
            android.widget.Toast.makeText(this, "Transcript loaded", android.widget.Toast.LENGTH_SHORT).show();
        });
        builder.setNegativeButton(android.R.string.cancel, null);
        builder.show();
        return true;
    }

    /** Build a human-readable label for a transcript entry.
     * Format: "MM:SS  filename  —  Engine"
     * If this is the currently shown transcript, prefix with "● " */
    private String formatTranscriptEntry(Object target, boolean isCurrent) {
        String sourceName = "unknown";
        long positionMs = 0;
        String engine = "";
        if (target instanceof com.fadcam.ui.faditor.model.Clip) {
            com.fadcam.ui.faditor.model.Clip c = (com.fadcam.ui.faditor.model.Clip) target;
            sourceName = getSourceFileName(c.getSourceUri());
            // Clip position on timeline = clipStartMs (from timeline) + inPointMs (trim start)
            int clipIdx = project.getTimeline().getClips().indexOf(target);
            long clipStartMs = (clipIdx >= 0) ? project.getTimeline().getClipStartMs(clipIdx) : 0;
            positionMs = clipStartMs + c.getInPointMs();
            com.fadcam.ui.faditor.transcript.NamedTranscript nt = c.getActiveNamedTranscript();
            if (nt != null) engine = nt.engine;
        } else if (target instanceof com.fadcam.ui.faditor.model.AudioClip) {
            com.fadcam.ui.faditor.model.AudioClip ac = (com.fadcam.ui.faditor.model.AudioClip) target;
            sourceName = getSourceFileName(ac.getSourceUri());
            positionMs = ac.getOffsetMs() + ac.getInPointMs();
            com.fadcam.ui.faditor.transcript.NamedTranscript nt = ac.getActiveNamedTranscript();
            if (nt != null) engine = nt.engine;
        }
        String timeStr = formatMsShort(positionMs);
        String label = timeStr + "  " + sourceName + "  —  " + engine;
        if (isCurrent) label = "● " + label;
        return label;
    }

    /** Get filename from a URI (last path segment). */
    private String getSourceFileName(Uri uri) {
        if (uri == null) return "unknown";
        String path = uri.getPath();
        if (path == null) return uri.toString();
        int idx = path.lastIndexOf('/');
        return (idx >= 0 && idx + 1 < path.length()) ? path.substring(idx + 1) : path;
    }

    /** Format milliseconds as MM:SS or H:MM:SS. */
    private String formatMsShort(long ms) {
        if (ms < 0) ms = 0;
        long totalSec = ms / 1000;
        long h = totalSec / 3600;
        long m = (totalSec % 3600) / 60;
        long s = totalSec % 60;
        if (h > 0) return String.format(java.util.Locale.US, "%d:%02d:%02d", h, m, s);
        return String.format(java.util.Locale.US, "%02d:%02d", m, s);
    }

    /** Tag already-downloaded models in the picker so the choice is informed. */
    private void updateModelChoiceReadyLabels() {
        if (transcriptionEngine == null || transcriptModelChoice == null) return;
        markModelReady(R.id.transcript_model_fast,
                com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType.FAST);
        markModelReady(R.id.transcript_model_accurate,
                com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType.ACCURATE);
        markModelReady(R.id.transcript_model_whisper,
                com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType.WHISPER_BASE_EN);
    }

    private void markModelReady(int rowId,
            @NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type) {
        View row = findViewById(rowId);
        if (row == null) return;
        boolean ready = transcriptionEngine.isModelReady(type);
        // A downloaded model gets a subtle highlight so the user knows it's instant.
        row.setAlpha(ready ? 1f : 0.85f);
    }

    /** Download (if needed) the chosen model and transcribe the selected clip. */
    private void startTranscription(
            @NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type) {
        startTranscription(type, null);
    }

    /**
     * Same as {@link #startTranscription(com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType)},
     * but invokes {@code onDone} once this run finishes (success or error) —
     * used by {@link #runNextQueuedTranscription()} to chain multiple
     * engines sequentially against the "Transcribe this video?" prompt
     * (Feature A) without running them concurrently.
     */
    /**
     * Mini-map transcription-meter colour for a model, so several queued runs are told apart at
     * a glance. Deliberately NOT the object palette: this is a transient progress meter, and
     * reusing an object hue would read as "there is a sprite/text object here".
     */
    private int transcribeMeterColor(
            @NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type) {
        switch (type) {
            case FAST:     return 0xFF4CAF50;   // green  — quick pass, best timing
            case ACCURATE: return 0xFFFFC107;   // amber  — slower, better words
            default:       return 0xFF7E57C2;   // violet — Whisper, slowest, best words
        }
    }

    private void startTranscription(
            @NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type,
            @Nullable Runnable onDone) {
        boolean isAudio = transcriptIsForAudio && transcriptAudioIndex >= 0
                && transcriptAudioIndex < project.getTimeline().getAudioClips().size();
        Clip clip = null;
        AudioClip audioClip = null;
        if (isAudio) {
            audioClip = project.getTimeline().getAudioClips().get(transcriptAudioIndex);
        } else {
            clip = getSelectedClip();
        }
        if (clip == null && audioClip == null) return;

        final Clip fClip = clip;
        final AudioClip fAudioClip = audioClip;
        // Captured NOW: the mini-map meter is keyed by segment index, and the selection can
        // move while a run is in flight (transcription is serial and long). Reading
        // selectedClipIndex from inside the callback would paint the meter on whatever clip the
        // user had wandered to.
        final int fSegmentIndex = isAudio ? -1 : selectedClipIndex;

        transcriptModelChoice.setVisibility(View.GONE);
        // G6: keep existing transcript readable while transcribing - progress overlays, does not replace
        if (currentTranscript != null && !currentTranscript.isEmpty() && transcriptView.getVisibility() == View.VISIBLE) {
            // keep transcriptView visible with current content
        } else {
            transcriptView.setVisibility(View.GONE);
            transcriptView.setTranscript(null);
        }
        transcriptProgress.setVisibility(View.VISIBLE);
        transcriptProgressText.setText(R.string.faditor_transcript_working);
        addActiveTranscription(type);
        // Foreground service + wake lock, so the run survives the editor closing and the screen
        // going off. AIJobService already exists for exactly this ("long tasks (transcription,
        // silence detection...)") — it simply had never been wired to transcription, which is
        // why a run silently died with the Activity.
        com.fadcam.ui.faditor.ai.AIJobService.start(
                getApplicationContext(), "Transcribing (" + type.label + ")");

        final String clipId = isAudio ? audioClip.getId() : clip.getId();
        final Uri sourceUri = isAudio ? audioClip.getSourceUri() : clip.getSourceUri();
        final long inMs = isAudio ? audioClip.getInPointMs() : clip.getInPointMs();
        final long outMs = isAudio ? audioClip.getOutPointMs() : clip.getOutPointMs();
        // Create a new transcript version for this run (the user can keep a fast
        // Vosk pass for editing AND a Whisper pass for captions, side by side).
        String engine = type.engine
                == com.fadcam.ui.faditor.transcript.TranscriptionEngine.Engine.WHISPER
                ? "whisper" : "vosk";
        com.fadcam.ui.faditor.transcript.NamedTranscript version =
                new com.fadcam.ui.faditor.transcript.NamedTranscript(
                        type.label, engine,
                        new com.fadcam.ui.faditor.transcript.Transcript());
        if (isAudio) {
            audioClip.addTranscript(version);
        } else {
            clip.addTranscript(version);
        }
        final String versionId = version.id;
        currentTranscript = version.transcript;
        transcriptClipId = clipId;
        refreshTranscriptVersionBar();

        transcriptionEngine.transcribe(sourceUri, inMs, outMs, type,
                new com.fadcam.ui.faditor.transcript.TranscriptionEngine.Callback() {
                    @Override
                    public void onProgress(@NonNull String status, float fraction) {
                        // The run outlives the editor now, so every callback must tolerate a
                        // destroyed Activity. Keep the SERVICE notification updated regardless —
                        // that is the only progress the user can see once the editor is gone.
                        com.fadcam.ui.faditor.ai.AIJobService.update(getApplicationContext(),
                                "Transcribing (" + type.label + ") — " + status,
                                fraction >= 0f ? (int) (fraction * 100) : -1);
                        if (isFinishing() || isDestroyed()) return;
                        transcriptProgressText.setText(status);
                        updateTranscriptionProgress(type, status, fraction);
                        // Mirror progress onto the mini-map block for THIS clip. Transcription
                        // runs in series and a long clip on the Accurate model takes tens of
                        // minutes; without this the editor looks idle and the run gets closed
                        // out from under itself (lost a 20-minute run this way, 2026-07-28).
                        if (!isAudio && editorTimeline != null) {
                            editorTimeline.setSegmentTranscribing(
                                    fSegmentIndex, fraction, transcribeMeterColor(type));
                        }
                        if (transcriptProgressBar != null) {
                            if (fraction >= 0f) {
                                transcriptProgressBar.setIndeterminate(false);
                                transcriptProgressBar.setProgress(
                                        Math.max(0, Math.min(100, (int) (fraction * 100))));
                            } else {
                                transcriptProgressBar.setIndeterminate(true);
                            }
                        }
                    }

                    @Override
                    public void onPartial(@NonNull com.fadcam.ui.faditor.transcript.Transcript t) {
                        // Model update is safe after teardown; the UI below is not.
                        if (isFinishing() || isDestroyed()) {
                            updateTranscriptVersion(clipId, versionId, t);
                            return;
                        }
                        if (updateTranscriptVersion(clipId, versionId, t)) {
                            currentTranscript = t;
                            transcriptClipId = clipId;
                            if (transcriptView != null) {
                                transcriptView.setVisibility(View.VISIBLE);
                                transcriptView.setTranscript(t);
                            }
                            if (isAudio && fAudioClip != null) {
                                editorTimeline.setAudioClipTranscript(transcriptAudioIndex, t);
                            }
                            scheduleAutoSave();
                        }
                    }

                    @Override
                    public void onResult(@NonNull com.fadcam.ui.faditor.transcript.Transcript t) {
                        finishTranscription(type);
                        if (activeTranscriptionModels.isEmpty()) {
                            com.fadcam.ui.faditor.ai.AIJobService.stop(getApplicationContext());
                        }
                        if (isFinishing() || isDestroyed()) {
                            // The editor is gone but the work is real: fold the result into the
                            // model and persist it directly, or a completed run would be thrown
                            // away at the finish line — the very thing this change prevents.
                            if (updateTranscriptVersion(clipId, versionId, t) && project != null
                                    && projectStorage != null) {
                                projectStorage.save(project);
                                FLog.i(TAG, "Transcription finished after the editor closed — saved");
                            }
                            if (transcriptionEngine != null
                                    && activeTranscriptionModels.isEmpty()) {
                                transcriptionEngine.shutdown();
                            }
                            return;
                        }
                        transcriptProgress.setVisibility(View.GONE);
                        if (!isAudio && editorTimeline != null) {
                            editorTimeline.clearSegmentTranscribing(fSegmentIndex);
                        }
                        if (t.isEmpty()) {
                            Toast.makeText(FaditorEditorActivity.this,
                                    R.string.faditor_transcript_empty, Toast.LENGTH_SHORT).show();
                        }
                        if (updateTranscriptVersion(clipId, versionId, t)) {
                            // Re-running the same model REPLACES its previous run
                            // instead of stacking another copy: drop older versions
                            // of the same engine+label that carry no user edits.
                            // (Edited/active versions are never removed — see
                            // TranscriptDedup's rule.)
                            if (isAudio && fAudioClip != null) {
                                com.fadcam.ui.faditor.transcript.TranscriptDedup
                                        .dedupAudioClip(fAudioClip, true);
                            } else if (fClip != null) {
                                com.fadcam.ui.faditor.transcript.TranscriptDedup
                                        .dedupClip(fClip, true);
                            }
                            currentTranscript = t;
                            transcriptClipId = clipId;
                            transcriptView.setTranscript(t);
                            // Sync to timeline
                            if (isAudio && fAudioClip != null) {
                                editorTimeline.setAudioClipTranscript(transcriptAudioIndex, t);
                            } else {
                                syncTimelineTranscript();
                            }
                            refreshTranscriptVersionBar();
                            saveProjectNow();
                        }
                        if (onDone != null) onDone.run();
                    }

                    @Override
                    public void onError(@NonNull String message) {
                        finishTranscription(type);
                        if (activeTranscriptionModels.isEmpty()) {
                            com.fadcam.ui.faditor.ai.AIJobService.stop(getApplicationContext());
                        }
                        if (isFinishing() || isDestroyed()) {
                            if (transcriptionEngine != null
                                    && activeTranscriptionModels.isEmpty()) {
                                transcriptionEngine.shutdown();
                            }
                            return;
                        }
                        transcriptProgress.setVisibility(View.GONE);
                        if (!isAudio && editorTimeline != null) {
                            editorTimeline.clearSegmentTranscribing(fSegmentIndex);
                        }
                        if (isAudio && fAudioClip != null) {
                            int vi = indexOfVersion(fAudioClip, versionId);
                            if (vi >= 0 && fAudioClip.getTranscripts().get(vi).transcript.isEmpty()) {
                                fAudioClip.removeTranscript(vi);
                            }
                        } else if (fClip != null) {
                            int vi = indexOfVersion(fClip, versionId);
                            if (vi >= 0 && fClip.getTranscripts().get(vi).transcript.isEmpty()) {
                                fClip.removeTranscript(vi);
                            }
                        }
                        if (currentTranscript == null || currentTranscript.isEmpty()) {
                            transcriptModelChoice.setVisibility(View.VISIBLE);
                        }
                        refreshTranscriptVersionBar();
                        Toast.makeText(FaditorEditorActivity.this,
                                getString(R.string.faditor_transcript_error, message),
                                Toast.LENGTH_LONG).show();
                        if (onDone != null) onDone.run();
                    }
                });
    }

    private void addActiveTranscription(@NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type) {
        Integer count = activeTranscriptionModels.get(type);
        activeTranscriptionModels.put(type, count == null ? 1 : count + 1);
        updateTranscriptionStatusUI();
    }

    private void finishTranscription(@NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type) {
        Integer count = activeTranscriptionModels.get(type);
        if (count == null || count <= 1) {
            activeTranscriptionModels.remove(type);
        } else {
            activeTranscriptionModels.put(type, count - 1);
        }
        updateTranscriptionStatusUI();
    }

    private void updateTranscriptionProgress(@NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type,
                                             @NonNull String status,
                                             float fraction) {
        runOnUiThread(() -> {
            updateTranscriptionStatusUI(status, fraction);
            if (transcriptProgressBar != null) {
                if (fraction >= 0f) {
                    transcriptProgressBar.setIndeterminate(false);
                    transcriptProgressBar.setProgress(Math.max(0, Math.min(100, (int) (fraction * 100))));
                } else {
                    transcriptProgressBar.setIndeterminate(true);
                }
            }
        });
    }

    private void updateTranscriptionStatusUI() {
        updateTranscriptionStatusUI(null, -1f);
    }

    private void updateTranscriptionStatusUI(@Nullable String status, float fraction) {
        if (activeTranscriptionModels.isEmpty()) {
            if (transcriptStatusBadge != null) {
                transcriptStatusBadge.setVisibility(View.GONE);
                transcriptStatusBadge.setAlpha(1f);
            }
            if (transcriptGlobalProgressBar != null) transcriptGlobalProgressBar.setVisibility(View.GONE);
            if (toolTranscript != null) {
                toolTranscript.setAlpha(1f);
                toolTranscript.setForeground(null);
            }
            TextView icon = findViewById(R.id.tool_transcript_icon);
            TextView label = findViewById(R.id.tool_transcript_label);
            if (icon != null) icon.setTextColor(0xFF888888);
            if (label != null) label.setTextColor(0xFF888888);
            if (transcriptionPulseAnimator != null) {
                transcriptionPulseAnimator.cancel();
                transcriptionPulseAnimator = null;
            }
            return;
        }
        List<com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType> models =
                new ArrayList<>(activeTranscriptionModels.keySet());
        com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType pulseModel =
                models.get(transcriptionPulseIndex % models.size());
        int color = modelAccentColor(pulseModel);
        String label = activeTranscriptionModels.size() == 1
                ? "Transcribing " + pulseModel.label
                : "Transcribing " + models.size() + " engines";
        if (status != null && !status.isEmpty()) label = status;
        if (transcriptStatusBadge != null) {
            transcriptStatusBadge.setVisibility(View.VISIBLE);
            transcriptStatusBadge.setText(label);
            transcriptStatusBadge.setTextColor(color);
            transcriptStatusBadge.setBackgroundColor(combineColorWithAlpha(color, 0x2A));
        }
        if (transcriptGlobalProgressBar != null) {
            transcriptGlobalProgressBar.setVisibility(View.VISIBLE);
            if (fraction >= 0f) {
                transcriptGlobalProgressBar.setIndeterminate(false);
                transcriptGlobalProgressBar.setProgress(Math.max(0, Math.min(100, (int) (fraction * 100))));
            } else {
                transcriptGlobalProgressBar.setIndeterminate(true);
            }
        }
        TextView icon = findViewById(R.id.tool_transcript_icon);
        TextView transcriptLabel = findViewById(R.id.tool_transcript_label);
        if (icon != null) icon.setTextColor(color);
        if (transcriptLabel != null) transcriptLabel.setTextColor(color);
        startTranscriptionPulse(color);
    }

    private void startTranscriptionPulse(int color) {
        if (transcriptionPulseAnimator != null) return;
        transcriptionPulseAnimator = ValueAnimator.ofFloat(0.45f, 1f);
        transcriptionPulseAnimator.setDuration(720);
        transcriptionPulseAnimator.setRepeatMode(ValueAnimator.REVERSE);
        transcriptionPulseAnimator.setRepeatCount(ValueAnimator.INFINITE);
        transcriptionPulseAnimator.addUpdateListener(animation -> {
            float alpha = (float) animation.getAnimatedValue();
            if (toolTranscript != null) toolTranscript.setAlpha(alpha);
            if (transcriptStatusBadge != null) transcriptStatusBadge.setAlpha(alpha);
            if (transcriptGlobalProgressBar != null) transcriptGlobalProgressBar.setAlpha(alpha);
        });
        transcriptionPulseAnimator.start();
        new Handler(Looper.getMainLooper()).postDelayed(() -> {
            if (!activeTranscriptionModels.isEmpty()) {
                transcriptionPulseIndex = (transcriptionPulseIndex + 1) % activeTranscriptionModels.size();
                updateTranscriptionStatusUI();
            }
        }, 720);
    }

    private int modelAccentColor(@NonNull com.fadcam.ui.faditor.transcript.TranscriptionEngine.ModelType type) {
        switch (type) {
            case FAST:
                return 0xFF42A5F5;
            case ACCURATE:
                return 0xFF4CAF50;
            case WHISPER_BASE_EN:
                return 0xFFFFC107;
            default:
                return 0xFF4CAF50;
        }
    }

    private int combineColorWithAlpha(int color, int alpha) {
        return (alpha & 0xFF) << 24 | (color & 0x00FFFFFF);
    }

    /** Index of the version with this id in the clip, or -1. */
    private int indexOfVersion(@NonNull Clip clip, @NonNull String versionId) {
        java.util.List<com.fadcam.ui.faditor.transcript.NamedTranscript> vs =
                clip.getTranscripts();
        for (int i = 0; i < vs.size(); i++) {
            if (vs.get(i).id.equals(versionId)) return i;
        }
        return -1;
    }

    private int indexOfVersion(@NonNull AudioClip clip, @NonNull String versionId) {
        java.util.List<com.fadcam.ui.faditor.transcript.NamedTranscript> vs =
                clip.getTranscripts();
        for (int i = 0; i < vs.size(); i++) {
            if (vs.get(i).id.equals(versionId)) return i;
        }
        return -1;
    }

    /** Replace the words of a transcript version (during/after a run). */
    private boolean updateTranscriptVersion(@NonNull String clipId,
            @NonNull String versionId,
            @NonNull com.fadcam.ui.faditor.transcript.Transcript t) {
        Clip clip = findClipById(clipId);
        if (clip != null) {
            int vi = indexOfVersion(clip, versionId);
            if (vi < 0) return false;
            clip.getTranscripts().get(vi).transcript = t;
            clip.setActiveTranscriptIndex(vi);
            return true;
        }
        // Try audio clip
        AudioClip ac = findAudioClipById(clipId);
        if (ac != null) {
            int vi = indexOfVersion(ac, versionId);
            if (vi < 0) return false;
            ac.getTranscripts().get(vi).transcript = t;
            ac.setActiveTranscriptIndex(vi);
            return true;
        }
        return false;
    }

    /**
     * Rebuild the row of transcript-version chips above the transcript view.
     * Each chip switches the active version; a "+" chip adds another pass.
     */
    private void refreshTranscriptVersionBar() {
        if (transcriptVersionBar == null) return;
        transcriptVersionBar.removeAllViews();
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        java.util.List<com.fadcam.ui.faditor.transcript.NamedTranscript> versions;
        int active;
        if (preferAudio) {
            AudioClip ac = project.getTimeline().getAudioClips().get(editorTimeline.getSelectedAudioIndex());
            versions = ac == null ? java.util.Collections.emptyList() : ac.getTranscripts();
            active = ac == null ? -1 : ac.getActiveTranscriptIndex();
        } else {
            Clip clip = getSelectedClip();
            versions = clip == null ? java.util.Collections.emptyList() : clip.getTranscripts();
            active = clip == null ? -1 : clip.getActiveTranscriptIndex();
        }
        if (versions.isEmpty()) {
            if (transcriptVersionScroll != null) transcriptVersionScroll.setVisibility(View.GONE);
            return;
        }
        if (transcriptVersionScroll != null) transcriptVersionScroll.setVisibility(View.VISIBLE);
        float density = getResources().getDisplayMetrics().density;
        int pad = (int) (8 * density);
        for (int i = 0; i < versions.size(); i++) {
            final int idx = i;
            com.fadcam.ui.faditor.transcript.NamedTranscript v = versions.get(i);
            TextView chip = new TextView(this);
            boolean isActive = i == active;
            // Whisper chips green-tinted, Vosk blue-tinted; active = filled dot.
            int accent = "whisper".equals(v.engine) ? 0xFFFFC107 : 0xFF42A5F5;
            chip.setText((isActive ? "● " : "") + v.label);
            chip.setTextColor(isActive ? accent : 0xFF999999);
            chip.setTextSize(12);
            chip.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            chip.setPadding(pad, pad / 2, pad, pad / 2);
            chip.setBackgroundResource(R.drawable.floating_button_item_bg);
            chip.setAlpha(isActive ? 1f : 0.75f);
            android.widget.LinearLayout.LayoutParams lp =
                    new android.widget.LinearLayout.LayoutParams(
                            android.widget.LinearLayout.LayoutParams.WRAP_CONTENT,
                            android.widget.LinearLayout.LayoutParams.WRAP_CONTENT);
            lp.rightMargin = pad / 2;
            chip.setLayoutParams(lp);
            chip.setOnClickListener(view -> switchTranscriptVersion(idx));
            chip.setOnLongClickListener(view -> { showTranscriptVersionMenu(idx); return true; });
            transcriptVersionBar.addView(chip);
        }
        // "+ New" chip to add another pass via the model picker.
        TextView add = new TextView(this);
        add.setText("+");
        add.setTextColor(0xFF4CAF50);
        add.setTextSize(14);
        add.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
        add.setPadding(pad + pad / 2, pad / 2, pad + pad / 2, pad / 2);
        add.setBackgroundResource(R.drawable.floating_button_item_bg);
        add.setOnClickListener(view -> {
            transcriptView.setVisibility(View.GONE);
            transcriptModelChoice.setVisibility(View.VISIBLE);
            updateModelChoiceReadyLabels();
        });
        transcriptVersionBar.addView(add);
    }

    /** Switch which transcript version is active (panel + captions follow). */
    private void switchTranscriptVersion(int index) {
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        if (preferAudio) {
            AudioClip ac = project.getTimeline().getAudioClips().get(editorTimeline.getSelectedAudioIndex());
            if (ac == null) return;
            ac.setActiveTranscriptIndex(index);
            currentTranscript = ac.getTranscript();
            transcriptClipId = ac.getId();
            if (currentTranscript != null) {
                transcriptModelChoice.setVisibility(View.GONE);
                transcriptView.setVisibility(View.VISIBLE);
                transcriptView.setTranscript(currentTranscript);
                editorTimeline.setAudioClipTranscript(transcriptAudioIndex, currentTranscript);
                if (captionsActive && ac.getId().equals(audioCaptionClipId)) {
                    bindAudioCaptionData(ac);
                }
            }
        } else {
            Clip clip = getSelectedClip();
            if (clip == null) return;
            clip.setActiveTranscriptIndex(index);
            currentTranscript = clip.getTranscript();
            transcriptClipId = clip.getId();
            if (currentTranscript != null) {
                transcriptModelChoice.setVisibility(View.GONE);
                transcriptView.setVisibility(View.VISIBLE);
                transcriptView.setTranscript(currentTranscript);
                // The TAPE has to follow the selection too. The audio branch above already
                // pushes setAudioClipTranscript; this branch updated only the panel and the
                // captions, so switching version on a VIDEO clip left the timeline tape showing
                // the previously-active transcript — different words, different timings, and no
                // visible response to the picker (user-reported 2026-07-27). Full resync rather
                // than a single setSegmentTranscript: one transcript object is shared by every
                // clip of the same source, so a switch can affect more than the selected clip.
                syncTimelineTranscript();
                if (captionsActive && clip.getId().equals(captionClipId)) {
                    showCaptionsForClip(clip);
                }
            }
        }
        refreshTranscriptVersionBar();
        scheduleAutoSave();
    }

    /**
     * Long-press menu on a transcript version chip (JoyRaptor 2026-07-16): copy the transcript
     * out in three flavors, import timestamped text back in, or delete the version.
     * TODO(strings): hardcoded per the rebrand-freeze standing rule.
     */
    private void showTranscriptVersionMenu(int index) {
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        java.util.List<com.fadcam.ui.faditor.transcript.NamedTranscript> versions =
                preferAudio
                        ? project.getTimeline().getAudioClips()
                                .get(editorTimeline.getSelectedAudioIndex()).getTranscripts()
                        : (getSelectedClip() != null ? getSelectedClip().getTranscripts() : null);
        if (versions == null || index < 0 || index >= versions.size()) return;
        final com.fadcam.ui.faditor.transcript.Transcript tr = versions.get(index).transcript;

        String[] items = {
                "Copy text",
                "Copy with [mm:ss] stamps  —  simple, readable",
                "Copy as SRT  —  subtitle standard, works everywhere",
                "Copy word-level timing  —  exact per-word spans, as the app sees it",
                "Import timestamped text…",
                "Delete version…"
        };
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(versions.get(index).label)
                .setItems(items, (d, which) -> {
                    switch (which) {
                        case 0: copyToClipboard(
                                com.fadcam.ui.faditor.transcript.TranscriptIO.toPlainText(tr)); break;
                        case 1: copyToClipboard(
                                com.fadcam.ui.faditor.transcript.TranscriptIO.toStampedText(tr)); break;
                        case 2: copyToClipboard(
                                com.fadcam.ui.faditor.transcript.TranscriptIO.toSrt(tr)); break;
                        case 3: copyToClipboard(
                                com.fadcam.ui.faditor.transcript.TranscriptIO.toWordLevelText(tr)); break;
                        case 4: promptImportTimestampedText(); break;
                        case 5: confirmDeleteVersion(index); break;
                    }
                })
                .show();
    }

    /**
     * Mirror the transcript panel's search hits onto the timeline words tape
     * (JoyRaptor 2026-07-16): the same word indices highlight amber on the selected
     * clip's tape (or as taller amber marks at wide zoom).
     */
    private void pushSearchHitsToTimeline() {
        if (editorTimeline == null || transcriptView == null) return;
        Clip c = getSelectedClip();
        java.util.Set<Integer> hits = transcriptView.getSearchMatchSet();
        editorTimeline.setTranscriptSearchMatches(
                (c != null && !hits.isEmpty()) ? c.getId() : null,
                new java.util.HashSet<>(hits));
    }

    private void copyToClipboard(@NonNull String text) {
        android.content.ClipboardManager cm =
                (android.content.ClipboardManager) getSystemService(CLIPBOARD_SERVICE);
        cm.setPrimaryClip(android.content.ClipData.newPlainText("transcript", text));
        Toast.makeText(this, "Copied to clipboard", Toast.LENGTH_SHORT).show();
    }

    /** Paste SRT / WebVTT / [mm:ss]-stamped text → new transcript version on the selection. */
    private void promptImportTimestampedText() {
        final android.widget.EditText input = new android.widget.EditText(this);
        input.setHint("Paste SRT, WebVTT, or [mm:ss] stamped lines");
        input.setMinLines(6);
        input.setGravity(android.view.Gravity.TOP);
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle("Import timestamped text")
                .setView(input)
                .setNegativeButton(R.string.faditor_cancel, null)
                .setPositiveButton("Import", (d, w) -> {
                    com.fadcam.ui.faditor.transcript.Transcript parsed =
                            com.fadcam.ui.faditor.transcript.TranscriptIO.parse(
                                    input.getText().toString());
                    if (parsed == null) {
                        Toast.makeText(this,
                                "No timestamps found — expected SRT, VTT, or [mm:ss] lines",
                                Toast.LENGTH_LONG).show();
                        return;
                    }
                    com.fadcam.ui.faditor.transcript.NamedTranscript named =
                            new com.fadcam.ui.faditor.transcript.NamedTranscript(
                                    java.util.UUID.randomUUID().toString(),
                                    "Imported", "import", parsed);
                    boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                            && editorTimeline.getSelectedAudioIndex()
                                    < project.getTimeline().getAudioClips().size());
                    if (preferAudio) {
                        project.getTimeline().getAudioClips()
                                .get(editorTimeline.getSelectedAudioIndex()).addTranscript(named);
                    } else if (getSelectedClip() != null) {
                        getSelectedClip().addTranscript(named);
                    } else {
                        return;
                    }
                    currentTranscript = parsed;
                    if (transcriptView != null) {
                        transcriptView.setTranscript(parsed);
                        transcriptView.setVisibility(View.VISIBLE);
                    }
                    refreshTranscriptVersionBar();
                    saveProjectNow();
                    Toast.makeText(this, "Imported " + parsed.words.size() + " words",
                            Toast.LENGTH_SHORT).show();
                })
                .show();
    }

    private void confirmDeleteVersion(int index) {
        boolean preferAudio = (editorTimeline.getSelectedAudioIndex() >= 0
                && editorTimeline.getSelectedAudioIndex() < project.getTimeline().getAudioClips().size());
        java.util.List<com.fadcam.ui.faditor.transcript.NamedTranscript> versions;
        Runnable delete;
        if (preferAudio) {
            AudioClip ac = project.getTimeline().getAudioClips().get(editorTimeline.getSelectedAudioIndex());
            if (ac == null || index < 0 || index >= ac.getTranscripts().size()) return;
            versions = ac.getTranscripts();
            delete = () -> {
                ac.removeTranscript(index);
                currentTranscript = ac.getTranscript();
                if (currentTranscript != null) {
                    transcriptView.setTranscript(currentTranscript);
                } else {
                    transcriptView.setVisibility(View.GONE);
                    transcriptModelChoice.setVisibility(View.VISIBLE);
                    updateModelChoiceReadyLabels();
                }
                refreshTranscriptVersionBar();
                saveProjectNow();
            };
        } else {
            Clip clip = getSelectedClip();
            if (clip == null || index < 0 || index >= clip.getTranscripts().size()) return;
            versions = clip.getTranscripts();
            delete = () -> {
                clip.removeTranscript(index);
                currentTranscript = clip.getTranscript();
                if (currentTranscript != null) {
                    transcriptView.setTranscript(currentTranscript);
                } else {
                    transcriptView.setVisibility(View.GONE);
                    transcriptModelChoice.setVisibility(View.VISIBLE);
                    updateModelChoiceReadyLabels();
                }
                refreshTranscriptVersionBar();
                saveProjectNow();
            };
        }
        String label = versions.get(index).label;
        String title = getString(R.string.faditor_transcript_delete_version_title);
        String msg = getString(R.string.faditor_transcript_delete_version_msg, label);
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(title)
                .setMessage(msg)
                .setNegativeButton(R.string.faditor_cancel, null)
                .setPositiveButton(R.string.faditor_delete_confirm, (d, w) -> delete.run())
                .show();
    }

    /**
     * H1: the pillarbox slack the transcript drawer may claim, in px — the horizontal twin
     * of {@link #reflowPreviewUnderDrawer(int)}'s arithmetic. Half the drawer's width
     * re-centres the picture in what is left of the slot; clamped to the letterbox bars so
     * the picture's own edge never leaves the container. On a 16:9 project there is no
     * pillarbox slack and this returns 0 — opening the transcript then moves nothing,
     * exactly how the vertical version no-ops on 9:16.
     */
    private float transcriptDrawerShiftPx() {
        View container = findViewById(R.id.player_container);
        if (container == null) return 0f;
        int slotW = container.getWidth();
        if (slotW <= 0) return 0f;
        int videoW = 0;
        if (playerView != null && playerView.getVideoSurfaceView() != null) {
            videoW = playerView.getVideoSurfaceView().getWidth();
        }
        if (videoW <= 0) videoW = slotW;
        float slack = Math.max(0f, (slotW - videoW) / 2f);
        float drawerW = transcriptPanel.getWidth() > 0 ? transcriptPanel.getWidth()
                : transcriptPanel.getLayoutParams().width;
        if (drawerW <= 0) return 0f;
        return Math.min(drawerW / 2f, slack);
    }

    /**
     * H1: apply (or clear) the transcript reflow — container to −shift, panel + reopen tab
     * counter-shifted to hold station. One write-point so the open animation, the resize
     * handle's re-station and the layout-change recovery all agree.
     *
     * <p>Both translation axes are named on the container's animator: {@code View.animate()}
     * is ONE shared object per view, so naming only X would cancel an in-flight vertical
     * drawer reflow at its mid-flight value (audit 084b1bc5 #1).</p>
     *
     * @param animate true for the 220ms slide matching the drawer; false for instant
     *                re-stationing after a geometry change (resize handle, rotation).
     */
    private void applyTranscriptReflow(boolean animate) {
        View container = findViewById(R.id.player_container);
        if (container == null) return;
        float shift = transcriptPanelOpen ? transcriptDrawerShiftPx() : 0f;
        transcriptReflowShiftX = shift;
        android.view.animation.Interpolator decel =
                new android.view.animation.DecelerateInterpolator();
        if (animate) {
            container.animate().translationX(-shift).translationY(drawerReflowShiftY)
                    .scaleX(1f).scaleY(1f).setDuration(220).setInterpolator(decel).start();
        } else {
            container.animate().cancel();
            container.setTranslationX(-shift);
            // Keep the vertical writer's last target — not the view's possibly mid-flight value.
            container.setTranslationY(drawerReflowShiftY);
        }
        if (transcriptPanelOpen) {
            transcriptPanel.setTranslationX(shift);
            transcriptReopenTab.setTranslationX(shift);
        }
    }

    private void showTranscriptPanel(boolean show) {
        if (transcriptPanel == null) return;
        ViewGroup.LayoutParams lp = transcriptPanel.getLayoutParams();
        int screenW = getResources().getDisplayMetrics().widthPixels;
        if (lp.width < screenW * 0.20f) {
            lp.width = (int) (screenW * 0.60f);
            transcriptPanel.setLayoutParams(lp);
        }
        transcriptPanel.animate().cancel();
        boolean alreadyOpen = transcriptPanel.getVisibility() == View.VISIBLE && transcriptPanelOpen;
        if (show == alreadyOpen) return;
        // H1 (SPEC_20260824_HORIZONTAL_REFLOW): slide the picture into its own pillarbox
        // slack while the drawer is out. THE TRAP: transcript_panel is a CHILD of
        // player_container, so translating the container drags the drawer along with it.
        // Fix is counter-translation, NOT reparenting — reparenting would change z-order
        // against every overlay declared after it. The container gets -shift; the panel
        // and reopen tab get +shift so they hold station on screen. Because the panel's
        // own translationX IS its open/close slide property, the counter-shift is folded
        // INTO the slide endpoints: station = layout + shift, off-screen = layout + screenW.
        // TRANSLATE ONLY — never scale (§0 of the spec).
        if (show) {
            // Flag first: applyTranscriptReflow derives the shift only while "open".
            transcriptPanelOpen = true;
            applyTranscriptReflow(true);
            transcriptPanel.setVisibility(View.VISIBLE);
            transcriptPanel.setTranslationX(screenW);
            transcriptPanel.animate()
                    .translationX(transcriptReflowShiftX)
                    .setDuration(220)
                    .setInterpolator(new android.view.animation.DecelerateInterpolator())
                    .start();
            transcriptReopenTab.setVisibility(View.GONE);
            transcriptReopenTab.setTranslationX(transcriptReflowShiftX);
            updateTranscriptBreakButton();
        } else {
            transcriptPanelOpen = false;
            // The picture returns to centre while the drawer slides out; both axes named
            // (see applyTranscriptReflow) so neither cancels the other's tween.
            applyTranscriptReflow(true);
            transcriptPanel.animate()
                    .translationX(screenW)
                    .setDuration(180)
                    .setInterpolator(new android.view.animation.AccelerateInterpolator())
                    .withEndAction(() -> {
                        if (transcriptPanelOpen) return;
                        transcriptPanel.setVisibility(View.GONE);
                        transcriptReopenTab.setVisibility(
                                currentTranscript != null ? View.VISIBLE : View.GONE);
                        // Reset path: both counter-translated views return to station 0
                        // now that the container itself is back at 0.
                        transcriptPanel.setTranslationX(0f);
                        transcriptReopenTab.setTranslationX(0f);
                    })
                    .start();
        }
    }

    /**
     * Rebuild the selected clip's removed-span skip list from the struck words.
     * Non-destructive and live: preview skips these, the timeline draws them dark,
     * and export bakes them out. The clip stays a single editable unit.
     */
    private void syncRemovedSpansFromTranscript() {
        if (currentTranscript == null) return;
        Clip clip = getSelectedClip();
        com.fadcam.ui.faditor.model.AudioClip ac = null;
        boolean isAudio = false;
        if (clip != null && clip.getId().equals(transcriptClipId)) {
            isAudio = false;
        } else {
            if (project != null) {
                for (com.fadcam.ui.faditor.model.AudioClip c : project.getTimeline().getAudioClips()) {
                    if (c.getId().equals(transcriptClipId)) { ac = c; isAudio = true; break; }
                }
            }
            if (!isAudio) return;
        }

        // Pad each struck word slightly: Vosk timestamps a word's onset a touch
        // late, so without this the very start of the word ("the m of ma'am")
        // leaks through. Clamped to the clip's trim.
        long inMs = isAudio ? ac.getInPointMs() : clip.getInPointMs();
        long outMs = isAudio ? ac.getOutPointMs() : clip.getOutPointMs();
        List<long[]> raw = new ArrayList<>();
        for (com.fadcam.ui.faditor.transcript.TranscriptWord w : currentTranscript.words) {
            // Only words fully inside this clip's trim window contribute cuts (defensive: once the
            // transcript-windowing rework lands, a clip keeps the full source transcript). Mirrors
            // the timeline's word filter. See tasks/PLAN_transcript_windowing.md.
            if (w.startMs < inMs || w.endMs > outMs) continue;
            if (w.struck) {
                long s = Math.max(inMs, w.startMs - 70);
                long e = Math.min(outMs, w.endMs + 50);
                raw.add(new long[]{s, e});
            }
        }
        java.util.Collections.sort(raw, (a, b) -> Long.compare(a[0], b[0]));

        // Merge adjacent/overlapping struck spans into continuous regions.
        List<long[]> merged = new ArrayList<>();
        for (long[] s : raw) {
            if (!merged.isEmpty() && s[0] <= merged.get(merged.size() - 1)[1] + 80) {
                long[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], s[1]);
            } else {
                merged.add(new long[]{s[0], s[1]});
            }
        }
        if (isAudio) ac.setRemovedSpans(merged); else clip.setRemovedSpans(merged);
        editorTimeline.invalidate();
        refreshTotalTimeDisplay();
        scheduleAutoSave();
    }

    /**
     * "Commit" — finalise the transcript edits. They are already live on the
     * clip (non-destructive), so this just closes the panel; export will apply
     * them. The clip remains one unit, so the timeline isn't shredded with cuts.
     */
    private void commitTranscript() {
        showTranscriptPanel(false);
        transcriptReopenTab.setVisibility(
                currentTranscript != null ? View.VISIBLE : View.GONE);
        Toast.makeText(this, R.string.faditor_transcript_committed, Toast.LENGTH_SHORT).show();
    }

    /** Reflect the active word's forced-break state in the header toggle. */
    private void updateTranscriptBreakButton() {
        if (transcriptBreakBtn == null) return;
        int idx = transcriptView != null ? transcriptView.getActiveIndex() : -1;
        boolean enabled = idx >= 0 && currentTranscript != null
                && idx < currentTranscript.words.size();
        boolean active = enabled && currentTranscript.words.get(idx).forceLineBreakAfter;
        transcriptBreakBtn.setEnabled(enabled);
        transcriptBreakBtn.setAlpha(enabled ? 1f : 0.4f);
        transcriptBreakBtn.setTextColor(active ? 0xFF4DD0E1 : 0x80FFFFFF);
    }

    // ── Silence detection → yellow candidates → tap to cut ───────────

    private SilenceDetector silenceDetector;

    /** Toggle the yellow silence-candidate view; detect on first show. */
    private void toggleSilenceDetect() {
        if (editorTimeline.isShowSilence()) {
            removeDetectedGaps();
            return;
        }
        Clip clip = getSelectedClip();
        if (clip == null) return;
        if (clip.isImageClip()) {
            Toast.makeText(this, R.string.faditor_silence_image, Toast.LENGTH_SHORT).show();
            return;
        }
        if (inCropMode) exitCropMode(false);

        int pad = (int) (16 * getResources().getDisplayMetrics().density);
        android.widget.LinearLayout root = new android.widget.LinearLayout(this);
        root.setOrientation(android.widget.LinearLayout.VERTICAL);
        root.setPadding(pad, pad / 2, pad, 0);
        android.widget.TextView label = new android.widget.TextView(this);
        label.setText(R.string.faditor_silence_sensitivity);
        label.setTextColor(0xFFCCCCCC);
        root.addView(label);
        final android.widget.SeekBar seek = new android.widget.SeekBar(this);
        seek.setMax(100);
        seek.setProgress(50);
        root.addView(seek);
        android.widget.TextView preview = attachSilenceLivePreview(root, seek);

        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.faditor_silence_detect_title)
                .setMessage(R.string.faditor_silence_detect_desc)
                .setView(root)
                .setNegativeButton(android.R.string.cancel, null)
                .setPositiveButton(R.string.faditor_silence_detect_btn, (d, w) ->
                        runSilenceDetect(seek.getProgress() / 100f))
                .show();
        previewSilenceCandidates(0.5f, preview);
    }

    // ── C3: Fix audio — one-tap baked chain (highpass → afftdn → acompressor → loudnorm) ──
    private void fixSelectedAudio() {
        if (project == null) {
            Toast.makeText(this, "No project", Toast.LENGTH_SHORT).show();
            return;
        }
        // Resolve selected audio: prefer the audio-band selection, else the master clip's audio
        AudioClip clip = null;
        int selIdx = -1;
        if (editorTimeline != null) {
            try { selIdx = editorTimeline.getSelectedAudioIndex(); } catch (Exception ignored) {}
        }
        if (selIdx >= 0 && selIdx < project.getTimeline().getAudioClips().size()) {
            clip = project.getTimeline().getAudioClips().get(selIdx);
        }
        if (clip == null) {
            // Fallback: audio at playhead
            clip = findAudioClipAtTimelineMs(lastPlayheadAbsoluteMs);
        }
        if (clip == null) {
            Toast.makeText(this, "Select an audio clip first", Toast.LENGTH_SHORT).show();
            return;
        }
        final AudioClip target = clip;
        long startMs = target.getInPointMs();
        long endMs = target.getOutPointMs();
        if (endMs <= startMs) endMs = target.getSourceDurationMs();
        if (endMs <= startMs) {
            Toast.makeText(this, "Audio has no duration", Toast.LENGTH_SHORT).show();
            return;
        }
        // If already baked, the Clean tab's revert is the honest path — but Fix should still
        // be reachable via undo, not by stacking bakes. For now, allow re-bake and let the
        // BakedAudioCache's cache-hit handle it (it will be a no-op if already baked).
        java.io.File projectDir = projectStorage.projectDir(project.getId());
        com.fadcam.ui.faditor.audio.BakedAudioCache cache = new com.fadcam.ui.faditor.audio.BakedAudioCache(this);
        // Progress dialog (honest, not instant — §6.2 baked)
        android.app.ProgressDialog pd = new android.app.ProgressDialog(this);
        pd.setTitle("Fixing audio");
        pd.setMessage("Running Fix audio chain…");
        pd.setProgressStyle(android.app.ProgressDialog.STYLE_HORIZONTAL);
        pd.setMax(100);
        pd.setCancelable(false);
        pd.show();
        com.fadcam.ui.faditor.audio.BakedAudioCache.Request req =
                new com.fadcam.ui.faditor.audio.BakedAudioCache.Request(target.getSourceUri(), startMs, endMs, com.fadcam.ui.faditor.audio.BakedAudioCache.CHAIN_FIX);
        cache.bakeAsync(projectDir, req, fraction -> runOnUiThread(() -> {
            if (fraction >= 0) pd.setProgress((int) (fraction * 100));
            else pd.setIndeterminate(true);
        }), (result, error) -> runOnUiThread(() -> {
            pd.dismiss();
            if (result == null) {
                Toast.makeText(this, "Fix failed: " + (error != null ? error : "unknown"), Toast.LENGTH_LONG).show();
                return;
            }
            // Swap clip to baked file — one undo step (like Clean tab)
            String originalUri = target.getSourceUri().toString();
            String bakedPath = result.bakedFile.getAbsolutePath();
            String beforeUri = target.getSourceUri().toString();
            String beforeBakedUri = target.getBakedFromUri();
            String beforeBakedFile = target.getBakedFromFile();
            android.net.Uri bakedUri = android.net.Uri.fromFile(result.bakedFile);
            target.setSourceUri(bakedUri);
            target.setBakedFrom(originalUri, bakedPath);
            // Invalidate waveform (stale until re-extract) — keep old for now
            undoManager.recordAction(new com.fadcam.ui.faditor.undo.EditActions.LambdaAction(
                    "Fix audio",
                    () -> {
                        target.setSourceUri(bakedUri);
                        target.setBakedFrom(originalUri, bakedPath);
                        syncTimelineOverlays();
                        if (editorTimeline != null) editorTimeline.invalidate();
                        prepareAudioPlayer();
                        scheduleAutoSave();
                    },
                    () -> {
                        target.setSourceUri(android.net.Uri.parse(beforeUri));
                        target.setBakedFrom(beforeBakedUri, beforeBakedFile);
                        syncTimelineOverlays();
                        if (editorTimeline != null) editorTimeline.invalidate();
                        prepareAudioPlayer();
                        scheduleAutoSave();
                    }));
            syncTimelineOverlays();
            if (editorTimeline != null) editorTimeline.invalidate();
            prepareAudioPlayer();
            scheduleAutoSave();
            Toast.makeText(this, "Audio fixed — Revert in Clean tab", Toast.LENGTH_SHORT).show();
        }));
    }

